        const EMBEDDED_ASSETS = {};

        function normalizeAssetPath(path) {
            return String(path || '').replace(/^data:/, 'data:').startsWith('data:')
                ? String(path)
                : String(path || '').replace(/\\/g, '/').replace(/^\.\//, '').split('?')[0];
        }

        function getEmbeddedAsset(path) {
            const normalized = normalizeAssetPath(path);
            if (normalized.startsWith('data:')) return normalized;
            return EMBEDDED_ASSETS[normalized] || '';
        }

        function versionedAsset(path) {
            return getEmbeddedAsset(path) || window.DBZ_V6_ASSETS?.[normalizeAssetPath(path)] || `${path}?v=${encodeURIComponent(GAME_VERSION)}`;
        }

