        function getPartnerCollection(collectionId) {
            return PARTNER_COLLECTIONS.find(collection => collection.id === collectionId) || null;
        }

        function partnerCollectionComplete(char, collectionId) {
            const collection = getPartnerCollection(collectionId);
            if (!collection || !collection.ids.length) return false;
            const owned = new Set(getOwnedPartners(char));
            return collection.ids.every(id => owned.has(id));
        }


        const PARTNER_ID_ALIASES = {
            frieza_namek: 'frieza_final_form'
        };

        function migratePartnerId(partnerId) {
            return PARTNER_ID_ALIASES[partnerId] || partnerId;
        }

        function migratePartnerIdList(partnerIds = []) {
            return [...new Set((partnerIds || []).map(migratePartnerId))]
                .filter(id => PARTNER_ROSTER.some(p => p.id === id));
        }

        function makeVisualSvg(opts) {
            const svg = `
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 180" role="img" aria-label="${opts.label}">
                    <defs>
                        <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
                            <stop offset="0" stop-color="${opts.bg1}"/>
                            <stop offset="0.58" stop-color="${opts.bg2}"/>
                            <stop offset="1" stop-color="${opts.bg3 || '#090d15'}"/>
                        </linearGradient>
                    </defs>
                    <rect width="320" height="180" rx="18" fill="url(#bg)"/>
                    <path d="M18 146 C70 96, 102 170, 160 106 C214 48, 244 92, 302 30" fill="none" stroke="${opts.accent}" stroke-width="10" stroke-linecap="round" opacity="0.78"/>
                    <circle cx="245" cy="54" r="33" fill="${opts.accent}" opacity="0.18"/>
                    <circle cx="76" cy="112" r="45" fill="#fff" opacity="0.07"/>
                    <text x="26" y="62" fill="#ffffff" font-family="Arial Black, Arial, sans-serif" font-size="44">${opts.mark}</text>
                    <text x="26" y="142" fill="#ffffff" font-family="Trebuchet MS, Arial, sans-serif" font-size="24" font-weight="700">${opts.label}</text>
                </svg>`;
            return 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svg);
        }

