        const STAT_COLORS = {
            STR: '#ff8c00', END: '#ff4444', AGI: '#aa44ff',
            VIT: '#44cc88', SPI: '#4488ff', TEC: '#1ec8b5', GKI: '#88ccff'
        };

        function formatSignificantNumber(num, sig = 4) {
            const value = Number(num);
            if (!Number.isFinite(value)) return '0';
            if (Math.abs(value) < 1e-9) return '0';
            return Number(value.toPrecision(sig)).toString();
        }

        function roundToSignificantNumber(num, sig = 6) {
            const value = Number(num);
            if (!Number.isFinite(value)) return 0;
            if (Math.abs(value) < 1e-9) return 0;
            return Number(value.toPrecision(sig));
        }

        function formatPL(num) {
            if (!isFinite(num) || num < 0) return '0';
            if (num < 1000) return formatSignificantNumber(num, 4);
            const tiers = [
                [1e36,'Ud'],[1e33,'Dc'],[1e30,'No'],[1e27,'Oc'],[1e24,'Sp'],
                [1e21,'Sx'],[1e18,'Qi'],[1e15,'Qa'],[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']
            ];
            for (const [v, s] of tiers) {
                if (num >= v) {
                    const n = num / v;
                    return formatSignificantNumber(n, 4) + s;
                }
            }
            return formatSignificantNumber(num, 4);
        }

        function formatStat(num) {
            if (!isFinite(num) || num <= 0) return '0';
            if (num < 1000) return formatSignificantNumber(num, 4);
            const tiers = [
                [1e36,'Ud'],[1e33,'Dc'],[1e30,'No'],[1e27,'Oc'],[1e24,'Sp'],
                [1e21,'Sx'],[1e18,'Qi'],[1e15,'Qa'],[1e12,'T'],[1e9,'B'],[1e6,'M'],[1e3,'K']
            ];
            for (const [v, s] of tiers) {
                if (num >= v) {
                    return formatSignificantNumber(num / v, 4) + s;
                }
            }
            return formatSignificantNumber(num, 4);
        }

