        function getArtPanel(id, opacity, fallbackType) {
            const resolvedKey = IMAGE_ALIASES[id] || id;
            const img = IMAGE_MAP[resolvedKey];
            if (img) {
                return `<div class="art-panel" style="height:280px;background:#0a0a0f;opacity:${opacity};border-radius:6px 6px 0 0;overflow:hidden;display:flex;align-items:center;justify-content:center;">
                    <img src="${img}" style="width:100%;height:100%;object-fit:contain;object-position:center;transition:transform 0.3s ease;background:#080c14;"
                         onmouseover="this.style.transform='scale(1.04)'" onmouseout="this.style.transform='scale(1)'"
                         onerror="this.parentElement.outerHTML=getFallbackArtPanel('${id}',${opacity},'${fallbackType}')">
                </div>`;
            }
            return getFallbackArtPanel(id, opacity, fallbackType);
        }

