        function getFallbackArtPanel(id, opacity, fallbackFn) {
            const art = fallbackFn === 'ability'  ? getAbilityArt(id)
                      : fallbackFn === 'saga'     ? getSagaArt(id)
                                                  : getTransformationArt(id);
            return `<div class="art-panel ${art.cls}" style="opacity:${opacity}">
                <span class="art-symbol" style="color:#fff;font-size:2.2em;">${art.sym}</span>
            </div>`;
        }

        // ── Per-tab background images ──────────────────────────────────────────
        const TAB_BACKGROUNDS = {
            'dashboard':       'bg_dashboard',
            'training':        'bg_stats',
            'character':       'bg_transformations',
            'sagas':           'bg_sagas',
            'transformations': 'bg_transformations',
            'abilities':       'bg_abilities',
            'fitness-plan':    'bg_stats',
            'achievements':    'bg_achievements',
            'history':         'bg_stats',
            'charts':          'bg_stats',
            'arcs':            'bg_stats',
        };

        function applyTabBg(tabId) {
            const overlay = document.getElementById('tabBgOverlay');
            if (!overlay) return;
            const key = TAB_BACKGROUNDS[tabId];
            const img = key && IMAGE_MAP[key];
            if (img) {
                overlay.style.backgroundImage = `url(${img})`;
                overlay.style.opacity = '0.08';
            } else {
                overlay.style.opacity = '0';
            }
        }

        function renderGameTabContent(tabId) {
            if      (tabId === 'sagas')           renderSagas();
            else if (tabId === 'transformations') renderTransformations();
            else if (tabId === 'abilities')       renderAbilities();
            else if (tabId === 'dragonballs')     renderDragonBalls();
            else if (tabId === 'achievements')    renderAchievements();
            else if (tabId === 'training')        { renderTraining(); renderWorkoutLog(); }
            else if (tabId === 'character')       renderCharacter();
            else if (tabId === 'fitness-plan')    renderFitnessPlan();
            else if (tabId === 'history')         renderHistoryTab();
        }

        function switchGameTab(tabId) {
            const target = document.getElementById(tabId);
            if (!target) return;
            document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.toggle('active', btn.dataset.tab === tabId));
            document.querySelectorAll('.tab-content').forEach(content => content.classList.toggle('active', content.id === tabId));
            applyTabBg(tabId);
            renderGameTabContent(tabId);
        }
        window.switchGameTab = switchGameTab;

        document.addEventListener('click', (event) => {
            const button = event.target.closest?.('.tab-btn[data-tab]');
            if (!button) return;
            const tabId = button.dataset.tab;
            if (!document.getElementById(tabId)) return;
            event.preventDefault();
            event.stopPropagation();
            switchGameTab(tabId);
        }, true);

