            addExerciseIfMissing('strength', 'chest', { name: 'Incline Bench Press Machine', type: 'weighted', weights: { STR: 0.00035, VIT: 0.00007, TEC: 0.00004 } }, 'chest');
            addExerciseIfMissing('strength', 'chest', { name: 'Decline Bench Press Machine', type: 'weighted', weights: { STR: 0.00036, VIT: 0.00006, TEC: 0.00004 } }, 'chest');
