        const ABILITY_ID_MIGRATIONS = {
            planet_burst: 'granolah_sniping',
        };
        const REMOVED_ABILITY_REFUNDS = {
            kaioken_technique: 6,
            gamma_burst_flash: 18,
        };

        function migrateAbilityInventory(char) {
            if (!char || !char.purchasedAbilities || typeof char.purchasedAbilities !== 'object') return;
            let refund = 0;
            Object.entries(ABILITY_ID_MIGRATIONS).forEach(([from, to]) => {
                const rank = Number(char.purchasedAbilities[from]) || 0;
                if (rank > 0) {
                    char.purchasedAbilities[to] = Math.max(Number(char.purchasedAbilities[to]) || 0, rank);
                    delete char.purchasedAbilities[from];
                    if (Array.isArray(char.equippedAbilities)) {
                        char.equippedAbilities = char.equippedAbilities.map(id => id === from ? to : id);
                    }
                }
            });
            Object.entries(REMOVED_ABILITY_REFUNDS).forEach(([id, cost]) => {
                const rank = Number(char.purchasedAbilities[id]) || 0;
                if (rank > 0) {
                    refund += Number(cost) || 0;
                    delete char.purchasedAbilities[id];
                }
                if (Array.isArray(char.equippedAbilities)) {
                    char.equippedAbilities = char.equippedAbilities.filter(abilityId => abilityId !== id);
                }
            });
            if (refund > 0) {
                char.spSpent = Math.max(0, +(Number(char.spSpent || 0) - refund).toFixed(2));
                char.abilityPointsSpent = Math.max(0, +(Number(char.abilityPointsSpent || 0) - refund).toFixed(2));
            }
            if (Array.isArray(char.equippedAbilities)) {
                char.equippedAbilities = [...new Set(char.equippedAbilities.filter(Boolean))];
            }
        }

