        let currentWorkoutSession = [];
        let activeTrainingBranchId = 'weighted';

        // ============ HELPERS ============
        function getActiveCharacter() {
            return state.characters[state.activeCharacter];
        }

        function getStartingStatsForRace(race = 'earthling') {
            const stats = RACE_STARTING_STATS[race] || RACE_STARTING_STATS.earthling;
            return { ...stats };
        }

        function isEmptyStatMap(stats = {}) {
            return STATS.every(stat => Math.abs(Number(stats[stat]) || 0) < 0.0001);
        }

        function isStarterStatProfile(char) {
            const stats = char?.stats || {};
            return Object.values(RACE_STARTING_STATS).some(profile =>
                STATS.every(stat => Math.abs((Number(stats[stat]) || 0) - (Number(profile[stat]) || 0)) < 0.001)
            );
        }

        function hasCharacterTrainingProgress(char) {
            return (Number(char?.totalTXP) || 0) > 0
                || (Array.isArray(char?.workoutLog) && char.workoutLog.length > 0)
                || (Array.isArray(char?.history) && char.history.length > 0)
                || (Array.isArray(char?.completedSagas) && char.completedSagas.length > 0);
        }

        function applyStartingStatsForRace(char, race = 'earthling') {
            if (!char) return;
            char.stats = getStartingStatsForRace(race);
            char.startingStatsAppliedRace = race;
        }

        function getPowerLevelFromStats(stats) {
            const raw = Object.entries(POWER_STAT_WEIGHTS)
                .reduce((sum, [stat, weight]) => sum + ((Number(stats?.[stat]) || 0) * weight), 0);
            return Math.round(raw) / 1000;
        }

        function getGodPowerLevelFromStats(stats) {
            const raw = Object.entries(GOD_POWER_STAT_WEIGHTS)
                .reduce((sum, [stat, weight]) => sum + ((Number(stats?.[stat]) || 0) * weight), 0);
            return Math.round(raw) / 1000;
        }

        function getTransformationById(id) {
            return TRANSFORMATIONS.find(t => t.id === id) || TRANSFORMATIONS[0];
        }

        function normalizeRaceKey(race) {
            const key = String(race || 'earthling').toLowerCase().replace(/[-\s]+/g, '_');
            if (['human', 'earthling'].includes(key)) return 'earthling';
            if (['half_saiyan', 'half-saiyan', 'hybrid'].includes(key)) return 'hybrid';
            if (['frieza', 'friezas_race', "frieza's_race", 'frieza_race'].includes(key)) return 'frieza_race';
            if (key === 'perfect_android') return 'android';
            return key;
        }

        const KAIOKEN_TRANSFORMATION_IDS = new Set(['kaioken_x1', 'kaioken_x3', 'kaioken_x10', 'kaioken_x20', 'kaioken_x50', 'kaioken_x100']);
        const SHARED_ULTRA_TRANSFORMATION_IDS = new Set(['ultra_instinct_sign', 'mastered_ultra_instinct', 'ultra_instinct_selfishness', 'ultra_ego']);
        const HALF_SAIYAN_EXCLUDED_TRANSFORMATION_IDS = new Set([
            'golden_great_ape',
            'super_saiyan_4',
            'legendary_super_saiyan',
            'full_power_broly',
            'super_saiyan_god',
            'super_saiyan_blue',
            'super_saiyan_rose',
            'ssb_evolved',
            'ssb_kaioken_x10',
            'ssb_kaioken_x20'
        ]);

        function isKaiokenTransformation(trans) {
            return !!trans && KAIOKEN_TRANSFORMATION_IDS.has(trans.id);
        }

        function isSharedUltraTransformation(trans) {
            return !!trans && (SHARED_ULTRA_TRANSFORMATION_IDS.has(trans.id) || /ultra instinct|ultra ego/i.test(String(trans.id || '') + ' ' + String(trans.name || '')));
        }

        function transformationAllowedForRace(race, trans) {
            if (!trans) return false;
            const raceKey = normalizeRaceKey(race);
            if (trans.id === 'base') return true;
            if (raceKey === 'majin') return false;
            if (isKaiokenTransformation(trans) || isSharedUltraTransformation(trans)) {
                return !['frieza_race', 'majin'].includes(raceKey);
            }
            if (trans.race === 'universal') return true;
            if (raceKey === 'hybrid' && trans.race === 'saiyan') {
                return !HALF_SAIYAN_EXCLUDED_TRANSFORMATION_IDS.has(trans.id);
            }
            if (trans.race === raceKey) return true;
            if (trans.race === 'hybrid' && raceKey === 'hybrid') return true;
            return false;
        }
        window.transformationAllowedForRace = transformationAllowedForRace;

        function transformationRaceRequirementLabel(trans) {
            if (!trans || trans.id === 'base') return 'Any race';
            if (isKaiokenTransformation(trans) || isSharedUltraTransformation(trans)) return 'Any race except Frieza Race or Majin';
            if (trans.race === 'saiyan') return HALF_SAIYAN_EXCLUDED_TRANSFORMATION_IDS.has(trans.id) ? 'Saiyan' : 'Saiyan or Half-Saiyan';
            return (typeof v5tRaceLabel === 'function' ? v5tRaceLabel(trans.race) : String(trans.race || 'Universal').replace(/_/g, ' '));
        }

        function getRacePartnerXPBonus(char) {
            const race = normalizeRaceKey(char?.race);
            const level = Math.max(1, typeof getLevel === 'function' ? Number(getLevel(char)) || 1 : Number(char?.level) || 1);
            if (race === 'earthling' || race === 'hybrid') return 0.10 + Math.max(0, level - 1) * 0.01;
            return 0;
        }

        function getRacePartnerXPMultiplier(char) {
            return Math.max(0.1, 1 + getRacePartnerXPBonus(char));
        }

        function getRaceTrainingEffectMultiplier(char) {
            const race = normalizeRaceKey(char?.race);
            if (race === 'frieza_race') return 1.5;
            if (race === 'earthling') return 1.25;
            return 1;
        }

        function getRacePartnerEffectMultiplier(char) {
            return normalizeRaceKey(char?.race) === 'frieza_race' ? 1.5 : 1;
        }

        function getRaceSagaEffectMultiplier(char) {
            return normalizeRaceKey(char?.race) === 'earthling' ? 1.25 : 1;
        }

        function getRaceAbilityXPMultiplier(char) {
            return normalizeRaceKey(char?.race) === 'earthling' ? 1.25 : 1;
        }

        function getRaceDragonBallDifficultyMultiplier(char) {
            const race = normalizeRaceKey(char?.race);
            if (race === 'frieza_race') return 2;
            if (race === 'namekian') return 0.5;
            if (race === 'earthling') return 0.75;
            return 1;
        }

        function scaleLegacyEffectTotals(effects, scale = 1) {
            if (!effects || Math.abs(scale - 1) < 0.0001) return effects;
            Object.keys(effects.statBonus || {}).forEach(key => { effects.statBonus[key] *= scale; });
            Object.keys(effects.typeBonus || {}).forEach(key => { effects.typeBonus[key] *= scale; });
            Object.keys(effects.categoryBonus || {}).forEach(key => { effects.categoryBonus[key] *= scale; });
            ['txpBonus', 'tpBonus', 'spBonus', 'spFlat', 'characterXPBonus'].forEach(key => {
                if (Object.prototype.hasOwnProperty.call(effects, key)) effects[key] *= scale;
            });
            return effects;
        }

        function mergeLegacyEffectTotals(target, source, scale = 1) {
            if (!target || !source) return target;
            Object.entries(source.statBonus || {}).forEach(([key, value]) => { if (target.statBonus?.[key] !== undefined) target.statBonus[key] += (Number(value) || 0) * scale; });
            Object.entries(source.typeBonus || {}).forEach(([key, value]) => { target.typeBonus[key] = (target.typeBonus[key] || 0) + (Number(value) || 0) * scale; });
            Object.entries(source.categoryBonus || {}).forEach(([key, value]) => { target.categoryBonus[key] = (target.categoryBonus[key] || 0) + (Number(value) || 0) * scale; });
            ['txpBonus', 'tpBonus', 'spBonus', 'spFlat', 'characterXPBonus'].forEach(key => {
                target[key] = (Number(target[key]) || 0) + (Number(source[key]) || 0) * scale;
            });
            return target;
        }

        function getUnlockedTransformationIds(char) {
            if (!Array.isArray(char.unlockedTransformations)) char.unlockedTransformations = ['base'];
            if (!char.unlockedTransformations.includes('base')) char.unlockedTransformations.unshift('base');
            return [...new Set(char.unlockedTransformations)].filter(id => TRANSFORMATIONS.some(trans => trans.id === id));
        }

        function getAvailableTransformations(char) {
            const race = normalizeRaceKey(char?.race || 'earthling');
            return getUnlockedTransformationIds(char)
                .map(id => getTransformationById(id))
                .filter(trans => transformationAllowedForRace(race, trans));
        }

        function getActiveTransformation(char) {
            const available = getAvailableTransformations(char);
            if (!available.some(t => t.id === char.activeTransformation)) char.activeTransformation = 'base';
            return available.find(t => t.id === char.activeTransformation) || TRANSFORMATIONS[0];
        }

        function getEffectiveStatsForTransformation(char, transformationId = 'base') {
            const baseStats = { ...createZeroStatMap(), ...(char?.stats || {}) };
            const trans = getTransformationById(transformationId);
            if (!trans || trans.id === 'base') return baseStats;
            const profile = { STR: 1, END: 1, AGI: 1, VIT: 1, SPI: 1, TEC: 1, GKI: 1, ...(trans.statProfile || {}) };
            const baseRaw = Object.entries(POWER_STAT_WEIGHTS).reduce((sum, [stat, weight]) => sum + (baseStats[stat] * weight), 0);
            const profiledRaw = Object.entries(POWER_STAT_WEIGHTS).reduce((sum, [stat, weight]) => sum + (baseStats[stat] * (Number(profile[stat]) || 1) * weight), 0);
            const targetRaw = baseRaw * (Number(trans.mult) || 1);
            const scalar = baseRaw > 0 && profiledRaw > 0 ? targetRaw / profiledRaw : 1;
            const effective = { ...baseStats };
            Object.keys(POWER_STAT_WEIGHTS).forEach(stat => {
                effective[stat] = baseStats[stat] * (Number(profile[stat]) || 1) * scalar;
            });
            effective.GKI = baseStats.GKI * (Number(profile.GKI) || 1);
            return effective;
        }

        function getTransformationStatMultipliers(trans) {
            const baseStats = { STR: 100, END: 100, AGI: 100, VIT: 100, SPI: 100, TEC: 100, GKI: 100 };
            const effective = getEffectiveStatsForTransformation({ stats: baseStats }, trans.id);
            return Object.fromEntries(STATS.map(stat => [stat, (effective[stat] || 0) / baseStats[stat]]));
        }

        function getEffectiveStats(char) {
            return getEffectiveStatsForTransformation(char, getActiveTransformation(char).id);
        }

        function getBasePowerLevel(char) {
            return getPowerLevelFromStats(char?.stats || {});
        }

        function getPowerLevel(char) {
            return getPowerLevelFromStats(getEffectiveStats(char));
        }

        function getGodPowerLevel(char) {
            return getGodPowerLevelFromStats(getEffectiveStats(char));
        }

        function getBestSagaRequirementForm(char, saga) {
            const baseStats = { ...createZeroStatMap(), ...(char?.stats || {}) };
            const candidates = saga?.baseOnly
                ? [{
                    trans: getTransformationById('base'),
                    stats: baseStats,
                    pl: getPowerLevelFromStats(baseStats),
                    gpl: getGodPowerLevelFromStats(baseStats)
                }]
                : getAvailableTransformations(char)
                    .map(trans => {
                        const stats = getEffectiveStatsForTransformation(char, trans.id);
                        return {
                            trans,
                            stats,
                            pl: getPowerLevelFromStats(stats),
                            gpl: getGodPowerLevelFromStats(stats)
                        };
                    });
            return candidates
                .filter(form => form.pl >= (saga.plReq || 0)
                    && (!saga.gplReq || form.gpl >= saga.gplReq)
                    && Object.entries(saga.statReqs || {}).every(([stat, val]) => (form.stats[stat] || 0) >= val))
                .sort((a, b) => b.pl - a.pl)[0] || null;
        }

        function getBestAvailablePowerLevel(char) {
            return Math.max(...getAvailableTransformations(char).map(trans => getPowerLevelFromStats(getEffectiveStatsForTransformation(char, trans.id))));
        }

        function getBestAvailableGodPowerLevel(char) {
            return Math.max(...getAvailableTransformations(char).map(trans => getGodPowerLevelFromStats(getEffectiveStatsForTransformation(char, trans.id))));
        }

        function isGodTierSaga(sagaId) {
            return sagaId && (sagaId.startsWith('dbs_') || sagaId.startsWith('daima_'));
        }

        function hasReachedGodTier(char) {
            if (SAGAS.some(s => isGodTierSaga(s.id) && char.completedSagas.includes(s.id))) return true;
            return SAGAS.some(s => isGodTierSaga(s.id) && getBestSagaRequirementForm(char, s));
        }

        function isGodKiUnlocked(char) {
            if (!char || !char.stats) return false;
            if ((char.completedSagas || []).some(id => isGodTierSaga(id))) return true;
            const beerus = SAGAS.find(s => s.id === 'dbs_beerus');
            if (!beerus) return false;
            return !!getBestSagaRequirementForm(char, beerus);
        }

        // Slower early curve so a first workout cannot jump several levels.
        function getLevel(char) {
            return Math.floor(1 + Math.sqrt((char.totalTXP || 0) / LEVEL_TXP_FACTOR));
        }

        // PL milestone thresholds and their SP bonuses
        const PL_MILESTONES = [
            // Early PL milestones are mostly recognition; SP is reserved for major breakthroughs.
            { id: 'pl_5_farmer', threshold: 5, sp: 0, label: 'Farmer PL 5' },
            { id: 'pl_10',    threshold: 10,          sp: 0, label: 'PL 10' },
            { id: 'pl_100',   threshold: 100,         sp: 0, label: 'PL 100' },
            { id: 'pl_500',   threshold: 500,         sp: 0, label: 'PL 500 — Dragon Ball complete!' },
            { id: 'pl_9001',  threshold: 9001,        sp: 1, label: 'Over 9,000!' },
            { id: 'pl_50k',   threshold: 50000,       sp: 1, label: 'PL 50K' },
            { id: 'pl_1m',    threshold: 1e6,         sp: 1, label: 'PL 1 Million' },
            { id: 'pl_100m',  threshold: 1e8,         sp: 2, label: 'PL 100 Million' },
            { id: 'pl_1b',    threshold: 1e9,         sp: 2, label: 'PL 1 Billion' },
            { id: 'pl_10b',   threshold: 10000000000, sp: 2, label: 'PL 10 Billion' },
            { id: 'pl_50b',   threshold: 50000000000, sp: 3, label: 'PL 50 Billion — God Tier reached!' },
            { id: 'pl_100b',  threshold: 1e11,        sp: 3, label: 'PL 100 Billion' },
            { id: 'pl_250b',  threshold: 2.5e11,      sp: 4, label: 'PL 250 Billion — True Mortal Peak' },
        ];

        const GPL_MILESTONES = [
            { id: 'gpl_1',     threshold: 1,      sp: 1, label: '𒀭 GPL 1 — Godly Ki Awakened!' },
            { id: 'gpl_50',    threshold: 50,     sp: 1, label: '𒀭 GPL 50 — Golden Form' },
            { id: 'gpl_200',   threshold: 200,    sp: 1, label: '𒀭 GPL 200 — Universal Tournament' },
            { id: 'gpl_1500',  threshold: 1500,   sp: 2, label: '𒀭 GPL 1,500 — Zero Mortal Plan' },
            { id: 'gpl_5k',    threshold: 5000,   sp: 2, label: '𒀭 GPL 5,000 — Ultra Instinct Sign' },
            { id: 'gpl_50k',   threshold: 50000,  sp: 3, label: '𒀭 GPL 50,000 — Granolah Survivor' },
            { id: 'gpl_500k',  threshold: 500000, sp: 4, label: '𒀭 GPL 500,000 — Daima True Form' },
        ];

        // Stat milestone thresholds (applies per-stat)
        const STAT_MILESTONES = [100, 250, 500, 1000, 2000, 4000, 7500];

        function getSkillPoints(char) {
            return Math.max(0, (char.spEarned || 0) - (char.spSpent || 0));
        }

        function formatPointValue(value, decimals = 2) {
            const num = Number(value) || 0;
            if (Math.abs(num - Math.round(num)) < 0.0001) return String(Math.round(num));
            const rounded = Number(num.toPrecision(4));
            return rounded.toFixed(Math.min(4, Math.max(0, decimals + 2))).replace(/\.?0+$/, '');
        }

        function addTrainingPointValue(char, amount) {
            if (!(Number(amount) > 0)) return 0;
            char.trainingPoints = +((Number(char.trainingPoints) || 0) + Number(amount)).toFixed(4);
            char.tpEarned = +((Number(char.tpEarned) || 0) + Number(amount)).toFixed(4);
            return amount;
        }

        function addSkillPointValue(char, amount) {
            if (!(Number(amount) > 0)) return 0;
            char.spEarned = +((Number(char.spEarned) || 0) + Number(amount)).toFixed(4);
            char.abilityPointsEarned = +Math.max(Number(char.abilityPointsEarned) || 0, char.spEarned).toFixed(4);
            return amount;
        }

        function getExerciseDistanceKm(entry) {
            return Math.max(0, Number(entry?.inputs?.distance ?? entry?.distance) || 0);
        }

        function getExerciseDurationMinutes(entry) {
            const direct = Number(entry?.inputs?.duration ?? entry?.duration) || 0;
            const setSeconds = (entry?.sets || []).reduce((sum, set) => sum + (Number(set.seconds) || 0), 0) / 60;
            return Math.max(0, direct, setSeconds);
        }

        function getFractionalPracticeAwards(normalizedSession) {
            const awards = [];
            let walkingKm = 0;
            let meditationMinutes = 0;
            (normalizedSession || []).forEach(entry => {
                const name = String(entry?.name || '');
                if (/walk/i.test(name)) walkingKm += getExerciseDistanceKm(entry);
                if (/meditation|breath/i.test(name)) meditationMinutes += getExerciseDurationMinutes(entry);
            });
            let outdoorRowKm = 0;
            let outdoorRowSpeedBonus = 0;
            (normalizedSession || []).forEach(entry => {
                const name = String(entry?.name || '');
                if (!/outdoor row/i.test(name)) return;
                const distance = getExerciseDistanceKm(entry);
                const speed = Number(entry?.inputs?.speed ?? entry?.speed) || 0;
                outdoorRowKm += distance;
                outdoorRowSpeedBonus += Math.max(0, speed - 8.5) * Math.max(0.25, distance);
            });

            if (walkingKm > 0) {
                awards.push({
                    reason: `Walking practice (${formatPointValue(walkingKm, 1)} km)`,
                    tp: Math.min(0.35, walkingKm * 0.08),
                    sp: Math.min(0.08, walkingKm * 0.015)
                });
            }
            if (meditationMinutes > 0) {
                awards.push({
                    reason: `Meditation practice (${formatPointValue(meditationMinutes, 0)} min)`,
                    tp: Math.min(0.3, meditationMinutes * 0.01),
                    sp: Math.min(0.25, meditationMinutes * 0.008)
                });
            }
            if (outdoorRowKm > 0) {
                awards.push({
                    reason: `Outdoor rowing (${formatPointValue(outdoorRowKm, 1)} km)`,
                    tp: Math.min(0.45, outdoorRowKm * 0.07 + outdoorRowSpeedBonus * 0.012),
                    sp: Math.min(0.16, outdoorRowKm * 0.022 + outdoorRowSpeedBonus * 0.004)
                });
            }

            const tpTotal = Math.min(0.85, awards.reduce((sum, award) => sum + award.tp, 0));
            const spTotal = Math.min(0.45, awards.reduce((sum, award) => sum + award.sp, 0));
            return { awards, tpTotal, spTotal };
        }

        function awardFractionalAbilityPoints(char, normalizedSession, workoutDate) {
            const practice = getFractionalPracticeAwards(normalizedSession);
            const base = practice.spTotal;
            if (!(base > 0)) return { total: 0, awards: [] };
            const total = Math.floor(base * getPartnerSPMultiplier(char) * 100) / 100;
            if (!(total > 0)) return { total: 0, awards: [] };
            addSkillPointValue(char, total);
            if (!Array.isArray(char.spFragmentHistory)) char.spFragmentHistory = [];
            const awards = practice.awards
                .filter(award => award.sp > 0)
                .map(award => ({ reason: award.reason, amount: +award.sp.toFixed(4) }));
            char.spFragmentHistory.push({ date: workoutDate, awards, total });
            if (char.spFragmentHistory.length > 300) char.spFragmentHistory = char.spFragmentHistory.slice(-300);
            return { total, awards };
        }

        function formatRewardText(sp = 0, txp = 0, signed = false) {
            const parts = [];
            if (sp) parts.push(`${signed ? '+' : ''}${formatPointValue(sp)} SP`);
            if (txp) parts.push(`${signed ? '+' : ''}${txp} TXP`);
            return parts.join(signed ? ', ' : ' + ') || 'Progress only';
        }

        const ACHIEVEMENT_REWARD_MAP = {
            first_workout: { tp: 1, txp: 25 },
            ten_workouts: { tp: 3 },
            fifty_workouts: { tp: 8, sp: 1 },
            hundred_workouts: { tp: 14, sp: 1 },
            workouts_200: { tp: 18, sp: 1 },
            workouts_365: { tp: 24, sp: 2 },
            workouts_500: { tp: 30, sp: 2 },
            workouts_1000: { tp: 50, sp: 4 },
            first_saga: { tp: 2 },
            complete_db: { tp: 7, sp: 1 },
            complete_dbz: { tp: 10, sp: 2 },
            complete_dbs: { tp: 14, sp: 2 },
            complete_daima: { tp: 12, sp: 2 },
            over_9000: { sp: 1 },
            pl_million: { tp: 10, sp: 2 },
            first_transform: { sp: 1 },
            first_ability: { tp: 1 },
            ten_abilities: { tp: 3, sp: 1 },
            abilities_20: { tp: 5, sp: 1 },
            abilities_30: { tp: 7, sp: 2 },
            partners_ginyu_force: { tp: 4, sp: 0.5 },
            partners_all_goku: { tp: 18, sp: 2 },
            partners_all_vegeta: { tp: 16, sp: 2 },
            partners_saiyan_elite: { tp: 30, sp: 3 },
            partners_hybrid_saiyans: { tp: 18, sp: 2 },
            partners_androids: { tp: 10, sp: 1 },
            partners_buu_forms: { tp: 14, sp: 2 },
            partners_frieza_line: { tp: 16, sp: 2 },
            streak_7: { tp: 3 },
            streak_30: { tp: 5, sp: 1 },
            streak_100: { tp: 10, sp: 2 },
            streak_365: { tp: 18, sp: 3 },
            all_stats_50: { tp: 5, sp: 1 },
            all_stats_100: { tp: 7, sp: 1 },
            all_stats_500: { tp: 12, sp: 2 },
            all_stats_1000: { tp: 16, sp: 3 },
            god_tier: { tp: 12, sp: 3 },
            all_sagas: { tp: 21, sp: 5 },
            dragon_ball_first: { tp: 2 },
            dragon_ball_earth_set: { tp: 5, sp: 1 },
            dragon_ball_namek_set: { tp: 10, sp: 2 },
            dragon_ball_super_set: { tp: 20, sp: 4 },
            dragon_ball_first_wish: { tp: 3, sp: 1 },
            dragon_ball_ten_wishes: { tp: 14, sp: 2 }
        };

        function getAchievementReward(ach) {
            if (ACHIEVEMENT_REWARD_MAP[ach.id]) return ACHIEVEMENT_REWARD_MAP[ach.id];
            const id = String(ach.id || '');
            if (id.startsWith('workouts_')) return { tp: 8, sp: 1 };
            if (id.startsWith('streak_')) return { tp: 5, sp: 1 };
            if (id.startsWith('str_') || id.startsWith('end_') || id.startsWith('agi_') || id.startsWith('vit_') || id.startsWith('spi_')) return { tp: 3 };
            if (id.startsWith('pl_')) return { tp: 5, sp: 1 };
            if (id.startsWith('unlock_')) return { tp: 4, sp: 1 };
            if (id.startsWith('partners_')) return getPartnerCollection(id)?.reward || { tp: 8, sp: 1 };
            if (id.startsWith('transforms_')) return { tp: 6, sp: 1 };
            if (id.startsWith('abilities_')) return { tp: 4 };
            if (id.startsWith('sagas_')) return { tp: 6, sp: 1 };
            if (id.startsWith('complete_')) return { tp: 8, sp: 2 };
            return { tp: 1 };
        }

        function normalizeReward(reward = {}) {
            return {
                sp: Math.max(0, Number(reward.sp) || 0),
                tp: Math.max(0, Number(reward.tp) || 0),
                txp: Math.max(0, Number(reward.txp) || 0)
            };
        }

        function formatRewardBundle(reward = {}, signed = true) {
            const r = normalizeReward(reward);
            const prefix = signed ? '+' : '';
            const parts = [];
            if (r.sp) parts.push(`${prefix}${formatPointValue(r.sp)} SP`);
            if (r.tp) parts.push(`${prefix}${formatPointValue(r.tp)} TP`);
            if (r.txp) parts.push(`${prefix}${r.txp} TXP`);
            return parts.join(', ');
        }

        function awardAchievementReward(char, ach) {
            if (!Array.isArray(char.achievementRewardsClaimed)) char.achievementRewardsClaimed = [];
            if (char.achievementRewardsClaimed.includes(ach.id)) return normalizeReward();
            const reward = normalizeReward(getAchievementReward(ach));
            if (reward.sp) addSkillPointValue(char, reward.sp);
            if (reward.tp) addTrainingPointValue(char, reward.tp);
            if (reward.txp) char.totalTXP = (char.totalTXP || 0) + reward.txp;
            char.achievementRewardsClaimed.push(ach.id);
            return reward;
        }

        function countLevelThresholdsCrossed(oldLevel, newLevel, interval) {
            return Math.max(0, Math.floor((newLevel - 1) / interval) - Math.floor((oldLevel - 1) / interval));
        }

        function getLegacyLevelRewardAbilityPointsForLevel(level) {
            const lv = Math.max(1, Math.floor(Number(level) || 1));
            return Math.floor(Math.max(0, lv - 1) / LEVELS_PER_SKILL_POINT)
                + Math.floor(Math.max(0, lv - 1) / LEVEL_SKILL_POINT_BONUS_INTERVAL);
        }

        function getLevelRewardTotalsForLevel(level) {
            const lv = Math.max(1, Math.floor(Number(level) || 1));
            let ap = getLegacyLevelRewardAbilityPointsForLevel(lv);
            let tp = 0;
            for (let rewardLevel = 2; rewardLevel <= lv; rewardLevel++) {
                ap += LEVEL_REWARD_AP_PER_LEVEL;
                tp += LEVEL_REWARD_TP_PER_LEVEL;
                if (rewardLevel % LEVEL_REWARD_MINOR_INTERVAL === 0) {
                    ap += 0.15;
                    tp += 0.35;
                }
                if (rewardLevel % LEVEL_REWARD_MAJOR_INTERVAL === 0) {
                    ap += 1;
                    tp += 1;
                }
                if (rewardLevel % LEVEL_REWARD_CHOICE_INTERVAL === 0) {
                    ap += 1.5;
                    tp += 2;
                }
                if (rewardLevel % LEVEL_REWARD_PRESTIGE_INTERVAL === 0) {
                    ap += 2;
                    tp += 3;
                }
                if (rewardLevel % LEVEL_REWARD_LEGACY_INTERVAL === 0) {
                    ap += 5;
                    tp += 7;
                }
            }
            return { ap: +ap.toFixed(2), tp: +tp.toFixed(2) };
        }

        function getLevelRewardAbilityPointsForLevel(level) {
            return getLevelRewardTotalsForLevel(level).ap;
        }

        function getLevelRewardTrainingPointsForLevel(level) {
            return getLevelRewardTotalsForLevel(level).tp;
        }

        function getLevelRewardBreakthroughLevels(level) {
            const lv = Math.max(1, Math.floor(Number(level) || 1));
            const levels = [];
            for (let rewardLevel = LEVEL_TRAINING_BREAKTHROUGH_INTERVAL; rewardLevel <= lv; rewardLevel += LEVEL_TRAINING_BREAKTHROUGH_INTERVAL) {
                levels.push(rewardLevel);
            }
            return levels;
        }

        function effectIncludesGodKi(effect) {
            if (!effect) return false;
            if (effect.stat && Number(effect.stat.GKI) > 0) return true;
            return false;
        }

        function upgradeIncludesGodKi(upgrade) {
            return effectIncludesGodKi(upgrade?.effects) || effectIncludesGodKi(upgrade?.effectsPerLevel);
        }

        function canBreakthroughTrainingUpgrade(char, upgrade) {
            if (!upgrade) return false;
            const currentLevel = getTrainingUpgradeLevel(char, upgrade.id);
            const maxLevel = upgrade.repeatable ? upgrade.maxLevel : 1;
            if (currentLevel >= maxLevel) return false;
            if (!trainingPrerequisitesMet(char, upgrade)) return false;
            if (upgradeIncludesGodKi(upgrade) && !isGodKiUnlocked(char)) return false;
            return true;
        }

        function getBreakthroughUpgradeAmount(upgrade, currentLevel) {
            const maxLevel = upgrade.repeatable ? upgrade.maxLevel : 1;
            if (upgrade.id === 'gravity_level') return Math.min(5, maxLevel - currentLevel);
            return 1;
        }

        function findNextTrainingBreakthroughUpgrade(char) {
            const branchById = Object.fromEntries(TRAINING_BRANCHES.map(branch => [branch.id, branch]));
            const orderedBranches = ['weighted', 'gravity', 'chamber', 'otherworld'];
            const firstEligible = upgrades => upgrades.find(upgrade => getTrainingUpgradeLevel(char, upgrade.id) === 0 && canBreakthroughTrainingUpgrade(char, upgrade))
                || upgrades.find(upgrade => canBreakthroughTrainingUpgrade(char, upgrade));

            for (const branchId of orderedBranches) {
                const branch = branchById[branchId];
                if (!branch) continue;
                if (branchId === 'gravity') {
                    const support = firstEligible(branch.upgrades.filter(upgrade => upgrade.id !== 'gravity_level'));
                    if (support) return { branch, upgrade: support };
                    const gravity = branch.upgrades.find(upgrade => upgrade.id === 'gravity_level');
                    if (canBreakthroughTrainingUpgrade(char, gravity)) return { branch, upgrade: gravity };
                    continue;
                }
                const upgrade = firstEligible(branch.upgrades);
                if (upgrade) return { branch, upgrade };
            }
            return null;
        }

        function addLevelRewardAbilityPoints(char, amount, source = 'Level reward') {
            const value = +(Number(amount) || 0).toFixed(2);
            if (value <= 0) return 0;
            if (typeof addAbilityPoints === 'function') return addAbilityPoints(char, value, source);
            char.spEarned = +((Number(char.spEarned) || 0) + value).toFixed(2);
            char.abilityPointsEarned = +Math.max(Number(char.abilityPointsEarned) || 0, char.spEarned).toFixed(2);
            return value;
        }

        function addLevelRewardTrainingPoints(char, amount) {
            const value = +(Number(amount) || 0).toFixed(2);
            if (value <= 0) return 0;
            char.trainingPoints = +((Number(char.trainingPoints) || 0) + value).toFixed(2);
            char.tpEarned = +((Number(char.tpEarned) || 0) + value).toFixed(2);
            return value;
        }

        function grantLevelTrainingBreakthrough(char, rewardLevel) {
            if (!char) return null;
            if (!Array.isArray(char.levelBreakthroughsClaimed)) char.levelBreakthroughsClaimed = [];
            const key = String(rewardLevel);
            if (char.levelBreakthroughsClaimed.includes(key)) return null;
            if (!Array.isArray(char.levelRewardHistory)) char.levelRewardHistory = [];

            const found = findNextTrainingBreakthroughUpgrade(char);
            char.levelBreakthroughsClaimed.push(key);

            if (!found) {
                const fallbackTP = 2;
                addLevelRewardTrainingPoints(char, fallbackTP);
                const entry = {
                    level: rewardLevel,
                    type: 'fallback_tp',
                    name: 'Training Breakthrough Reserve',
                    detail: `No training upgrade was available, so you gained +${formatPointValue(fallbackTP)} TP instead.`
                };
                char.levelRewardHistory.push({ ...entry, date: new Date().toISOString().slice(0, 10) });
                char.levelRewardHistory = char.levelRewardHistory.slice(-80);
                return entry;
            }

            const { branch, upgrade } = found;
            const currentLevel = getTrainingUpgradeLevel(char, upgrade.id);
            const amount = getBreakthroughUpgradeAmount(upgrade, currentLevel);
            getTrainingUnlocks(char)[upgrade.id] = currentLevel + amount;
            const levelLabel = upgrade.repeatable
                ? `Lv ${currentLevel + amount}/${upgrade.maxLevel}`
                : 'Unlocked';
            const entry = {
                level: rewardLevel,
                type: 'training_upgrade',
                upgradeId: upgrade.id,
                branch: branch.name,
                name: upgrade.name,
                detail: `${branch.name}: ${levelLabel}. ${upgrade.desc || 'Your training infrastructure improved.'}`
            };
            char.levelRewardHistory.push({ ...entry, date: new Date().toISOString().slice(0, 10) });
            char.levelRewardHistory = char.levelRewardHistory.slice(-80);
            return entry;
        }

        function grantLevelTrainingBreakthroughs(char, maxLevel) {
            if (!char) return [];
            return getLevelRewardBreakthroughLevels(maxLevel)
                .map(level => grantLevelTrainingBreakthrough(char, level))
                .filter(Boolean);
        }

        function grantLevelRewards(char, oldLevel = 1, newLevel = null) {
            if (!char) return { ap: 0, tp: 0, breakthroughs: [] };
            const level = Math.max(1, Math.floor(Number(newLevel || getLevel(char)) || 1));
            const legacyAP = getLegacyLevelRewardAbilityPointsForLevel(level);
            const expectedAP = getLevelRewardAbilityPointsForLevel(level);
            const hasAPTracker = Object.prototype.hasOwnProperty.call(char, 'v5LevelRewardAPGranted');
            const alreadyAP = hasAPTracker ? (Number(char.v5LevelRewardAPGranted) || 0) : Math.min(expectedAP, legacyAP);
            const missingAP = Math.max(0, +(expectedAP - alreadyAP).toFixed(2));
            if (missingAP > 0) addLevelRewardAbilityPoints(char, missingAP, 'Level reward');
            char.v5LevelRewardAPGranted = +Math.max(alreadyAP, expectedAP).toFixed(2);

            const expectedTP = getLevelRewardTrainingPointsForLevel(level);
            const alreadyTP = Number(char.v5LevelRewardTPGranted) || 0;
            const missingTP = Math.max(0, +(expectedTP - alreadyTP).toFixed(2));
            if (missingTP > 0) addLevelRewardTrainingPoints(char, missingTP);
            char.v5LevelRewardTPGranted = +Math.max(alreadyTP, expectedTP).toFixed(2);

            const breakthroughs = grantLevelTrainingBreakthroughs(char, level);
            const summary = { level, oldLevel, ap: missingAP, tp: missingTP, breakthroughs };
            char.lastLevelRewardSummary = summary;
            return summary;
        }

        function formatLevelRewardSummary(summary) {
            if (!summary) return '';
            const parts = [];
            if (summary.ap) parts.push(`+${formatPointValue(summary.ap)} AP`);
            if (summary.tp) parts.push(`+${formatPointValue(summary.tp)} TP`);
            if (summary.breakthroughs?.length) parts.push(`${summary.breakthroughs.length} training breakthrough${summary.breakthroughs.length === 1 ? '' : 's'}`);
            return parts.length ? ` Reward: ${parts.join(', ')}.` : '';
        }

        function getLegacyAvailableSkillPointCap(char) {
            const level = getLevel(char);
            const levelSP = getLegacyLevelRewardAbilityPointsForLevel(level);
            const workoutSP = Math.min(1, (char.workoutLog || []).length);
            const sagaSP = Math.min(2, Math.floor((char.completedSagas || []).length / 4));
            const milestoneSP = Math.min(2, (char.plMilestones || []).filter(id => String(id).startsWith('pl_') || String(id).startsWith('gpl_')).length);
            return Math.max(0, levelSP + workoutSP + sagaSP + milestoneSP);
        }

        function getTrainingPoints(char) {
            return Math.max(0, +(((Number(char.trainingPoints) || 0) - (Number(char.tpSpent) || 0)).toFixed(2)));
        }

        function getNextTPPurchaseTarget(char) {
            const available = getTrainingPoints(char);
            const candidates = [];
            TRAINING_BRANCHES.forEach(branch => {
                branch.upgrades.forEach(upgrade => {
                    if (!canShowTrainingUpgrade(char, upgrade)) return;
                    const level = getTrainingUpgradeLevel(char, upgrade.id);
                    const maxLevel = upgrade.repeatable ? upgrade.maxLevel : 1;
                    if (level >= maxLevel) return;
                    candidates.push({
                        name: upgrade.name,
                        type: branch.name,
                        cost: getTrainingUpgradeCost(upgrade, level),
                        available
                    });
                });
            });
            PARTNER_SLOT_UPGRADES.forEach(upgrade => {
                if (getPartnerSlotLimit(char) < upgrade.slot) {
                    candidates.push({ name: upgrade.name, type: 'Partner slot', cost: upgrade.cost, available });
                }
            });
            const owned = getOwnedPartners(char);
            PARTNER_ROSTER.forEach(partner => {
                if (!owned.includes(partner.id) && partnerSagaMet(char, partner)) {
                    candidates.push({ name: partner.name, type: 'Partner', cost: partner.cost, available });
                }
            });
            return candidates
                .filter(item => Number(item.cost) > 0)
                .sort((a, b) => Math.max(0, a.cost - available) - Math.max(0, b.cost - available) || a.cost - b.cost)[0] || null;
        }

        const PL_MILESTONE_NOTIFICATIONS = [];
        function checkAndAwardMilestones(char) {
            const pl  = getPowerLevel(char);
            const gpl = getGodPowerLevel(char);
            const events = [];
            if (!Array.isArray(char.plMilestones)) char.plMilestones = [];
            if (!Array.isArray(char.statMilestones)) char.statMilestones = [];

            PL_MILESTONES.forEach(m => {
                if (!char.plMilestones.includes(m.id) && pl >= m.threshold) {
                    char.plMilestones.push(m.id);
                    char.spEarned = (char.spEarned || 0) + m.sp;
                    events.push({ type: 'milestone', title: 'Power Level Milestone', name: m.label, detail: `Reached ${formatPL(m.threshold)} Power Level`, reward: { sp: m.sp } });
                    PL_MILESTONE_NOTIFICATIONS.push(`⚡ Power Level Milestone: ${m.label} — ${formatRewardText(m.sp, 0, true)}!`);
                }
            });

            GPL_MILESTONES.forEach(m => {
                if (!char.plMilestones.includes(m.id) && gpl >= m.threshold) {
                    char.plMilestones.push(m.id);
                    char.spEarned = (char.spEarned || 0) + m.sp;
                    events.push({ type: 'milestone', title: 'God Power Milestone', name: m.label, detail: `Reached ${formatPL(m.threshold)} God Power Level`, reward: { sp: m.sp } });
                    PL_MILESTONE_NOTIFICATIONS.push(`𒀭 God Power Milestone: ${m.label} — ${formatRewardText(m.sp, 0, true)}!`);
                }
            });

            STATS.forEach(stat => {
                STAT_MILESTONES.forEach(threshold => {
                    const key = `${stat}_${threshold}`;
                    if (!char.statMilestones.includes(key) && char.stats[stat] >= threshold) {
                        char.statMilestones.push(key);
                        char.spEarned = (char.spEarned || 0) + 1;
                        events.push({ type: 'milestone', title: 'Stat Milestone', name: `${stat} ${formatStat(threshold)}`, detail: 'A core stat crossed a major threshold.', reward: { sp: 1 } });
                        PL_MILESTONE_NOTIFICATIONS.push(`💪 Stat Milestone: ${stat} ${formatStat(threshold)} reached — +1 SP!`);
                    }
                });
            });
            return events;
        }

        function getCurrentSaga(char) {
            if (!char || !char.stats) return SAGAS[0];
            let best = SAGAS[0];
            for (let saga of SAGAS) {
                if (sagaRequirementsMet(char, saga)) best = saga;
            }
            return best;
        }

        function checkAndAwardAchievements(char) {
            const unlocked = [];
            ACHIEVEMENTS.forEach(ach => {
                if (!char.achievements.includes(ach.id) && ach.check(char)) {
                    char.achievements.push(ach.id);
                    const reward = awardAchievementReward(char, ach);
                    unlocked.push({ ...ach, reward });
                }
            });
            return unlocked;
        }

        function getTrainingUnlocks(char) {
            if (!char.trainingUnlocks || typeof char.trainingUnlocks !== 'object' || Array.isArray(char.trainingUnlocks)) {
                char.trainingUnlocks = {};
            }
            return char.trainingUnlocks;
        }

        function getTrainingUpgradeById(upgradeId) {
            for (const branch of TRAINING_BRANCHES) {
                const upgrade = branch.upgrades.find(u => u.id === upgradeId);
                if (upgrade) return { branch, upgrade };
            }
            return null;
        }

        function getTrainingUpgradeLevel(char, upgradeId) {
            const level = Number(getTrainingUnlocks(char)[upgradeId]);
            return Number.isFinite(level) ? Math.max(0, Math.floor(level)) : 0;
        }

        function getTrainingUpgradeCost(upgrade, currentLevel = 0) {
            if (upgrade.repeatable && upgrade.costGrowth) return Math.ceil(upgrade.cost * Math.pow(upgrade.costGrowth, currentLevel));
            if (upgrade.repeatable) return upgrade.cost + (upgrade.costStep || 0) * currentLevel;
            return upgrade.cost;
        }

        function getSagaById(sagaId) {
            return SAGAS.find(saga => saga.id === sagaId) || null;
        }

        function trainingSagaMet(char, upgrade) {
            if (!upgrade?.sagaId) return true;
            const saga = getSagaById(upgrade.sagaId);
            if (!saga) return true;
            if (Array.isArray(char?.completedSagas) && char.completedSagas.includes(upgrade.sagaId)) return true;
            return getCurrentSaga(char).order >= saga.order;
        }

        function trainingPrerequisitesMet(char, upgrade) {
            const ownsRequired = (upgrade.requires || []).every(reqId => getTrainingUpgradeLevel(char, reqId) > 0);
            const levelRequired = Object.entries(upgrade.requiresLevel || {}).every(([reqId, minLevel]) => getTrainingUpgradeLevel(char, reqId) >= minLevel);
            return ownsRequired && levelRequired;
        }

        function trainingRequirementsMet(char, upgrade) {
            return trainingPrerequisitesMet(char, upgrade) && trainingSagaMet(char, upgrade);
        }

        function canShowTrainingUpgrade(char, upgrade) {
            if (getTrainingUpgradeLevel(char, upgrade.id) > 0) return true;
            return trainingRequirementsMet(char, upgrade);
        }

        function getTrainingRequirementText(upgrade) {
            const parts = [];
            (upgrade.requires || [])
                .filter(reqId => !Object.prototype.hasOwnProperty.call(upgrade.requiresLevel || {}, reqId))
                .forEach(reqId => parts.push(getTrainingUpgradeById(reqId)?.upgrade?.name || reqId));
            Object.entries(upgrade.requiresLevel || {}).forEach(([reqId, minLevel]) => {
                const reqName = getTrainingUpgradeById(reqId)?.upgrade?.name || reqId;
                parts.push(`${reqName} Lv ${minLevel}`);
            });
            return parts.join(', ');
        }

        function getTrainingSagaRequirementText(upgrade) {
            if (!upgrade?.sagaId) return '';
            const saga = getSagaById(upgrade.sagaId);
            return saga ? saga.name : upgrade.sagaId;
        }

        function partnerSagaMet(char, partner) {
            if (!partner?.sagaReq) return true;
            const saga = getSagaById(partner.sagaReq);
            if (!saga) return true;
            if (Array.isArray(char?.completedSagas) && char.completedSagas.includes(partner.sagaReq)) return true;
            return getCurrentSaga(char).order >= saga.order;
        }

        function getPartnerSagaRequirementText(partner) {
            if (!partner?.sagaReq) return '';
            const saga = getSagaById(partner.sagaReq);
            return saga ? saga.name : partner.sagaReq;
        }

        function getCharacterXPBonusValue(effect) {
            if (!effect) return 0;
            if (typeof effect.characterXP === 'number') return Number(effect.characterXP) || 0;
            if (typeof effect.characterXp === 'number') return Number(effect.characterXp) || 0;
            if (typeof effect.partnerXP === 'number') return Number(effect.partnerXP) || 0;
            if (typeof effect.partnerXp === 'number') return Number(effect.partnerXp) || 0;
            return 0;
        }

        function applyTrainingEffect(effectTotals, effect, levels = 1) {
            if (!effect || levels <= 0) return;
            if (effect.statAll) {
                STATS.forEach(stat => effectTotals.statBonus[stat] += effect.statAll * levels);
            }
            if (effect.stat) {
                Object.entries(effect.stat).forEach(([stat, bonus]) => {
                    if (effectTotals.statBonus[stat] !== undefined) effectTotals.statBonus[stat] += bonus * levels;
                });
            }
            if (effect.type) {
                Object.entries(effect.type).forEach(([type, bonus]) => {
                    effectTotals.typeBonus[type] = (effectTotals.typeBonus[type] || 0) + bonus * levels;
                });
            }
            if (effect.category) {
                Object.entries(effect.category).forEach(([category, bonus]) => {
                    effectTotals.categoryBonus[category] = (effectTotals.categoryBonus[category] || 0) + bonus * levels;
                });
            }
            effectTotals.txpBonus += (effect.txp || 0) * levels;
            effectTotals.tpBonus += (effect.tp || 0) * levels;
            effectTotals.characterXPBonus += getCharacterXPBonusValue(effect) * levels;
        }

        function getTrainingEffects(char) {
            const effects = {
                statBonus: Object.fromEntries(STATS.map(stat => [stat, 0])),
                typeBonus: {},
                categoryBonus: {},
                txpBonus: 0,
                tpBonus: 0,
                characterXPBonus: 0
            };
            if (!char) return effects;
            TRAINING_BRANCHES.forEach(branch => {
                branch.upgrades.forEach(upgrade => {
                    const level = getTrainingUpgradeLevel(char, upgrade.id);
                    if (level <= 0) return;
                    applyTrainingEffect(effects, upgrade.effects, level);
                    applyTrainingEffect(effects, upgrade.effectsPerLevel, level);
                });
            });
            scaleLegacyEffectTotals(effects, getRaceTrainingEffectMultiplier(char));
            return effects;
        }

        function getTrainingStatMultiplier(char, stat, exercise) {
            const effects = getTrainingEffects(char);
            const typeBonus = exercise ? (effects.typeBonus[exercise.type] || 0) : 0;
            const category = exercise ? findExerciseCategory(exercise.name) : null;
            const categoryBonus = category ? (effects.categoryBonus[category] || 0) : 0;
            return Math.max(1, 1 + (effects.statBonus[stat] || 0) + typeBonus + categoryBonus);
        }

        function getTrainingTXPMultiplier(char) {
            return Math.max(1, 1 + getTrainingEffects(char).txpBonus);
        }

        function getTrainingTPMultiplier(char) {
            return Math.max(1, 1 + getTrainingEffects(char).tpBonus);
        }

        function getTrainingCharacterXPMultiplier(char) {
            return Math.max(1, 1 + getTrainingEffects(char).characterXPBonus);
        }

        function getPartnerById(partnerId) {
            return PARTNER_ROSTER.find(p => p.id === partnerId) || null;
        }

        function getPartnerBoons(partner) {
            const track = PARTNER_BOON_TRACKS[partner?.boonTrack] || [];
            return [...track, ...(partner?.boons || [])].sort((a, b) => a.level - b.level);
        }

        function getPartnerImagePath(partner) {
            if (partner?.image) return partner.image;
            return `${PARTNER_THUMBNAIL_DIR}${encodeURIComponent(partner?.id || 'unknown')}.webp`;
        }

        function getPartnerPlaceholder(partner) {
            return VISUAL_ASSETS.partnerFrames[partner?.tier] || VISUAL_ASSETS.partnerFrames.Ally;
        }

        function getPartnerImageSrc(partner) {
            return PARTNER_IMAGE_MODE === 'local' ? versionedAsset(getPartnerImagePath(partner)) : getPartnerPlaceholder(partner);
        }

        function getPartnerSlotLimit(char) {
            const raw = Number(char?.partnerSlots);
            return Math.max(PARTNER_DEFAULT_SLOTS, Math.min(PARTNER_MAX_SLOTS, Number.isFinite(raw) ? Math.floor(raw) : PARTNER_DEFAULT_SLOTS));
        }

        function getOwnedPartners(char) {
            if (!Array.isArray(char.ownedPartners)) char.ownedPartners = [];
            char.ownedPartners = [...new Set(char.ownedPartners)].filter(id => getPartnerById(id));
            return char.ownedPartners;
        }

        function getActivePartners(char) {
            if (!Array.isArray(char.activePartners)) char.activePartners = [];
            const owned = getOwnedPartners(char);
            const slots = getPartnerSlotLimit(char);
            char.activePartners = [...new Set(char.activePartners)].filter(id => owned.includes(id)).slice(0, slots);
            if (char.mainPartner && !char.activePartners.includes(char.mainPartner)) {
                char.mainPartner = char.activePartners[0] || null;
            }
            return char.activePartners;
        }

        function getMainPartnerId(char) {
            const active = getActivePartners(char);
            if (!active.length) {
                char.mainPartner = null;
                return null;
            }
            if (!active.includes(char.mainPartner)) char.mainPartner = active[0];
            return char.mainPartner;
        }

        function getPartnerProgress(char, partnerId) {
            if (!char.partnerLevels || typeof char.partnerLevels !== 'object' || Array.isArray(char.partnerLevels)) char.partnerLevels = {};
            const existing = char.partnerLevels[partnerId] || {};
            const level = Math.max(1, Math.floor(Number(existing.level) || 1));
            const xp = Math.max(0, Math.floor(Number(existing.xp) || 0));
            const totalXp = Math.max(xp, Math.floor(Number(existing.totalXp) || 0));
            char.partnerLevels[partnerId] = { level, xp, totalXp };
            return char.partnerLevels[partnerId];
        }

        function getPartnerXPNeeded(partner, level) {
            const power = Math.max(1, Number(partner?.powerTier) || 1);
            const base = 80 + power * 38;
            return Math.max(40, Math.round(base * Math.pow(Math.max(1, level), 1.28) * Math.pow(power, 0.36)));
        }

        function getPartnerPowerEffectScale(partner) {
            const power = Math.max(1, Number(partner?.powerTier) || 1);
            return 0.45 + Math.pow(power, 1.75) * 0.145;
        }

        function getPartnerLevelEffectScale(partner, progress, isMain = false) {
            const power = Math.max(1, Number(partner?.powerTier) || 1);
            const level = Math.max(1, Number(progress?.level) || 1);
            const perLevel = 0.0008 + Math.pow(power, 1.35) * 0.00042;
            const existingGrowthScale = 1 + ((level - 1) * perLevel);
            const loyaltyGrowthScale = 1 + ((level - 1) * PARTNER_LEVEL_BONUS_PER_LEVEL);
            const levelScale = getPartnerPowerEffectScale(partner) * existingGrowthScale * loyaltyGrowthScale;
            return levelScale * (isMain ? 1 + PARTNER_MAIN_EFFECT_BONUS : 1);
        }

        function getPartnerLegacyEffect(partner, progress) {
            const level = Math.max(1, Number(progress?.level) || 1);
            const ranks = Math.floor(level / 100);
            if (ranks <= 0) return null;
            const power = Math.max(1, Number(partner?.powerTier) || 1);
            return {
                statAll: ranks * power * 0.0015,
                txp: ranks * 0.002,
                tp: ranks * 0.0015
            };
        }

        function applyPartnerEffect(effectTotals, effect, scale = 1) {
            if (!effect) return;
            const amount = value => (Number(value) || 0) * scale;
            if (effect.statAll) {
                STATS.forEach(stat => effectTotals.statBonus[stat] += amount(effect.statAll));
            }
            if (effect.stat) {
                Object.entries(effect.stat).forEach(([stat, bonus]) => {
                    if (effectTotals.statBonus[stat] !== undefined) effectTotals.statBonus[stat] += amount(bonus);
                });
            }
            if (effect.type) {
                Object.entries(effect.type).forEach(([type, bonus]) => {
                    effectTotals.typeBonus[type] = (effectTotals.typeBonus[type] || 0) + amount(bonus);
                });
            }
            if (effect.category) {
                Object.entries(effect.category).forEach(([category, bonus]) => {
                    effectTotals.categoryBonus[category] = (effectTotals.categoryBonus[category] || 0) + amount(bonus);
                });
            }
            effectTotals.txpBonus += amount(effect.txp);
            effectTotals.tpBonus += amount(effect.tp);
            effectTotals.spBonus += amount(effect.sp);
            effectTotals.spFlat += amount(effect.spFlat);
            effectTotals.characterXPBonus += amount(getCharacterXPBonusValue(effect));
        }

        function getPartnerEffects(char) {
            const effects = {
                statBonus: Object.fromEntries(STATS.map(stat => [stat, 0])),
                typeBonus: {},
                categoryBonus: {},
                txpBonus: 0,
                tpBonus: 0,
                spBonus: 0,
                spFlat: 0,
                characterXPBonus: 0
            };
            if (!char) return effects;
            const mainPartnerId = getMainPartnerId(char);
            getActivePartners(char).forEach(partnerId => {
                const partner = getPartnerById(partnerId);
                if (!partner) return;
                const progress = getPartnerProgress(char, partnerId);
                const scale = getPartnerLevelEffectScale(partner, progress, partnerId === mainPartnerId);
                applyPartnerEffect(effects, partner.effects, scale);
                getPartnerBoons(partner).forEach(boon => {
                    if (progress.level >= boon.level) applyPartnerEffect(effects, boon.effects, scale);
                });
                applyPartnerEffect(effects, getPartnerLegacyEffect(partner, progress), scale);
            });
            applyAbsorbedPartnerEffects(effects, char);
            scaleLegacyEffectTotals(effects, getRacePartnerEffectMultiplier(char));
            return effects;
        }

        function getPartnerStatMultiplier(char, stat, exercise) {
            const effects = getPartnerEffects(char);
            const category = exercise ? findExerciseCategory(exercise.name) : null;
            const typeBonus = exercise ? (effects.typeBonus[exercise.type] || 0) : 0;
            const categoryBonus = category ? (effects.categoryBonus[category] || 0) : 0;
            return Math.max(1, 1 + (effects.statBonus[stat] || 0) + typeBonus + categoryBonus);
        }

        function getPartnerTXPMultiplier(char) {
            return Math.max(1, 1 + getPartnerEffects(char).txpBonus);
        }

        function getPartnerTPMultiplier(char) {
            return Math.max(1, 1 + getPartnerEffects(char).tpBonus);
        }

        function getPartnerSPMultiplier(char) {
            return Math.max(1, 1 + getPartnerEffects(char).spBonus);
        }

        function getPartnerSPFlatBonus(char) {
            return Math.max(0, getPartnerEffects(char).spFlat);
        }

        function getPartnerCharacterXPMultiplier(char) {
            return Math.max(1, 1 + getPartnerEffects(char).characterXPBonus);
        }

        function addPartnerXP(char, partnerId, xpAmount) {
            const partner = getPartnerById(partnerId);
            if (!partner || xpAmount <= 0) return null;
            const progress = getPartnerProgress(char, partnerId);
            const beforeLevel = progress.level;
            progress.xp += Math.floor(xpAmount);
            progress.totalXp += Math.floor(xpAmount);
            while (progress.xp >= getPartnerXPNeeded(partner, progress.level)) {
                progress.xp -= getPartnerXPNeeded(partner, progress.level);
                progress.level += 1;
            }
            return {
                id: partnerId,
                name: partner.name,
                xp: Math.floor(xpAmount),
                beforeLevel,
                afterLevel: progress.level,
                leveled: progress.level > beforeLevel
            };
        }

        function awardPartnerXP(char, txpGained) {
            const active = getActivePartners(char);
            const mainPartnerId = getMainPartnerId(char);
            if (!active.length || txpGained <= 0) return [];
            const raceXpMult = getRacePartnerXPMultiplier(char);
            return active.map(partnerId => {
                const partner = getPartnerById(partnerId);
                if (!partner) return null;
                const power = Math.max(1, Number(partner.powerTier) || 1);
                const baseShare = 0.32 + Math.min(0.28, power * 0.015);
                const mainBoost = partnerId === mainPartnerId ? 1 + PARTNER_MAIN_XP_BONUS : 1;
                return addPartnerXP(char, partnerId, Math.round(txpGained * baseShare * mainBoost * raceXpMult));
            }).filter(Boolean);
        }

        function formatPartnerXPSummary(summary) {
            if (!summary || !summary.length) return '';
            const leveled = summary.filter(item => item.leveled);
            if (leveled.length) {
                return `\nCharacters: ${leveled.map(item => `${item.name} Lv ${item.afterLevel}`).join(', ')}`;
            }
            return `\nCharacters gained XP: ${summary.slice(0, 3).map(item => `${item.name} +${item.xp}`).join(', ')}${summary.length > 3 ? '...' : ''}`;
        }

        function getSetDetails(inputData) {
            if (!inputData) return [];
            if (Array.isArray(inputData.setsList)) return inputData.setsList;
            if (Array.isArray(inputData.setsDetail)) return inputData.setsDetail;
            return [];
        }

        function getCardioBaseSpeed(exercise) {
            const name = exercise?.name || '';
            if (name.includes('Walk')) return 5;
            if (name.includes('Intervals')) return 10;
            if (name.includes('Outdoor Rowing')) return 8.5;
            if (name.includes('Run')) return 8;
            if (name.includes('Ride')) return 18;
            if (name.includes('Swim')) return 2;
            return 8;
        }

        function getCardioSpeedKmh(exercise, inputData) {
            const directSpeed = parseFloat(inputData?.speed);
            if (directSpeed > 0) return directSpeed;
            const distance = parseFloat(inputData?.distance) || 0;
            const duration = parseFloat(inputData?.duration) || 0;
            if (!distance || !duration) return null;
            return distance / (duration / 60);
        }

        function getCardioSpeedMultiplier(exercise, inputData) {
            const speed = getCardioSpeedKmh(exercise, inputData);
            if (!speed) return 1;
            const base = getCardioBaseSpeed(exercise);
            const ratio = speed / base;
            return Math.max(BALANCE_RULES.speedMultiplierMin, Math.min(BALANCE_RULES.speedMultiplierMax, ratio));
        }

        function getExerciseVolume(exercise, inputData) {
            let volume = 0;
            const setsList = getSetDetails(inputData);
            if (exercise.type === 'weighted') {
                volume = setsList.length
                    ? setsList.reduce((sum, set) => sum + ((parseFloat(set.weight) || 0) * (parseInt(set.reps) || 0)), 0)
                    : (inputData.sets || 0) * (inputData.reps || 0) * (inputData.weight || 0);
            } else if (exercise.type === 'bodyweight') {
                volume = setsList.length
                    ? setsList.reduce((sum, set) => sum + (parseInt(set.reps) || 0), 0)
                    : (inputData.sets || 0) * (inputData.reps || 0);
            } else if (exercise.type === 'timed_hold') {
                const totalSeconds = setsList.length
                    ? setsList.reduce((sum, set) => sum + (parseFloat(set.seconds) || 0), 0)
                    : (inputData.sets || 0) * (inputData.seconds || 0);
                // Six seconds equals one hold-volume unit, preserving old 3 x 10 style scale around 3 x 60s holds.
                volume = totalSeconds / 6;
            } else if (exercise.type === 'cardio_distance') {
                volume = (inputData.distance || 0) * getCardioSpeedMultiplier(exercise, inputData);
            } else if (exercise.type === 'cardio_duration') {
                volume = inputData.duration || 0;
            }
            return volume;
        }

        function getExerciseVolumeForStat(exercise, inputData, stat) {
            if (exercise?.type === 'cardio_distance' && exercise.distanceProfile && exercise.speedProfile) {
                const distance = Math.max(0, parseFloat(inputData?.distance) || 0);
                if (!distance) return 0;
                const speed = getCardioSpeedKmh(exercise, inputData);
                const base = getCardioBaseSpeed(exercise);
                const speedRatio = speed ? speed / base : 1;
                const clampedRatio = Math.max(BALANCE_RULES.speedMultiplierMin, Math.min(BALANCE_RULES.speedMultiplierMax, speedRatio));
                const distanceBias = Number(exercise.distanceProfile[stat]) || 1;
                const speedBias = Number(exercise.speedProfile[stat]) || 1;
                return distance * distanceBias * (1 + ((clampedRatio - 1) * speedBias));
            }
            return getExerciseVolume(exercise, inputData);
        }

        function getExerciseStatGains(exercise, inputData, char = getActiveCharacter()) {
            const weights = exercise.weights || {};

            // Use raw floats — NO rounding here. Stats accumulate as decimals
            // (stored with toFixed(4) precision). This ensures light exercises
            // and cardio always contribute; gains aggregate correctly over sessions.
            const gains = {};
            STATS.forEach(stat => {
                if (stat === 'GKI' && !isGodKiUnlocked(char)) {
                    gains[stat] = 0;
                    return;
                }
                const raceMult = char ? getRaceStatMult(char, stat) : 1;
                const trainingMult = char ? getTrainingStatMultiplier(char, stat, exercise) : 1;
                const partnerMult = char ? getPartnerStatMultiplier(char, stat, exercise) : 1;
                const volume = getExerciseVolumeForStat(exercise, inputData || {}, stat);
                gains[stat] = volume * (weights[stat] || 0) * raceMult * trainingMult * partnerMult;
            });
            return gains;
        }

        function calculateExerciseXP(exercise, inputData) {
            return getExerciseStatGains(exercise, inputData, getActiveCharacter());
        }

        function unlockTransformationsAndAbilities(char) {
            const level = getLevel(char);
            if (!Array.isArray(char.unlockedTransformations)) char.unlockedTransformations = ['base'];
            TRANSFORMATIONS.forEach(trans => {
                if (!transformationAllowedForRace(char?.race, trans)) return;
                if (!char.unlockedTransformations.includes(trans.id)) {
                    const pl = getPowerLevel(char);
                    const reqs = trans.reqs || {};
                    if ((!reqs.sagaId || char.completedSagas.includes(reqs.sagaId)) &&
                        (!reqs.level || level >= reqs.level) &&
                        (!(reqs.PL || reqs.pl || reqs.powerLevel) || pl >= Number(reqs.PL || reqs.pl || reqs.powerLevel)) &&
                        STATS.every(s => !reqs[s] || char.stats[s] >= reqs[s])) {
                        char.unlockedTransformations.push(trans.id);
                    }
                }
            });
            char.equippedTransformations = (char.equippedTransformations || ['base']).filter(id => id === 'base' || getAvailableTransformations(char).some(trans => trans.id === id)).slice(0, getTransformationSlotLimit(char));
            if (!char.equippedTransformations.length) char.equippedTransformations = ['base'];
            if (!getAvailableTransformations(char).some(trans => trans.id === char.activeTransformation)) char.activeTransformation = char.equippedTransformations[0] || 'base';
        }

        function isSameDay(d1, d2) {
            return d1.getFullYear() === d2.getFullYear() && d1.getMonth() === d2.getMonth() && d1.getDate() === d2.getDate();
        }

        function parseLocalDate(dateStr) {
            if (!dateStr) return null;
            const d = new Date(`${dateStr}T00:00:00`);
            return Number.isNaN(d.getTime()) ? null : d;
        }

        function formatLocalDateKey(date) {
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        }

        function getCurrentWeekStartKey(date = new Date()) {
            const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
            const day = d.getDay() || 7;
            d.setDate(d.getDate() + 1 - day);
            return formatLocalDateKey(d);
        }

        function getCurrentWeekEndKey(date = new Date()) {
            const d = new Date(date.getFullYear(), date.getMonth(), date.getDate());
            const day = d.getDay() || 7;
            d.setDate(d.getDate() + 7 - day);
            return formatLocalDateKey(d);
        }

        function daysBetweenDates(fromDateStr, toDateStr) {
            const from = parseLocalDate(fromDateStr);
            const to = parseLocalDate(toDateStr);
            if (!from || !to) return 0;
            return Math.round((to - from) / 86400000);
        }

        function getWorkoutDates(char) {
            return (char.workoutLog || [])
                .filter(w => typeof workoutHasRealTraining !== 'function' || workoutHasRealTraining(w))
                .map(w => w.date)
                .filter(date => parseLocalDate(date));
        }

        function getLatestWorkoutDate(char) {
            const dates = getWorkoutDates(char);
            if (char.lastWorkoutDate && parseLocalDate(char.lastWorkoutDate)) dates.push(char.lastWorkoutDate);
            dates.sort((a, b) => a.localeCompare(b));
            return dates[dates.length - 1] || null;
        }

        function addDaysToDateKey(dateStr, days) {
            const date = parseLocalDate(dateStr);
            if (!date) return dateStr;
            date.setDate(date.getDate() + days);
            return formatLocalDateKey(date);
        }

        function getTodayKey() {
            return formatLocalDateKey(new Date());
        }

        function getRecoveryStatFloors(char) {
            const baseline = getStartingStatsForRace(char?.race || 'earthling');
            if (!isGodKiUnlocked(char)) baseline.GKI = 0;
            return Object.fromEntries(STATS.map(stat => [stat, Number(baseline[stat]) || 0]));
        }

        function ensureRecoveryState(char) {
            if (!char) return {};
            if (!char.recovery || typeof char.recovery !== 'object' || Array.isArray(char.recovery)) char.recovery = {};
            if (!Array.isArray(char.recovery.events)) char.recovery.events = [];
            if (!char.startedAt || !parseLocalDate(char.startedAt)) {
                const dated = (char.workoutLog || [])
                    .map(workout => workout.date)
                    .filter(date => parseLocalDate(date))
                    .sort((a, b) => a.localeCompare(b));
                char.startedAt = dated[0] || getTodayKey();
            }
            char.recovery.startedAt = char.startedAt;
            return char.recovery;
        }

        function isRestDayExerciseName(name) {
            return String(name || '').trim().toLowerCase() === RECOVERY_CONFIG.restExerciseName.toLowerCase();
        }

        function isMeditationExerciseName(name) {
            return String(name || '').trim().toLowerCase() === 'meditation';
        }

        function isWalkingExerciseName(name) {
            return /walk/i.test(String(name || ''));
        }

        function isRunningExerciseName(name) {
            return /run|interval/i.test(String(name || ''));
        }

        function isRestEntry(entry) {
            return entry?.recoveryType === 'rest_day'
                || entry?.type === 'recovery_rest'
                || isRestDayExerciseName(entry?.name || entry?.exercise?.name);
        }

        function isRecoveryOnlyWorkout(workout) {
            const exercises = workout?.exercises || [];
            return exercises.length > 0 && exercises.every(isRestEntry);
        }

        function isRealTrainingEntry(entry) {
            const name = entry?.name || entry?.exercise?.name || '';
            if (isRestEntry(entry) || isMeditationExerciseName(name) || isWalkingExerciseName(name)) return false;
            return true;
        }

        function workoutHasRealTraining(workout) {
            return (workout?.exercises || []).some(isRealTrainingEntry);
        }

        function getRealTrainingDateSet(char) {
            const dates = new Set();
            (char?.workoutLog || []).forEach(workout => {
                if (workout?.date && parseLocalDate(workout.date) && workoutHasRealTraining(workout)) dates.add(workout.date);
            });
            return dates;
        }

        function getRestWorkoutDates(char, beforeDate = null) {
            return (char?.workoutLog || [])
                .filter(workout => workout?.date && parseLocalDate(workout.date))
                .filter(workout => !beforeDate || workout.date < beforeDate)
                .filter(workout => (workout.exercises || []).some(isRestEntry))
                .map(workout => workout.date)
                .sort((a, b) => a.localeCompare(b));
        }

        function getLastRestDate(char, beforeDate = null) {
            return getRestWorkoutDates(char, beforeDate).slice(-1)[0] || null;
        }

        function getStatGainMapFromEntries(entries) {
            const totals = createZeroStatMap();
            entries.forEach(entry => {
                const gains = entry?.statGains || entry?.gains || {};
                if (isRestEntry(entry)) return;
                STATS.forEach(stat => { totals[stat] += Number(gains[stat]) || 0; });
            });
            return totals;
        }

        function getWorkoutTrainingStatTotals(workout) {
            return getStatGainMapFromEntries(workout?.exercises || []);
        }

        function sumTrainingGainsForWindow(char, startDate, endDate) {
            const totals = createZeroStatMap();
            (char?.workoutLog || []).forEach(workout => {
                if (!workout?.date || workout.date < startDate || workout.date > endDate) return;
                const gains = getWorkoutTrainingStatTotals(workout);
                STATS.forEach(stat => { totals[stat] += gains[stat]; });
            });
            return totals;
        }

        function getRealTrainingDatesSinceRest(char, previousRest, dateKey, hasPreviousRest) {
            return [...getRealTrainingDateSet(char)]
                .filter(date => hasPreviousRest ? date > previousRest : date >= previousRest)
                .filter(date => date <= dateKey)
                .sort((a, b) => a.localeCompare(b));
        }

        function sumTrainingGainsForDates(char, dates) {
            const wanted = new Set(dates || []);
            const totals = createZeroStatMap();
            if (!wanted.size) return totals;
            (char?.workoutLog || []).forEach(workout => {
                if (!workout?.date || !wanted.has(workout.date)) return;
                const gains = getWorkoutTrainingStatTotals(workout);
                STATS.forEach(stat => { totals[stat] += gains[stat]; });
            });
            return totals;
        }

        function calculateRestDayBonus(char, dateKey = getTodayKey()) {
            ensureRecoveryState(char);
            const actualPreviousRest = getLastRestDate(char, dateKey);
            const previousRest = actualPreviousRest || char.startedAt || dateKey;
            const trainingDates = getRealTrainingDatesSinceRest(char, previousRest, dateKey, !!actualPreviousRest);
            const trainingDaysSinceLastRest = trainingDates.length;
            const calendarDaysSinceLastRest = Math.max(0, daysBetweenDates(previousRest, dateKey));
            const multiplier = Math.min(RECOVERY_CONFIG.restMultiplierCap, RECOVERY_CONFIG.restMultiplierPerDay * trainingDaysSinceLastRest);
            const lookbackDays = Math.min(RECOVERY_CONFIG.restLookbackCapDays, Math.max(0, trainingDaysSinceLastRest));
            const lookbackTrainingDates = trainingDates.slice(-lookbackDays);
            const startDate = lookbackTrainingDates[0] || dateKey;
            const baseGains = sumTrainingGainsForDates(char, lookbackTrainingDates);
            const gains = createZeroStatMap();
            STATS.forEach(stat => {
                if (stat === 'GKI' && !isGodKiUnlocked(char)) {
                    gains[stat] = 0;
                    return;
                }
                gains[stat] = +(baseGains[stat] * multiplier).toFixed(4);
            });
            return {
                previousRest,
                daysSinceLastRest: trainingDaysSinceLastRest,
                trainingDaysSinceLastRest,
                calendarDaysSinceLastRest,
                multiplier,
                lookbackDays,
                lookbackTrainingDates,
                startDate,
                gains
            };
        }

        function refreshRestDayWorkoutGains(char) {
            (char?.workoutLog || []).forEach(workout => {
                (workout.exercises || []).forEach(entry => {
                    if (!isRestEntry(entry)) return;
                    const bonus = calculateRestDayBonus(char, workout.date || getTodayKey());
                    entry.recoveryType = 'rest_day';
                    entry.type = 'recovery_rest';
                    entry.category = 'recovery';
                    entry.muscle = 'recovery';
                    entry.inputs = {
                        ...(entry.inputs || {}),
                        daysSinceLastRest: bonus.trainingDaysSinceLastRest,
                        trainingDaysSinceLastRest: bonus.trainingDaysSinceLastRest,
                        calendarDaysSinceLastRest: bonus.calendarDaysSinceLastRest,
                        multiplier: bonus.multiplier,
                        lookbackDays: bonus.lookbackDays
                    };
                    entry.statGains = bonus.gains;
                });
            });
        }

        function getWeekStartKeyForDateKey(dateKey) {
            const d = parseLocalDate(dateKey);
            if (!d) return getCurrentWeekStartKey();
            return getCurrentWeekStartKey(d);
        }

        function getWeekEndKeyForStart(weekStartKey) {
            return addDaysToDateKey(weekStartKey, 6);
        }

        function getRecoveryGroupForEntry(entry) {
            if (isRestEntry(entry)) return 'recovery';
            const name = entry?.name || entry?.exercise?.name || '';
            return MUSCLE_GROUPS[name] || entry?.muscle || entry?.category || findExerciseCategory(name);
        }

        function getWeeklyCoverageCounts(char, weekStartKey, weekEndKey) {
            const counts = Object.fromEntries(RECOVERY_CONFIG.weeklyGroups.map(group => [group, 0]));
            (char?.workoutLog || []).forEach(workout => {
                if (!workout?.date || workout.date < weekStartKey || workout.date > weekEndKey) return;
                (workout.exercises || []).forEach(entry => {
                    const group = getRecoveryGroupForEntry(entry);
                    if (Object.prototype.hasOwnProperty.call(counts, group)) counts[group] += 1;
                });
            });
            return counts;
        }

        function getRecoveryCategoryProfiles() {
            if (window.__DBZ_RECOVERY_CATEGORY_PROFILES__) return window.__DBZ_RECOVERY_CATEGORY_PROFILES__;
            const profiles = Object.fromEntries(RECOVERY_CONFIG.weeklyGroups.map(group => [group, createZeroStatMap()]));
            const addWeights = (group, exercise) => {
                if (!profiles[group] || !exercise?.weights) return;
                STATS.forEach(stat => {
                    if (stat === 'GKI') return;
                    profiles[group][stat] += Math.max(0, Number(exercise.weights[stat]) || 0);
                });
            };
            Object.entries(EXERCISE_DB.strength || {}).forEach(([group, exercises]) => {
                (exercises || []).forEach(exercise => addWeights(group, exercise));
            });
            Object.values(EXERCISE_DB.cardio || {}).forEach(exercises => (exercises || []).forEach(exercise => addWeights('cardio', exercise)));
            Object.values(EXERCISE_DB.martial || {}).forEach(exercises => (exercises || []).forEach(exercise => addWeights('martial', exercise)));
            Object.values(EXERCISE_DB.flexibility || {}).forEach(exercises => (exercises || []).forEach(exercise => addWeights('flexibility', exercise)));
            Object.values(profiles).forEach(profile => {
                const max = Math.max(...STATS.map(stat => Number(profile[stat]) || 0), 0);
                STATS.forEach(stat => { profile[stat] = max > 0 ? profile[stat] / max : 0; });
            });
            window.__DBZ_RECOVERY_CATEGORY_PROFILES__ = profiles;
            return profiles;
        }

        function getWeeklyRiskGroups(char, dateKey = getTodayKey()) {
            const weekStart = getWeekStartKeyForDateKey(dateKey);
            const weekEnd = getWeekEndKeyForStart(weekStart);
            const counts = getWeeklyCoverageCounts(char, weekStart, weekEnd);
            return RECOVERY_CONFIG.weeklyGroups.filter(group => (counts[group] || 0) < RECOVERY_CONFIG.weeklyRequiredExercises);
        }

        function buildWeeklyDecayRatesForCounts(counts) {
            const profiles = getRecoveryCategoryProfiles();
            const rates = createZeroStatMap();
            const missedGroups = [];
            RECOVERY_CONFIG.weeklyGroups.forEach(group => {
                if ((counts[group] || 0) >= RECOVERY_CONFIG.weeklyRequiredExercises) return;
                missedGroups.push(group);
                const profile = profiles[group] || {};
                STATS.forEach(stat => {
                    rates[stat] += (Number(profile[stat]) || 0) * RECOVERY_CONFIG.weeklyCategoryMaxDecay;
                });
            });
            STATS.forEach(stat => {
                if (stat === 'GKI') rates[stat] = 0;
                rates[stat] = Math.min(RECOVERY_CONFIG.weeklyStatCap, rates[stat]);
            });
            return { rates, missedGroups };
        }

        function buildRecoveryDecayEvents(char, asOfDate = getTodayKey()) {
            ensureRecoveryState(char);
            const start = char.startedAt || asOfDate;
            const events = [];
            const realTrainingDates = getRealTrainingDateSet(char);
            let nonTrainingStreak = 0;
            for (let dateKey = start; dateKey <= asOfDate; dateKey = addDaysToDateKey(dateKey, 1)) {
                if (realTrainingDates.has(dateKey)) {
                    nonTrainingStreak = 0;
                    continue;
                }
                nonTrainingStreak += 1;
                if (nonTrainingStreak > RECOVERY_CONFIG.noTrainingGraceDays) {
                    events.push({
                        date: dateKey,
                        type: 'daily_decay',
                        name: 'No-log Decay',
                        recoveryEvent: true,
                        rates: Object.fromEntries(STATS.map(stat => [stat, stat === 'GKI' && !isGodKiUnlocked(char) ? 0 : RECOVERY_CONFIG.dailyDecayRate])),
                        nonTrainingDays: nonTrainingStreak
                    });
                }
            }

            const currentWeekStart = getWeekStartKeyForDateKey(asOfDate);
            for (let weekStart = getWeekStartKeyForDateKey(start); weekStart < currentWeekStart; weekStart = addDaysToDateKey(weekStart, 7)) {
                const weekEnd = getWeekEndKeyForStart(weekStart);
                const counts = getWeeklyCoverageCounts(char, weekStart, weekEnd);
                const { rates, missedGroups } = buildWeeklyDecayRatesForCounts(counts);
                if (!missedGroups.length || !STATS.some(stat => rates[stat] > 0)) continue;
                events.push({
                    date: weekEnd,
                    type: 'weekly_decay',
                    name: 'Weekly Variety Decay',
                    recoveryEvent: true,
                    rates,
                    missedGroups,
                    counts
                });
            }
            return events;
        }

        function getRecoveryHistoryEvents(char) {
            return (char?.recovery?.events || []).filter(event => event?.date && event?.recoveryEvent);
        }

        function getRecoveryEventTotals(event, runningStats, char) {
            const totals = createZeroStatMap();
            const floors = getRecoveryStatFloors(char);
            if (event?.rates && typeof event.rates === 'object') {
                STATS.forEach(stat => {
                    const rate = Math.max(0, Number(event.rates[stat]) || 0);
                    if (!rate || (stat === 'GKI' && !isGodKiUnlocked(char))) return;
                    const current = Number(runningStats[stat]) || 0;
                    const floor = Number(floors[stat]) || 0;
                    const next = Math.max(floor, current * (1 - rate));
                    totals[stat] = +(next - current).toFixed(4);
                });
                return totals;
            }
            const gains = event?.statGains || {};
            STATS.forEach(stat => { totals[stat] = Number(gains[stat]) || 0; });
            return totals;
        }

        function applyRecoveryDeltaToStats(char, runningStats, totals) {
            const floors = getRecoveryStatFloors(char);
            STATS.forEach(stat => {
                const delta = Number(totals[stat]) || 0;
                const next = (Number(runningStats[stat]) || 0) + delta;
                runningStats[stat] = delta < 0 ? Math.max(Number(floors[stat]) || 0, next) : next;
            });
        }

        function getNoTrainingDecayStatus(char, dateKey = getTodayKey()) {
            ensureRecoveryState(char);
            const realTrainingDates = getRealTrainingDateSet(char);
            if (realTrainingDates.has(dateKey)) return { active: false, nonTrainingDays: 0, rate: 0 };
            const lastReal = [...realTrainingDates].filter(date => date <= dateKey).sort((a, b) => a.localeCompare(b)).slice(-1)[0];
            const nonTrainingDays = lastReal ? Math.max(0, daysBetweenDates(lastReal, dateKey)) : Math.max(1, daysBetweenDates(char.startedAt || dateKey, dateKey) + 1);
            const decayDays = Math.max(0, nonTrainingDays - RECOVERY_CONFIG.noTrainingGraceDays);
            return { active: decayDays > 0, nonTrainingDays, rate: decayDays > 0 ? RECOVERY_CONFIG.dailyDecayRate : 0 };
        }

        function getRecoveryDashboardStatus(char) {
            ensureRecoveryState(char);
            const today = getTodayKey();
            const lastRest = getLastRestDate(char, null);
            const restBonus = calculateRestDayBonus(char, today);
            const noLog = getNoTrainingDecayStatus(char, today);
            const riskGroups = getWeeklyRiskGroups(char, today);
            return {
                lastRestText: lastRest ? `${daysBetweenDates(lastRest, today)} day${daysBetweenDates(lastRest, today) === 1 ? '' : 's'} ago` : 'None yet',
                restBonusText: `${Math.round(restBonus.multiplier * 1000) / 10}% (${restBonus.trainingDaysSinceLastRest} training day${restBonus.trainingDaysSinceLastRest === 1 ? '' : 's'})`,
                noLogText: noLog.active ? `Active -${Math.round(noLog.rate * 1000) / 10}%/day` : `Safe (${noLog.nonTrainingDays}/${RECOVERY_CONFIG.noTrainingGraceDays})`,
                noLogActive: noLog.active,
                weeklyRiskText: riskGroups.length ? `${riskGroups.slice(0, 3).map(g => g[0].toUpperCase() + g.slice(1)).join(', ')}${riskGroups.length > 3 ? ` +${riskGroups.length - 3}` : ''}` : 'None'
            };
        }

        function refreshRecoveryAndHistory(char, asOfDate = getTodayKey()) {
            if (!char) return;
            ensureRecoveryState(char);
            refreshRestDayWorkoutGains(char);
            char.recovery.events = buildRecoveryDecayEvents(char, asOfDate);
            rebuildHistoryFromWorkoutLog(char);
            applyLatestHistoryStatsToCharacter(char);
        }

        function sortWorkoutLogChronologically(char) {
            if (!Array.isArray(char.workoutLog)) return;
            char.workoutLog = char.workoutLog
                .map((workout, index) => ({ workout, index }))
                .sort((a, b) => {
                    const dateCmp = String(a.workout.date || '').localeCompare(String(b.workout.date || ''));
                    return dateCmp || a.index - b.index;
                })
                .map(item => item.workout);
        }

        function recalculateWorkoutStreaks(char) {
            const uniqueDates = [...new Set(getWorkoutDates(char))].sort((a, b) => a.localeCompare(b));
            if (!uniqueDates.length) {
                char.currentStreak = 0;
                char.longestStreak = 0;
                char.lastWorkoutDate = null;
                return;
            }

            let current = 0;
            let longest = 0;
            let prev = null;
            uniqueDates.forEach(date => {
                current = prev && daysBetweenDates(prev, date) === 1 ? current + 1 : 1;
                longest = Math.max(longest, current);
                prev = date;
            });
            char.currentStreak = current;
            char.longestStreak = longest;
            char.lastWorkoutDate = uniqueDates[uniqueDates.length - 1];
        }

        function updateStreak(char) {
            sortWorkoutLogChronologically(char);
            recalculateWorkoutStreaks(char);
        }

        function saveState(options = {}) {
            state.version = GAME_VERSION;
            state.schemaVersion = SAVE_SCHEMA_VERSION;
            state.lastSavedAt = new Date().toISOString();
            return window.DBZV6Storage.save(state, options).catch(error => {
                console.error('Unable to save game state:', error);
                v6Alert('Save failed. Export a backup before closing the game.', 'error');
                return false;
            });
        }

        function backupLegacySave(rawSave) {
            if (!rawSave || localStorage.getItem('dbfitness_save_backup_pre_v2')) return;
            try {
                localStorage.setItem('dbfitness_save_backup_pre_v2', rawSave);
            } catch (e) {
                console.warn('Unable to create pre-v2 save backup:', e);
            }
        }

        function ensureTechniqueStatCompatibility(c, fromSchema, hadTechniqueStat) {
            if (!c || fromSchema >= 28 || hadTechniqueStat) return;
            const starterTec = Number(getStartingStatsForRace(c.race || 'earthling').TEC) || 0;
            c.stats.TEC = Math.max(Number(c.stats.TEC) || 0, starterTec);
            (c.history || []).forEach(snapshot => {
                if (!snapshot.stats || typeof snapshot.stats !== 'object') snapshot.stats = {};
                if (Number.isFinite(Number(snapshot.stats.TEC))) return;
                snapshot.stats.TEC = snapshot.baseline
                    ? starterTec
                    : Math.max(starterTec, Number(c.stats.TEC) || starterTec);
            });
            (c.weeklyCoverageBonuses || []).forEach(bonus => {
                if (!bonus || !Array.isArray(bonus.groups)) return;
                bonus.appliesTo = 'all non-locked stats including TEC';
            });
        }

        function migrateCharacter(c, fromSchema = SAVE_SCHEMA_VERSION) {
            if (!c) return;
            if (!c.stats) c.stats = {};
            const hadTechniqueStat = Object.prototype.hasOwnProperty.call(c.stats, 'TEC');
            STATS.forEach(stat => {
                const val = Number(c.stats[stat]);
                c.stats[stat] = Number.isFinite(val) ? val : 0;
            });
            if (!Array.isArray(c.workoutLog)) c.workoutLog = [];
            ensureRecoveryState(c);
            if (!Array.isArray(c.completedSagas)) c.completedSagas = [];
            if (!Array.isArray(c.unlockedTransformations)) c.unlockedTransformations = ['base'];
            if (!c.unlockedTransformations.includes('base')) c.unlockedTransformations.unshift('base');
            if (!c.activeTransformation || !c.unlockedTransformations.includes(c.activeTransformation)) c.activeTransformation = 'base';
            if (!c.purchasedAbilities) c.purchasedAbilities = {};
            if (!Array.isArray(c.achievements)) c.achievements = [];
            if (!Array.isArray(c.achievementRewardsClaimed)) {
                c.achievementRewardsClaimed = fromSchema < 16 ? [...new Set(c.achievements)] : [];
            }
            if (typeof ensureDragonBallState === 'function') ensureDragonBallState(c);
            if (!Array.isArray(c.spFragmentHistory)) c.spFragmentHistory = [];
            if (!Array.isArray(c.statsGoalRewardsClaimed)) c.statsGoalRewardsClaimed = [];
            if (!Array.isArray(c.plMilestones)) c.plMilestones = [];
            if (!Array.isArray(c.statMilestones)) c.statMilestones = [];
            if (!Array.isArray(c.history)) c.history = [];
            if (!c.personalRecords) c.personalRecords = {};
            if (!c.race) c.race = 'earthling';
            ensureTechniqueStatCompatibility(c, fromSchema, hadTechniqueStat);
            if (c.setupComplete === undefined) c.setupComplete = hasCharacterTrainingProgress(c);
            if (!hasCharacterTrainingProgress(c) && isEmptyStatMap(c.stats)) applyStartingStatsForRace(c, c.race);
            if (!c.startingStatsAppliedRace && isStarterStatProfile(c)) c.startingStatsAppliedRace = c.race;
            if (!c.dailyMissions || !Array.isArray(c.dailyMissions.completed)) c.dailyMissions = { date: null, completed: [] };
            if (c.lastAdjustDate === undefined) c.lastAdjustDate = null;
            if (c.lastWorkoutDate === undefined) c.lastWorkoutDate = null;
            if (c.zenkaiReady === undefined) c.zenkaiReady = false;
            if (!Array.isArray(c.bodyWeightLog)) c.bodyWeightLog = [];
            if (c.activeArc === undefined) c.activeArc = null;
            if (!Array.isArray(c.completedArcs)) c.completedArcs = [];
            if (!Array.isArray(c.tpHistory)) c.tpHistory = [];
            if (!c.tpWeekly) c.tpWeekly = {};
            Object.keys(c.tpWeekly).forEach(weekKey => ensureWeeklyTrainingShape(c.tpWeekly[weekKey]));
            if (!Array.isArray(c.weeklyCoverageBonuses)) c.weeklyCoverageBonuses = [];
            if (!Array.isArray(c.levelBreakthroughsClaimed)) c.levelBreakthroughsClaimed = [];
            if (!Array.isArray(c.levelRewardHistory)) c.levelRewardHistory = [];
            if (!c.trainingUnlocks || typeof c.trainingUnlocks !== 'object' || Array.isArray(c.trainingUnlocks)) c.trainingUnlocks = {};
            TRAINING_BRANCHES.forEach(branch => {
                branch.upgrades.forEach(upgrade => {
                    const level = Number(c.trainingUnlocks[upgrade.id]);
                    c.trainingUnlocks[upgrade.id] = Number.isFinite(level) ? Math.max(0, Math.floor(level)) : 0;
                });
            });
            if (!Array.isArray(c.ownedPartners)) c.ownedPartners = [];
            if (!Array.isArray(c.activePartners)) c.activePartners = [];
            c.ownedPartners = migratePartnerIdList(c.ownedPartners);
            const slotVal = Number(c.partnerSlots);
            c.partnerSlots = Math.max(PARTNER_DEFAULT_SLOTS, Math.min(PARTNER_MAX_SLOTS, Number.isFinite(slotVal) ? Math.floor(slotVal) : PARTNER_DEFAULT_SLOTS));
            c.activePartners = migratePartnerIdList(c.activePartners).filter(id => c.ownedPartners.includes(id)).slice(0, c.partnerSlots);
            if (c.mainPartner) c.mainPartner = migratePartnerId(c.mainPartner);
            if (!c.mainPartner || !c.activePartners.includes(c.mainPartner)) c.mainPartner = c.activePartners[0] || null;
            if (!c.partnerLevels || typeof c.partnerLevels !== 'object' || Array.isArray(c.partnerLevels)) c.partnerLevels = {};
            Object.entries(PARTNER_ID_ALIASES).forEach(([oldId, newId]) => {
                if (!newId || !c.partnerLevels[oldId]) return;
                if (!c.partnerLevels[newId]) {
                    c.partnerLevels[newId] = c.partnerLevels[oldId];
                } else {
                    c.partnerLevels[newId] = {
                        level: Math.max(Number(c.partnerLevels[newId].level) || 1, Number(c.partnerLevels[oldId].level) || 1),
                        xp: Math.max(Number(c.partnerLevels[newId].xp) || 0, Number(c.partnerLevels[oldId].xp) || 0),
                        totalXp: Math.max(Number(c.partnerLevels[newId].totalXp) || 0, Number(c.partnerLevels[oldId].totalXp) || 0)
                    };
                }
                delete c.partnerLevels[oldId];
            });
            c.ownedPartners.forEach(id => getPartnerProgress(c, id));
            ['totalTXP', 'spEarned', 'spSpent', 'trainingPoints', 'tpSpent', 'tpCarry', 'currentStreak', 'longestStreak', 'partnerSpCarry'].forEach(key => {
                const val = Number(c[key]);
                c[key] = Number.isFinite(val) ? val : 0;
            });
            ['v5LevelRewardAPGranted', 'v5LevelRewardTPGranted'].forEach(key => {
                if (!Object.prototype.hasOwnProperty.call(c, key)) return;
                const val = Number(c[key]);
                c[key] = Number.isFinite(val) ? val : 0;
            });
            if (fromSchema < 14) {
                const availableSP = Math.max(0, c.spEarned - c.spSpent);
                const availableCap = getLegacyAvailableSkillPointCap(c);
                if (availableSP > availableCap) {
                    c.spLegacyRebalanced = {
                        from: availableSP,
                        to: availableCap,
                        schema: SAVE_SCHEMA_VERSION,
                        date: new Date().toISOString().slice(0, 10)
                    };
                    c.spEarned = c.spSpent + availableCap;
                }
            }
            if (fromSchema < 15) {
                sortWorkoutLogChronologically(c);
                recalculateWorkoutStreaks(c);
                rebuildHistoryFromWorkoutLog(c);
                applyLatestHistoryStatsToCharacter(c);
            }
            if (fromSchema < 18) {
                sortWorkoutLogChronologically(c);
                rebuildHistoryFromWorkoutLog(c);
                applyLatestHistoryStatsToCharacter(c);
                if (!isGodKiUnlocked(c)) c.stats.GKI = 0;
            }
            if (fromSchema < 31 && !c.v6Migration) {
                const migratedBasePower = window.DBZ_V6_CONFIG.basePower(
                    c.stats,
                    getStartingStatsForRace(c.race || 'earthling'),
                    false
                );
                const migratedRoute = typeof window.getRaceRoutePowerMultiplier === 'function'
                    ? window.getRaceRoutePowerMultiplier(c)
                    : { multiplier: 1, label: 'Base Form' };
                c.v6Migration = {
                    sourceSchema: fromSchema,
                    targetSchema: SAVE_SCHEMA_VERSION,
                    migratedAt: new Date().toISOString(),
                    note: 'Base fitness power now grows linearly; equipped states and race mechanics provide saga-scale power.',
                    preview: {
                        previousModel: 'v5 exponential display model',
                        baseFitnessPL: Math.max(1, Math.round(migratedBasePower)),
                        stateLabel: migratedRoute.label,
                        stateMultiplier: migratedRoute.multiplier,
                        effectivePL: Math.max(1, Math.round(migratedBasePower * migratedRoute.multiplier))
                    }
                };
            }
            if (fromSchema < 25) {
                migrateAbilityInventory(c);
                if (historyNeedsBaselineRepair(c)) {
                    sortWorkoutLogChronologically(c);
                    rebuildHistoryFromWorkoutLog(c);
                    applyLatestHistoryStatsToCharacter(c);
                }
                if (!isGodKiUnlocked(c)) c.stats.GKI = 0;
            }
        }

        async function loadState() {
            const loaded = await window.DBZV6Storage.load();
            window.DBZV6Storage.finishBootstrap();
            if (!loaded) return false;
            try {
                const defaults = JSON.parse(JSON.stringify(state));
                const loadedSchema = Number(loaded.schemaVersion) || 1;
                if (loadedSchema < SAVE_SCHEMA_VERSION) backupLegacySave(JSON.stringify(loaded));
                const mergedState = { ...defaults, ...loaded };
                Object.keys(state).forEach(key => delete state[key]);
                Object.assign(state, mergedState);
                state.version = GAME_VERSION;
                state.schemaVersion = SAVE_SCHEMA_VERSION;
                if (!state.workoutTemplates) state.workoutTemplates = [];
                if (typeof ensureBuiltInWorkoutTemplates === 'function') ensureBuiltInWorkoutTemplates();
                if (typeof ensureFitnessPlanState === 'function') ensureFitnessPlanState();
                if (!state.statsGoal || !state.statsGoal.type || !state.statsGoal.id) state.statsGoal = defaults.statsGoal;
                if (!state.characters) state.characters = defaults.characters;
                Object.keys(defaults.characters).forEach(id => {
                    if (!state.characters[id]) state.characters[id] = defaults.characters[id];
                });
                Object.keys(state.characters).forEach(id => migrateCharacter(state.characters[id], loadedSchema));
                if (!state.characters[state.activeCharacter]) state.activeCharacter = 'tim';
                document.documentElement.dataset.dbzLoadedStateName = state.characters[state.activeCharacter]?.name || '';
                document.documentElement.dataset.dbzLoadedStateId = state.activeCharacter || '';
                if (typeof ensureFitnessPlanState === 'function') ensureFitnessPlanState();
                saveState({ snapshot: loadedSchema < SAVE_SCHEMA_VERSION });
                return true;
            } catch (error) {
                console.error('Error loading save:', error);
                v6Alert('The save could not be loaded. Your recovery snapshots were left untouched.', 'error');
                return false;
            }
        }

        // ============ UI RENDERING ============

        function getNextSagaTarget(char) {
            // Returns the statReqs of the next locked saga (closest one not yet completed)
            const pl = getPowerLevel(char);
            const gpl = getGodPowerLevel(char);
            for (let i = 0; i < SAGAS.length; i++) {
                const s = SAGAS[i];
                if (char.completedSagas.includes(s.id)) continue;
                // This is the next target
                return { saga: s, statReqs: s.statReqs || {} };
            }
            // All completed — return last saga reqs
            const last = SAGAS[SAGAS.length - 1];
            return { saga: last, statReqs: last.statReqs || {} };
        }

        function getNextPowerMilestoneTarget(char) {
            const pl = getPowerLevel(char);
            const gpl = getGodPowerLevel(char);
            const nextCharacter = CANON_BENCHMARKS.find(m => m.pl > pl);
            const nextGPL = hasReachedGodTier(char) ? GPL_MILESTONES.find(m => !(char.plMilestones || []).includes(m.id)) : null;
            if (nextCharacter) {
                return {
                    type: 'Power Level',
                    label: `${nextCharacter.name} PL ${formatPL(nextCharacter.pl)}`,
                    current: pl,
                    threshold: nextCharacter.pl,
                    reward: {},
                    note: nextCharacter.saga ? `${nextCharacter.series} - ${nextCharacter.saga}` : 'Next character benchmark.'
                };
            }
            if (nextGPL) {
                return {
                    type: 'God Power Level',
                    label: nextGPL.label,
                    current: gpl,
                    threshold: nextGPL.threshold,
                    reward: { sp: nextGPL.sp },
                    note: 'Next divine training benchmark.'
                };
            }
            return null;
        }

        function renderMilestoneBanner(containerId, variant = '') {
            const el = document.getElementById(containerId);
            if (!el) return;
            const char = getActiveCharacter();
            const target = getNextPowerMilestoneTarget(char);
            if (!target) {
                el.innerHTML = '';
                return;
            }
            const pct = Math.min(100, Math.max(0, (target.current / target.threshold) * 100));
            const remaining = Math.max(0, target.threshold - target.current);
            const rewardText = formatRewardBundle(target.reward) || 'Recognition';
            el.innerHTML = `
                <div class="milestone-banner ${variant}">
                    <div class="milestone-banner-header">
                        <div>
                            <div class="milestone-banner-kicker">NEXT POWER LEVEL MILESTONE</div>
                            <div class="milestone-banner-title">${target.label}</div>
                        </div>
                        <div class="milestone-banner-value">${formatPL(target.current)} / ${formatPL(target.threshold)}</div>
                    </div>
                    <div class="milestone-progress"><div class="milestone-progress-fill" style="width:${pct.toFixed(1)}%"></div></div>
                    <div class="milestone-banner-meta">
                        <span>${target.type} - ${formatPL(remaining)} remaining</span>
                        <span>${target.note}</span>
                        <span class="milestone-reward-pill">${rewardText}</span>
                    </div>
                </div>
            `;
        }

        function renderActiveTeamPanel() {
            const el = document.getElementById('activeTeamPanel');
            if (!el) return;
            const safe = value => String(value ?? '').replace(/[&<>"']/g, ch => ({
                '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
            }[ch]));
            const char = getActiveCharacter();
            const active = getActivePartners(char);
            const slots = getPartnerSlotLimit(char);
            const mainPartnerId = getMainPartnerId(char);
            const raceArt = VISUAL_ASSETS.races[char?.race || 'earthling'] || VISUAL_ASSETS.races.earthling;
            const rows = [`
                <div class="active-team-row">
                    <img class="active-team-thumb" src="${raceArt}" alt="${safe(char.name)} thumbnail">
                    <div>
                        <div class="active-team-name">${safe(char.name)}</div>
                        <div class="active-team-meta">Main fighter · Lv ${getLevel(char)} · PL ${formatPL(getPowerLevel(char))}</div>
                    </div>
                </div>
            `];
            for (let i = 0; i < PARTNER_MAX_SLOTS; i++) {
                const slotNumber = i + 1;
                const partnerId = active[i];
                if (slotNumber <= slots && partnerId) {
                    const partner = getPartnerById(partnerId);
                    if (!partner) continue;
                    const progress = getPartnerProgress(char, partnerId);
                    const isMain = partnerId === mainPartnerId;
                    const scale = getPartnerLevelEffectScale(partner, progress, isMain);
                    const boosts = describePartnerEffects(partner.effects, scale).slice(0, 2).join(', ') || 'Support boost active';
                    rows.push(`
                        <div class="active-team-row">
                            <img class="active-team-thumb" src="${getPartnerImageSrc(partner)}" alt="${safe(partner.name)} thumbnail" onerror="this.src='${getPartnerPlaceholder(partner)}'">
                            <div>
                                <div class="active-team-name">${safe(partner.name)}${isMain ? ' · Main' : ''}</div>
                                <div class="active-team-meta">Lv ${progress.level} · ${safe(boosts)}</div>
                            </div>
                        </div>
                    `);
                } else if (slotNumber <= slots) {
                    rows.push(`
                        <div class="active-team-row locked">
                            <div class="active-team-thumb" style="display:grid;place-items:center;color:#778;">+</div>
                            <div>
                                <div class="active-team-name">Open Partner Slot</div>
                                <div class="active-team-meta">Activate a partner from the Character tab.</div>
                            </div>
                        </div>
                    `);
                } else {
                    const upgrade = PARTNER_SLOT_UPGRADES.find(item => item.slot === slotNumber);
                    rows.push(`
                        <div class="active-team-row locked">
                            <div class="active-team-thumb" style="display:grid;place-items:center;color:#778;font-size:0.62rem;">Locked</div>
                            <div>
                                <div class="active-team-name">Locked Partner Slot</div>
                                <div class="active-team-meta">${upgrade ? `Unlock for ${upgrade.cost} TP` : 'Locked'} in the Character tab.</div>
                            </div>
                        </div>
                    `);
                }
            }
            el.innerHTML = `
                <h3 style="color:#ffaa00;margin-bottom:0.5rem;font-size:0.9rem;text-transform:uppercase;letter-spacing:1px;">Active Characters</h3>
                <div class="active-team-list">${rows.slice(0, 7).join('')}</div>
            `;
        }

        function renderDashboard() {
            const char = getActiveCharacter();
            const pl = getPowerLevel(char);
            const level = getLevel(char);
            const totalLevel = Math.sqrt((char.totalTXP || 0) / LEVEL_TXP_FACTOR);
            const xpPercent = (totalLevel - Math.floor(totalLevel)) * 100;
            const saga = getCurrentSaga(char);
            const nextTarget = getNextSagaTarget(char);

            // Hero banner
            document.getElementById('charName').textContent = char.name;
            const activeTransform = getActiveTransformation(char);
            const basePL = getBasePowerLevel(char);
            document.getElementById('transformDisplay').textContent = activeTransform.id === 'base'
                ? 'Base Form'
                : `${activeTransform.name} - Base ${formatPL(basePL)} x${activeTransform.mult}`;
            document.getElementById('powerLevelDisplay').textContent = formatPL(pl);

            // Current saga name in hero
            const sagaNameEl = document.getElementById('currentSagaName');
            if (sagaNameEl) sagaNameEl.textContent = saga ? saga.name : '';
            const heroEl = document.querySelector('.db-hero');
            if (heroEl && VISUAL_ASSETS?.dashboardHero) {
                heroEl.classList.add('visual-hero');
                heroEl.style.backgroundImage = `linear-gradient(90deg, rgba(7,10,16,0.84), rgba(7,10,16,0.56)), url("${versionedAsset('./images/cover_a.jpg')}")`;
            }

            // God Power Level
            const gplVal = getGodPowerLevel(char);
            const gplDisplay = document.getElementById('godPowerLevelDisplay');
            const gplRow = document.getElementById('godPLRow');
            if (gplDisplay && gplRow) {
                if (hasReachedGodTier(char)) {
                    gplRow.style.display = '';
                    gplDisplay.textContent = formatPL(gplVal);
                } else {
                    gplRow.style.display = 'none';
                }
            }

            // Streak
            const streakNumEl = document.getElementById('streakNum');
            if (streakNumEl) streakNumEl.textContent = char.currentStreak > 0 ? char.currentStreak + ' 🔥' : '—';

            // Level / SP
            document.getElementById('levelDisplay').textContent = level;
            document.getElementById('spDisplay').textContent = formatPointValue(getSkillPoints(char));
            const tpDisplay = document.getElementById('tpDisplay');
            if (tpDisplay) tpDisplay.textContent = formatPointValue(getTrainingPoints(char));

            // XP bar
            document.getElementById('xpBar').style.width = xpPercent.toFixed(1) + '%';
            const txpForCurrentLevel = Math.pow(level - 1, 2) * LEVEL_TXP_FACTOR;
            const txpForNextLevel = Math.pow(level, 2) * LEVEL_TXP_FACTOR;
            const txpIntoLevel = char.totalTXP - txpForCurrentLevel;
            const txpNeeded = txpForNextLevel - txpForCurrentLevel;
            const safeTotal = isNaN(char.totalTXP) ? 0 : Math.round(char.totalTXP);
            const xpLabelEl = document.getElementById('xpLabel');
            const xpPctEl = document.getElementById('xpPct');
            const xpNextEl = document.getElementById('xpToNextLevel');
            if (xpLabelEl) xpLabelEl.textContent = safeTotal.toLocaleString() + ' TXP';
            if (xpPctEl) xpPctEl.textContent = xpPercent.toFixed(0) + '%';
            if (xpNextEl) {
                const txpLeft = Math.max(0, txpNeeded - txpIntoLevel);
                xpNextEl.textContent = isNaN(txpLeft) ? '' : Math.round(txpLeft).toLocaleString() + ' to Lv ' + (level + 1);
            }

            const tpCarry = Math.max(0, Math.min(0.9999, Number(char.tpCarry) || 0));
            const tpProgressBar = document.getElementById('tpProgressBar');
            const tpProgressPct = document.getElementById('tpProgressPct');
            const tpProgressLabel = document.getElementById('tpProgressLabel');
            const tpProgressTarget = document.getElementById('tpProgressTarget');
            const nextTPTarget = getNextTPPurchaseTarget(char);
            if (tpProgressBar) tpProgressBar.style.width = (tpCarry * 100).toFixed(1) + '%';
            if (tpProgressPct) tpProgressPct.textContent = (tpCarry * 100).toFixed(0) + '%';
            if (tpProgressLabel) tpProgressLabel.textContent = `${formatPointValue(getTrainingPoints(char))} TP available`;
            if (tpProgressTarget) {
                tpProgressTarget.textContent = nextTPTarget
                    ? `${formatPointValue(Math.max(0, nextTPTarget.cost - getTrainingPoints(char)))} TP to ${nextTPTarget.name}`
                    : 'All TP unlocks complete';
            }

            // Core Stats — bars relative to next saga targets
            let statsHTML = '';
            const statLabels = { STR: 'Strength', END: 'Endurance', AGI: 'Agility', VIT: 'Vitality', SPI: 'Spirit', TEC: 'Technique', GKI: 'God Ki' };
            STATS.forEach(stat => {
                const val = char.stats[stat];
                const target = nextTarget.statReqs[stat];
                if (target && target > 0) {
                    const pct = Math.min((val / target) * 100, 100);
                    statsHTML += `
                        <div class="stat-bar-wrap">
                            <div class="stat-bar-header">
                                <span class="stat-bar-name">${stat}</span>
                                <span class="stat-bar-vals"><span class="stat-cur">${formatStat(val)}</span><span class="stat-sep"> / </span>${target}</span>
                            </div>
                            <div class="stat-bar">
                                <div class="stat-fill ${stat.toLowerCase()}-fill" style="width: ${pct}%"></div>
                            </div>
                            <div class="stat-bar-saga-label">${nextTarget.saga ? nextTarget.saga.name : ''}</div>
                        </div>
                    `;
                } else {
                    // Stat not required for next saga — show compact grey bar
                    statsHTML += `
                        <div class="stat-bar-wrap">
                            <div class="stat-bar-header">
                                <span class="stat-bar-name">${stat}</span>
                                <span class="stat-bar-vals"><span class="stat-cur">${formatStat(val)}</span></span>
                            </div>
                            <div class="stat-bar" style="opacity:0.4;">
                                <div class="stat-fill ${stat.toLowerCase()}-fill" style="width:${Math.min(val/10,100)}%"></div>
                            </div>
                        </div>
                    `;
                }
            });
            const dashboardStatsEl = document.getElementById('dashboardStats');
            if (dashboardStatsEl) dashboardStatsEl.innerHTML = statsHTML;
            if (typeof renderStats === 'function') renderStats();

            // Current saga card
            document.getElementById('currentSagaDisplay').innerHTML = `
                <div style="color:#4488ff;font-size:0.8rem;margin-bottom:0.3rem;">${saga.series} Series</div>
                <div style="color:#ffaa00;font-size:1.1rem;font-weight:bold;margin-bottom:0.4rem;">${saga.name}</div>
                <div style="color:#d0d0d0;font-size:0.85rem;">${saga.desc}</div>
            `;

            // Daily missions date
            const missionDateEl = document.getElementById('missionDate');
            if (missionDateEl) missionDateEl.textContent = new Date().toLocaleDateString('en-GB', {day:'numeric',month:'short'});

            if (typeof renderDailyMissions === 'function') renderDailyMissions();
            const activeTeamEl = document.getElementById('activeTeamPanel');
            if (activeTeamEl) {
                activeTeamEl.dataset.renderAttempted = '1';
                try {
                    const safeTeamText = value => String(value ?? '').replace(/[&<>"']/g, ch => ({
                        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
                    }[ch]));
                    const active = getActivePartners(char);
                    const slots = getPartnerSlotLimit(char);
                    const mainPartnerId = active.includes(char.mainPartner) ? char.mainPartner : (active[0] || null);
                    const raceArt = VISUAL_ASSETS.races[char?.race || 'earthling'] || VISUAL_ASSETS.races.earthling;
                    const teamRows = [`
                        <div class="active-team-row">
                            <img class="active-team-thumb" src="${raceArt}" alt="${safeTeamText(char.name)} thumbnail">
                            <div>
                                <div class="active-team-name">${safeTeamText(char.name)}</div>
                                <div class="active-team-meta">Main fighter · Lv ${level} · PL ${formatPL(pl)}</div>
                            </div>
                        </div>
                    `];
                    for (let i = 0; i < PARTNER_MAX_SLOTS; i++) {
                        const slotNumber = i + 1;
                        const partnerId = active[i];
                        if (slotNumber <= slots && partnerId) {
                            const partner = getPartnerById(partnerId);
                            if (!partner) continue;
                            const progress = getPartnerProgress(char, partnerId);
                            const isMain = partnerId === mainPartnerId;
                            const scale = getPartnerLevelEffectScale(partner, progress, isMain);
                            const boosts = describePartnerEffects(partner.effects, scale).slice(0, 2).join(', ') || 'Support boost active';
                            teamRows.push(`
                                <div class="active-team-row">
                                    <img class="active-team-thumb" src="${getPartnerImageSrc(partner)}" alt="${safeTeamText(partner.name)} thumbnail" onerror="this.src='${getPartnerPlaceholder(partner)}'">
                                    <div>
                                        <div class="active-team-name">${safeTeamText(partner.name)}${isMain ? ' · Main' : ''}</div>
                                        <div class="active-team-meta">Lv ${progress.level} · ${safeTeamText(boosts)}</div>
                                    </div>
                                </div>
                            `);
                        } else if (slotNumber <= slots) {
                            teamRows.push(`
                                <div class="active-team-row locked">
                                    <div class="active-team-thumb" style="display:grid;place-items:center;color:#778;">+</div>
                                    <div>
                                        <div class="active-team-name">Open Partner Slot</div>
                                        <div class="active-team-meta">Activate a partner from the Character tab.</div>
                                    </div>
                                </div>
                            `);
                        } else {
                            const upgrade = PARTNER_SLOT_UPGRADES.find(item => item.slot === slotNumber);
                            teamRows.push(`
                                <div class="active-team-row locked">
                                    <div class="active-team-thumb" style="display:grid;place-items:center;color:#778;font-size:0.62rem;">Locked</div>
                                    <div>
                                        <div class="active-team-name">Locked Partner Slot</div>
                                        <div class="active-team-meta">${upgrade ? `Unlock for ${upgrade.cost} TP` : 'Locked'} in the Character tab.</div>
                                    </div>
                                </div>
                            `);
                        }
                    }
                    activeTeamEl.innerHTML = `
                        <h3 style="color:#ffaa00;margin-bottom:0.5rem;font-size:0.9rem;text-transform:uppercase;letter-spacing:1px;">Active Characters</h3>
                        <div class="active-team-list">${teamRows.slice(0, 7).join('')}</div>
                    `;
                } catch (err) {
                    activeTeamEl.innerHTML = `<div style="color:#ff8888;font-size:0.78rem;">Active characters could not be rendered: ${String(err?.message || err)}</div>`;
                    console.warn('Active team render failed:', err);
                }
            }
            if (typeof renderRacePanel === 'function') renderRacePanel();
            if (typeof applyRestDayAdjustments === 'function') applyRestDayAdjustments(char);
            if (typeof renderWeeklyRival === 'function') renderWeeklyRival();
            renderMilestoneBanner('dashboardMilestoneBanner');
            if (typeof updateChartGodKiLock === 'function') updateChartGodKiLock();
            if (typeof renderMuscleHeatmap === 'function') renderMuscleHeatmap();
            if (typeof renderChart === 'function') renderChart();
            if (typeof renderPersonalRecords === 'function') renderPersonalRecords();

            if (char.workoutLog.length === 0) {
                document.getElementById('welcomeMsg').innerHTML = `
                    <div class="welcome-message">
                        <h2>Welcome to Dragon Ball Fitness RPG!</h2>
                        <p>Start training to unlock transformations, abilities, and complete sagas. Train hard, become stronger!</p>
                    </div>
                `;
            } else {
                document.getElementById('welcomeMsg').innerHTML = '';
            }
        }

        function renderWeeklyRival() {
            const el = document.getElementById('weeklyRivalCard');
            if (!el) return;
            if (!player2Data) { el.style.display = 'none'; return; }
            el.style.display = '';
            const p1 = getActiveCharacter();
            const p2 = player2Data;
            const weekAgo = new Date(); weekAgo.setDate(weekAgo.getDate() - 7);
            const weekStr = weekAgo.toISOString().slice(0,10);
            const p1Sessions = (p1.workoutLog || []).filter(w => w.date >= weekStr).length;
            const p2Sessions = (p2.workoutLog || []).filter(w => w.date >= weekStr).length;
            const p1TXP = (p1.workoutLog || []).filter(w => w.date >= weekStr).reduce((s,w) => s+(w.totalTXP||0), 0);
            const p2TXP = (p2.workoutLog || []).filter(w => w.date >= weekStr).reduce((s,w) => s+(w.totalTXP||0), 0);
            const p1Wins = [p1Sessions > p2Sessions, p1TXP > p2TXP].filter(Boolean).length;
            const p2Wins = [p2Sessions > p1Sessions, p2TXP > p1TXP].filter(Boolean).length;
            const winnerMsg = p1Wins > p2Wins ? `${p1.name} leads this week` : p2Wins > p1Wins ? `${p2.name || 'Player 2'} leads this week` : 'Dead heat this week';
            el.innerHTML = `<h3 style="color:#cc88ff;margin-bottom:0.45rem;font-size:0.78rem;text-transform:uppercase;letter-spacing:1px;">Weekly Rivalry</h3>
                <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.5rem;font-size:0.82rem;">${winnerMsg}</div>
                <div class="weekly-rival-grid" style="display:grid;align-items:center;">
                    <div style="text-align:left;"><div style="color:#ffaa00;font-weight:bold;">${p1.name}</div></div>
                    <div style="color:#444;font-size:0.7rem;">vs</div>
                    <div style="text-align:right;"><div style="color:#cc88ff;font-weight:bold;">${p2.name||'Player 2'}</div></div>
                    <div style="text-align:left;color:${p1Sessions>=p2Sessions?'#44cc88':'#ff6666'}">${p1Sessions} sessions</div>
                    <div style="color:#333;font-size:0.7rem;">📅</div>
                    <div style="text-align:right;color:${p2Sessions>=p1Sessions?'#44cc88':'#ff6666'}">${p2Sessions} sessions</div>
                    <div style="text-align:left;color:${p1TXP>=p2TXP?'#44cc88':'#ff6666'}">${p1TXP.toLocaleString()} TXP</div>
                    <div style="color:#333;font-size:0.7rem;">⚡</div>
                    <div style="text-align:right;color:${p2TXP>=p1TXP?'#44cc88':'#ff6666'}">${p2TXP.toLocaleString()} TXP</div>
                </div>`;
        }

        function escapeHTML(value) {
            return String(value ?? '').replace(/[&<>"']/g, ch => ({
                '&': '&amp;',
                '<': '&lt;',
                '>': '&gt;',
                '"': '&quot;',
                "'": '&#39;'
            }[ch]));
        }

        function getRaceImageForCharacter(char) {
            const raceKey = char?.race || 'earthling';
            return VISUAL_ASSETS.races[raceKey] || VISUAL_ASSETS.races.earthling;
        }

