                mastered_ss: {cls:'art-ki-gold art-aura', sym:'MSS'},
                super_saiyan_2: {cls:'art-ki-gold art-aura', sym:'SS2'},
                super_saiyan_3: {cls:'art-ki-gold art-aura', sym:'SS3'},
                golden_great_ape: {cls:'art-ki-orange art-aura', sym:'🦍'},
                super_saiyan_4: {cls:'art-ki-crimson art-aura', sym:'SS4'},
                super_saiyan_god: {cls:'art-ki-red art-aura', sym:'SSG'},
