        function getPowerLevelSubtitle(pl) {
            if (pl < 1000) return "Earthling Level";
            if (pl < 1e6) return "Elite Warrior";
            if (pl < 1e9) return "Galactic Fighter";
            if (pl < 1e12) return "Planet Buster";
            if (pl < 1e18) return "Universal Threat";
            if (pl < 1e24) return "Multiversal";
            return "Beyond Measurement";
        }


        // ══════════════════════════════════════════════════════════════
        // CHARTS — SVG canvas stat history chart
        // ══════════════════════════════════════════════════════════════
        const CHART_SERIES = {
            STR: { color: '#ff4444', label: 'STR' },
            END: { color: '#44aaff', label: 'END' },
            AGI: { color: '#44ff88', label: 'AGI' },
            VIT: { color: '#ffaa00', label: 'VIT' },
            SPI: { color: '#cc44ff', label: 'SPI' },
            TEC: { color: '#1ec8b5', label: 'TEC' },
            GKI: { color: '#00ddcc', label: 'GKI' },
            PL:  { color: '#ffffff', label: 'Power Level' },
            BW:  { color: '#ff88cc', label: 'Body Weight' },
        };
        let chartActiveSeries = new Set(Object.keys(CHART_SERIES).filter(key => !['BW', 'GKI'].includes(key)));
        let chartActiveRange = 'all';
        let chartGroupBy = 'day';
        let chartYAxisMax = null;
        let chartYAxisMin = null;
        let chartXMinDate = null;
        let chartXMaxDate = null;

        function getHistoryInRange(history, range) {
            if (!history || history.length === 0) return [];
            const sortedHistory = history
                .filter(h => h.date && parseLocalDate(h.date))
                .slice()
                .sort((a, b) => a.date.localeCompare(b.date));
            const now = new Date();
            const cutoff = new Date(now);
            const rangeDays = { '1W': 7, '1M': 30, '3M': 90, '6M': 180, '1Y': 365 };
            if (range !== 'all' && rangeDays[range]) {
                cutoff.setDate(now.getDate() - rangeDays[range]);
                return sortedHistory.filter(h => new Date(`${h.date}T00:00:00`) >= cutoff);
            }
            return sortedHistory;
        }

        function groupHistory(history, groupBy) {
            if (groupBy === 'day' || !history.length) return history;
            const getKey = (dateStr) => {
                if (groupBy === 'month') return dateStr.slice(0, 7);
                // week: find Monday of the week
                const d = new Date(dateStr + 'T00:00:00');
                const day = d.getDay();
                const diff = day === 0 ? -6 : 1 - day;
                d.setDate(d.getDate() + diff);
                return d.toISOString().slice(0, 10);
            };
            const groups = {};
            history.forEach(h => {
                const key = getKey(h.date);
                // keep last entry per group (most recent stats snapshot)
                groups[key] = h;
            });
            return Object.entries(groups)
                .sort(([a], [b]) => a.localeCompare(b))
                .map(([key, h]) => ({ ...h, date: key }));
        }

        function renderChart() {
            const canvas = document.getElementById('statsChart');
            if (!canvas) return;
            const char = getActiveCharacter();
            const history = groupHistory(getHistoryInRange(char.history || [], chartActiveRange), chartGroupBy);
            const legend = document.getElementById('chartLegend');

            const W = canvas.offsetWidth || 700;
            const H = 380;
            canvas.width = W;
            canvas.height = H;
            const ctx = canvas.getContext('2d');
            if (!ctx) return;

            const pad = { top: 20, right: 20, bottom: 50, left: 60 };
            const plotW = W - pad.left - pad.right;
            const plotH = H - pad.top - pad.bottom;

            ctx.clearRect(0, 0, W, H);
            ctx.fillStyle = 'rgba(13, 13, 26, 0.88)';
            ctx.fillRect(0, 0, W, H);

            if (history.length < 1) {
                ctx.fillStyle = '#666';
                ctx.font = '14px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText('No history yet — log workouts to see your progress!', W/2, H/2);
                if (legend) legend.innerHTML = '';
                return;
            }
            // With a single data point we show dots rather than a line
            const singlePoint = history.length === 1;

            // Build data series
            const seriesData = {};
            let globalMin = Infinity, globalMax = -Infinity;
            Object.keys(CHART_SERIES).forEach(key => {
                if (!chartActiveSeries.has(key)) return;
                const values = history.map(h => key === 'PL' ? (h.pl || 0) : key === 'BW' ? (h.bw || 0) : (h.stats?.[key] || 0));
                const min = Math.min(...values);
                const max = Math.max(...values);
                if (min < globalMin) globalMin = min;
                if (max > globalMax) globalMax = max;
                seriesData[key] = values;
            });
            if (Number.isFinite(chartYAxisMin)) {
                globalMin = chartYAxisMin;
            }
            if (Number.isFinite(chartYAxisMax) && chartYAxisMax > globalMin) {
                globalMax = chartYAxisMax;
            }
            if (globalMin === globalMax) globalMax = globalMin + 1;

            // Draw grid lines
            ctx.strokeStyle = '#1a1a2e';
            ctx.lineWidth = 1;
            for (let i = 0; i <= 5; i++) {
                const y = pad.top + (plotH / 5) * i;
                ctx.beginPath(); ctx.moveTo(pad.left, y); ctx.lineTo(pad.left + plotW, y); ctx.stroke();
                const val = globalMax - (globalMax - globalMin) * (i / 5);
                ctx.fillStyle = '#555';
                ctx.font = '11px sans-serif';
                ctx.textAlign = 'right';
                ctx.fillText(formatStat(val), pad.left - 4, y + 4);
            }

            // Helper: safe x position (handles single-point case)
            const xPos = (i, total) => pad.left + (total <= 1 ? plotW / 2 : (i / (total - 1)) * plotW);

            // Draw X labels (dates) — format depends on groupBy
            const fmtLabel = (dateStr) => {
                if (!dateStr) return '';
                if (chartGroupBy === 'month') {
                    const [y, m] = dateStr.split('-');
                    return ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][parseInt(m,10)-1] + ' ' + y.slice(2);
                }
                if (chartGroupBy === 'week') return 'w/c ' + dateStr.slice(5);
                return dateStr.slice(5); // day: MM-DD
            };
            const step = Math.max(1, Math.floor(history.length / 6));
            ctx.fillStyle = '#555';
            ctx.font = '10px sans-serif';
            ctx.textAlign = 'center';
            history.forEach((h, i) => {
                if (i % step === 0 || i === history.length - 1) {
                    const x = xPos(i, history.length);
                    ctx.fillText(fmtLabel(h.date), x, H - pad.bottom + 18);
                }
            });

            // Draw canonical PL benchmarks
            ctx.save();
            ctx.setLineDash([4, 4]);
            ctx.lineWidth = 0.8;
            let lastBenchmarkLabelY = -999;
            CANON_BENCHMARKS.forEach(b => {
                if (b.pl < globalMin || b.pl > globalMax) return;
                const y = pad.top + plotH - ((b.pl - globalMin) / (globalMax - globalMin)) * plotH;
                if (y < pad.top || y > pad.top + plotH) return;
                ctx.strokeStyle = 'rgba(255,200,100,0.4)';
                ctx.beginPath(); ctx.moveTo(pad.left, y); ctx.lineTo(pad.left + plotW, y); ctx.stroke();
                if (Math.abs(y - lastBenchmarkLabelY) > 12) {
                    ctx.fillStyle = 'rgba(255,200,100,0.78)';
                    ctx.font = '9px sans-serif'; ctx.textAlign = 'left';
                    ctx.fillText(`${b.name} (${formatPL(b.pl)})`, pad.left + 2, y - 2);
                    lastBenchmarkLabelY = y;
                }
            });
            ctx.restore();
            ctx.setLineDash([]);

            // Draw each series
            Object.entries(seriesData).forEach(([key, values]) => {
                const col = CHART_SERIES[key].color;
                ctx.strokeStyle = col;
                ctx.lineWidth = key === 'PL' ? 1.5 : 2;
                ctx.shadowColor = col;
                ctx.shadowBlur = key === 'PL' ? 3 : 5;

                // Draw line (skip for single point — no line to draw)
                if (!singlePoint) {
                    ctx.beginPath();
                    values.forEach((v, i) => {
                        const x = xPos(i, values.length);
                        const y = pad.top + plotH - ((v - globalMin) / (globalMax - globalMin)) * plotH;
                        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    });
                    ctx.stroke();
                }
                // Draw a dot at every data point
                ctx.shadowBlur = 0;
                values.forEach((v, i) => {
                    const x = xPos(i, values.length);
                    const y = pad.top + plotH - ((v - globalMin) / (globalMax - globalMin)) * plotH;
                    ctx.beginPath();
                    ctx.arc(x, y, 5, 0, Math.PI * 2);
                    ctx.fillStyle = col;
                    ctx.fill();
                    // White outline so dots stand out against the line
                    ctx.beginPath();
                    ctx.arc(x, y, 5, 0, Math.PI * 2);
                    ctx.strokeStyle = 'rgba(255,255,255,0.25)';
                    ctx.lineWidth = 1;
                    ctx.stroke();
                });
                ctx.shadowBlur = 0;
            });

            // Legend + entry count
            if (legend) {
                const totalEntries = (char.history || []).length;
                legend.innerHTML = Object.entries(CHART_SERIES).map(([key, s]) =>
                    `<span style="display:flex;align-items:center;gap:0.35rem;opacity:${chartActiveSeries.has(key) ? 1 : 0.3}">
                        <span style="width:20px;height:3px;background:${s.color};display:inline-block;border-radius:2px;"></span>
                        <span style="color:#ccc;">${s.label}</span>
                    </span>`
                ).join('') + `<span style="margin-left:auto;color:#555;font-size:0.75rem;">${history.length} point${history.length !== 1 ? 's' : ''} shown${totalEntries !== history.length ? ' ('+totalEntries+' total)' : ''}</span>`;
            }
        }

        function renderPersonalRecords() {
            const char = getActiveCharacter();
            const prs = char.personalRecords || {};
            const el = document.getElementById('prDisplay');
            if (!el) return;
            const selectedCategory = document.getElementById('prCategoryFilter')?.value || 'all';
            if (selectedCategory === 'none') {
                el.innerHTML = '<span style="color:#777;">Choose an exercise category to view records.</span>';
                return;
            }
            const keys = Object.keys(prs).filter(ex => selectedCategory === 'all' || findExerciseMainCategory(ex) === selectedCategory);
            if (keys.length === 0) {
                el.innerHTML = `<span style="color:#666;">No personal records ${selectedCategory === 'all' ? 'yet' : 'in this category yet'} — log workouts to set PRs!</span>`;
                return;
            }
            el.innerHTML = `<div class="pr-grid">${keys.map(ex => {
                const pr = prs[ex];
                let prText = '';
                if (pr.volume) prText += pr.volume.toFixed(0) + ' vol';
                if (pr.reps) prText += ' / ' + pr.reps + ' reps';
                // Estimate 1RM if weight and reps available
                let est1rm = null;
                if (pr.weight && pr.reps && pr.reps > 1) {
                    est1rm = epley1RM(pr.weight, pr.reps);
                }
                return `<div class="pr-record-row">
                    <span style="color:#ddd;">${ex}</span>
                    <span style="color:#ffaa00;font-weight:bold;text-align:right;">
                        ${prText}
                        ${est1rm ? ' <span style="color:#ffaa00;font-size:0.85rem;">(est. 1RM: ' + est1rm + 'kg)</span>' : ''}
                        <span style="color:#666;font-size:0.8rem;margin-left:0.5rem;">(${pr.date || ''})</span>
                    </span>
                </div>`;
            }).join('')}</div>`;
        }

        function checkAndSetPR(char, exerciseName, volume, reps, workoutDate = new Date().toISOString().slice(0, 10), weight = null) {
            if (!char.personalRecords) char.personalRecords = {};
            const existing = char.personalRecords[exerciseName];
            let isPR = false;
            if (!existing || volume > (existing.volume || 0)) {
                const record = { volume, reps, date: workoutDate };
                if (weight !== null && Number.isFinite(weight)) record.weight = weight;
                char.personalRecords[exerciseName] = record;
                isPR = true;
            }
            return isPR;
        }

        // ══════════════════════════════════════════════════════════════
        // REST DAY ADJUSTMENTS — compatibility bridge for older save logic.
        // Recovery and deterioration are now rebuilt from workoutLog into history events.
        // ══════════════════════════════════════════════════════════════
        function applyRestDayAdjustments(char) {
            if (typeof refreshRecoveryAndHistory === 'function') refreshRecoveryAndHistory(char);
        }

        // ══════════════════════════════════════════════════════════════
        // ZENKAI BOOST — gap > 3 days → 1.5× TXP on next session
        // ══════════════════════════════════════════════════════════════
        function checkZenkaiBoost(char, workoutDate = new Date().toISOString().slice(0, 10)) {
            const latestWorkoutDate = getLatestWorkoutDate(char);
            if (!latestWorkoutDate) return false;
            const lastWork = new Date(`${latestWorkoutDate}T00:00:00`);
            const currentWork = new Date(`${workoutDate}T00:00:00`);
            const gap = (currentWork - lastWork) / 86400000;
            return gap >= 3;
        }

        function applyZenkaiBoost(char, baseTXP) {
            if (char.zenkaiReady) {
                char.zenkaiReady = false;
                if (typeof showNotification === 'function')
                    showNotification('⚡ Zenkai Boost!', 'You pushed through a gap — TXP ×1.5!', 'success');
                return Math.round(baseTXP * 1.5);
            }
            return baseTXP;
        }

        // ══════════════════════════════════════════════════════════════
        // DAILY TRAINING MISSIONS — 3 seeded missions per day
        // ══════════════════════════════════════════════════════════════
        const MISSION_POOL = [
            { id: 'do_cardio',    desc: 'Complete a cardio session',              check: log => log.some(e => e.category === 'cardio'),                          spReward: 0, xpReward: 25  },
            { id: 'do_strength',  desc: 'Do any strength exercise',               check: log => log.some(e => e.category === 'strength'),                        spReward: 0, xpReward: 25  },
            { id: 'do_core',      desc: 'Train your core',                         check: log => log.some(e => e.category === 'core'),                            spReward: 0, xpReward: 25  },
            { id: 'do_martial',   desc: 'Include martial skills training',          check: log => log.some(e => e.category === 'martial'),                         spReward: 0, xpReward: 30  },
            { id: 'upper_body',   desc: 'Train an upper-body muscle group',         check: log => log.some(e => ['chest','back','shoulders','arms'].includes(e.muscle)), spReward: 0, xpReward: 25 },
            { id: 'lower_body',   desc: 'Train legs today',                         check: log => log.some(e => e.muscle === 'legs'),                              spReward: 0, xpReward: 25  },
            { id: 'log_5',        desc: 'Log 5 or more exercises today',           check: log => log.length >= 5,                                                  spReward: 0, xpReward: 40  },
            { id: 'log_10',       desc: 'Log 10 or more exercises today',          check: log => log.length >= 10,                                                 spReward: 0, xpReward: 70 },
            { id: 'heavy_lift',   desc: 'Log a weighted lift of ≥ 100 kg total',   check: log => log.some(e => (e.sets||[]).some(s => (s.weight||0) * (s.reps||0) >= 100)), spReward: 0, xpReward: 40 },
            { id: 'weighted_3',   desc: 'Complete 3 weighted exercises',            check: log => log.filter(e => (e.sets||[]).some(s => Number(s.weight) > 0)).length >= 3, spReward: 0, xpReward: 45 },
            { id: 'full_body',    desc: 'Hit 3 different muscle groups',           check: log => new Set(log.map(e => e.muscle).filter(Boolean)).size >= 3,        spReward: 0, xpReward: 40 },
            { id: 'four_groups',  desc: 'Hit 4 different muscle groups',            check: log => new Set(log.map(e => e.muscle).filter(Boolean)).size >= 4,        spReward: 0, xpReward: 55 },
            { id: 'stretch',      desc: 'Include a flexibility exercise',          check: log => log.some(e => e.category === 'flexibility'),                      spReward: 0, xpReward: 25  },
            { id: 'meditate',     desc: 'Log meditation or breathwork',             check: log => log.some(e => /meditation|breath/i.test(e.name || '')),           spReward: 0, xpReward: 35  },
            { id: 'high_reps',    desc: 'Complete a set with 20+ reps',            check: log => log.some(e => (e.sets||[]).some(s => (s.reps||0) >= 20)),         spReward: 0, xpReward: 25  },
            { id: 'volume_100',   desc: 'Reach 100 total reps today',               check: log => log.reduce((sum, e) => sum + (e.sets||[]).reduce((s, set) => s + (Number(set.reps)||0), 0), 0) >= 100, spReward: 0, xpReward: 50 },
            { id: 'timed_hold',   desc: 'Complete a timed hold over 60 seconds',    check: log => log.some(e => (e.sets||[]).some(s => (Number(s.seconds)||0) >= 60)), spReward: 0, xpReward: 30 },
            { id: 'run_walk',     desc: 'Log running or walking distance',          check: log => log.some(e => /run|walk/i.test(e.name || '') && Number(e.distance || e.inputs?.distance) > 0), spReward: 0, xpReward: 35 },
            { id: 'swim_row',     desc: 'Log swimming or rowing',                   check: log => log.some(e => /swim|row/i.test(e.name || '')),                    spReward: 0, xpReward: 35 },
            { id: 'ki_train',     desc: 'Do any Spirit / Technique / GKI exercise', check: log => log.some(e => ['SPI','TEC','GKI'].some(s => (e.weights||{})[s] > 0)), spReward: 0, xpReward: 40  },
        ];

        function getDailyMissions(date = new Date().toISOString().slice(0, 10)) {
            let seed = 2166136261;
            for (const ch of String(date)) {
                seed ^= ch.charCodeAt(0);
                seed = Math.imul(seed, 16777619) >>> 0;
            }
            const dayOffset = Math.floor(new Date(`${date}T00:00:00`).getTime() / 86400000);
            const buckets = [
                MISSION_POOL.filter(m => ['do_cardio','do_strength','do_core','do_martial','upper_body','lower_body','stretch'].includes(m.id)),
                MISSION_POOL.filter(m => ['log_5','log_10','full_body','four_groups','volume_100','weighted_3'].includes(m.id)),
                MISSION_POOL.filter(m => ['heavy_lift','high_reps','timed_hold','meditate','run_walk','swim_row','ki_train'].includes(m.id))
            ];
            const chosen = [];
            buckets.forEach((bucket, bucketIndex) => {
                const idx = (seed + dayOffset * (bucketIndex + 3) + bucketIndex * 17) % bucket.length;
                chosen.push(bucket[idx]);
            });
            return chosen;
        }

        function renderDailyMissions() {
            const el = document.getElementById('dailyMissions');
            if (!el) return;
            const char = getActiveCharacter();
            const today = new Date().toISOString().slice(0, 10);
            const missions = getDailyMissions();
            const completed = (char.dailyMissions?.date === today) ? (char.dailyMissions.completed || []) : [];

            el.innerHTML = missions.map(m => {
                const done = completed.includes(m.id);
                return `<div style="display:flex;align-items:center;gap:0.75rem;padding:0.5rem 0;border-bottom:1px solid #1a1a2e;">
                    <span style="font-size:1.2rem;">${done ? '✅' : '⬜'}</span>
                    <div style="flex:1;">
                        <div style="color:${done ? '#44cc88' : '#ddd'};${done ? 'text-decoration:line-through;opacity:0.6;' : ''}">${m.desc}</div>
                        <div style="font-size:0.75rem;color:#888;">Reward: ${formatRewardText(m.spReward, m.xpReward)}</div>
                    </div>
                </div>`;
            }).join('');
        }

        function getDailyWorkoutEntries(char, workoutDate, fallbackSession = []) {
            const entries = (char.workoutLog || [])
                .filter(workout => workout.date === workoutDate)
                .flatMap(workout => workout.exercises || [])
                .map(normalizeWorkoutEntry);
            return entries.length ? entries : (fallbackSession || []).map(normalizeWorkoutEntry);
        }

        function checkMissionsAfterWorkout(char, workoutLog, workoutDate = new Date().toISOString().slice(0, 10)) {
            const today = workoutDate;
            const missions = getDailyMissions(today);
            const dailyLog = getDailyWorkoutEntries(char, today, workoutLog);
            if (!char.dailyMissions || char.dailyMissions.date !== today) {
                char.dailyMissions = { date: today, completed: [] };
            }
            missions.forEach(m => {
                if (!char.dailyMissions.completed.includes(m.id) && m.check(dailyLog)) {
                    char.dailyMissions.completed.push(m.id);
                    char.spEarned  = (char.spEarned  || 0) + m.spReward;
                    char.totalTXP  = (char.totalTXP  || 0) + m.xpReward;
                    if (typeof showNotification === 'function')
                        showNotification('🎯 Mission Complete!', `"${m.desc}" — ${formatRewardText(m.spReward, m.xpReward, true)}`, 'success');
                }
            });
        }

        // ══════════════════════════════════════════════════════════════
        // HISTORY — record a snapshot after each workout
        // ══════════════════════════════════════════════════════════════
        function getBodyWeightOnDate(char, workoutDate) {
            return (char.bodyWeightLog || [])
                .filter(b => b.date && b.date <= workoutDate && Number(b.weight) > 0)
                .sort((a, b) => a.date.localeCompare(b.date))
                .slice(-1)[0]?.weight || null;
        }

        function getWorkoutStatTotals(workout, char = null) {
            const totals = createZeroStatMap();
            (workout.exercises || []).forEach(ex => {
                const gains = ex.statGains || {};
                STATS.forEach(stat => {
                    if (stat === 'GKI' && char && !isGodKiUnlocked(char)) return;
                    totals[stat] += Number(gains[stat]) || 0;
                });
            });
            return totals;
        }

        function getHistoryBaselineStats(char) {
            const baseline = getStartingStatsForRace(char?.race || 'earthling');
            if (!isGodKiUnlocked(char)) baseline.GKI = 0;
            return Object.fromEntries(STATS.map(stat => [stat, Number(baseline[stat]) || 0]));
        }

        function getPowerLevelForHistorySnapshot(char, stats) {
            const basePowerFn = typeof window !== 'undefined' && typeof window.getBaseDisplayPowerFromStats === 'function'
                ? window.getBaseDisplayPowerFromStats
                : null;
            const raceScoreFn = typeof window !== 'undefined' && typeof window.getRaceStartingPowerScore === 'function'
                ? window.getRaceStartingPowerScore
                : null;
            if (basePowerFn && raceScoreFn) {
                const baselineScore = raceScoreFn(char?.race || 'earthling');
                const base = basePowerFn(stats || {}, isGodKiUnlocked(char), baselineScore);
                const transformationMultiplier = typeof getPrimaryTransformationPowerMultiplier === 'function'
                    ? getPrimaryTransformationPowerMultiplier(char)
                    : 1;
                return Math.max(1, roundToSignificantNumber(base * transformationMultiplier, 6));
            }
            return getPowerLevelFromStats(stats || {});
        }

        function historyNeedsBaselineRepair(char) {
            if (!char || !Array.isArray(char.workoutLog) || !char.workoutLog.length) return false;
            if (!Array.isArray(char.history) || !char.history.length) return true;
            const first = char.history
                .filter(h => h?.date && h.stats)
                .sort((a, b) => String(a.date).localeCompare(String(b.date)))[0];
            if (!first) return true;
            const baseline = getHistoryBaselineStats(char);
            const matchesBaseline = STATS.every(stat => Math.abs((Number(first.stats?.[stat]) || 0) - baseline[stat]) < 0.001);
            return !first.baseline || !matchesBaseline;
        }

        function createHistoryBaselineSnapshot(char, date) {
            const baselineStats = getHistoryBaselineStats(char);
            const snapStats = Object.fromEntries(STATS.map(stat => [stat, +baselineStats[stat].toFixed(4)]));
            return {
                date,
                stats: snapStats,
                pl: getPowerLevelForHistorySnapshot(char, snapStats),
                bw: getBodyWeightOnDate(char, date),
                baseline: true,
            };
        }

        function rebuildHistoryFromWorkoutLog(char) {
            const runningStats = getHistoryBaselineStats(char);
            const workouts = (char.workoutLog || [])
                .filter(w => w.date && parseLocalDate(w.date))
                .map((workout, index) => ({ workout, index }))
                .sort((a, b) => {
                    const dateCmp = a.workout.date.localeCompare(b.workout.date);
                    return dateCmp || a.index - b.index;
                });
            const recoveryEvents = getRecoveryHistoryEvents(char)
                .map((event, index) => ({ event, index }))
                .sort((a, b) => {
                    const dateCmp = String(a.event.date || '').localeCompare(String(b.event.date || ''));
                    return dateCmp || a.index - b.index;
                });
            const timeline = [
                ...workouts.map(item => ({ kind: 'workout', date: item.workout.date, index: item.index, workout: item.workout })),
                ...recoveryEvents.map(item => ({ kind: 'recovery', date: item.event.date, index: item.index + 100000, event: item.event }))
            ].sort((a, b) => {
                const dateCmp = String(a.date || '').localeCompare(String(b.date || ''));
                return dateCmp || a.index - b.index;
            });
            const bonusesByDate = {};
            (char.weeklyCoverageBonuses || []).forEach(bonus => {
                if (!bonus.date || !(Number(bonus.perStatBonus) > 0)) return;
                bonusesByDate[bonus.date] = (bonusesByDate[bonus.date] || 0) + Number(bonus.perStatBonus);
            });

            const history = [];
            let currentDate = null;
            if (timeline.length) {
                history.push(createHistoryBaselineSnapshot(char, timeline[0].date));
            }
            timeline.forEach((item, idx) => {
                currentDate = item.date;
                const totals = item.kind === 'recovery'
                    ? getRecoveryEventTotals(item.event, runningStats, char)
                    : getWorkoutStatTotals(item.workout, char);
                applyRecoveryDeltaToStats(char, runningStats, totals);

                const next = timeline[idx + 1];
                if (!next || next.date !== item.date) {
                    if (bonusesByDate[item.date]) {
                        STATS.forEach(stat => {
                            if (stat === 'GKI' && !isGodKiUnlocked(char)) return;
                            runningStats[stat] += bonusesByDate[item.date];
                        });
                    }
                    const snapStats = Object.fromEntries(STATS.map(stat => [stat, +runningStats[stat].toFixed(4)]));
                    history.push({
                        date: item.date,
                        stats: snapStats,
                        pl: getPowerLevelForHistorySnapshot(char, snapStats),
                        bw: getBodyWeightOnDate(char, item.date),
                    });
                }
            });
            char.history = history.slice(-500);
        }

        function applyLatestHistoryStatsToCharacter(char) {
            const latest = (char.history || []).filter(h => !h.baseline).slice().sort((a, b) => a.date.localeCompare(b.date)).slice(-1)[0];
            if (!latest || !latest.stats) return;
            STATS.forEach(stat => {
                const val = Number(latest.stats[stat]);
                if (Number.isFinite(val)) char.stats[stat] = +val.toFixed(4);
            });
        }

        function recordHistorySnapshot(char) {
            rebuildHistoryFromWorkoutLog(char);
        }

        // ══════════════════════════════════════════════════════════════
        // RACE info panel (shown on dashboard)
        // ══════════════════════════════════════════════════════════════
        const RACE_INFO = {
            earthling:   { label: 'Earthling',     icon: '🌍', desc: 'Versatile and adaptable. Slightly stronger Technique growth, all other gains ×1.0.' },
            saiyan:      { label: 'Saiyan',         icon: '🐒', desc: 'Combat-bred warriors. STR/SPI gains ×1.15 with lower control-focused gains.' },
            hybrid:      { label: 'Half-Saiyan',    icon: '⚡', desc: 'Saiyan heritage unlocks hidden power. Strong Spirit with steady Technique growth.' },
            namekian:    { label: 'Namekian',       icon: '🟢', desc: 'Wise healers. VIT/END gains ×1.2 with good Spirit and Technique control.' },
            android:     { label: 'Android',        icon: '🤖', desc: 'Infinite energy. AGI/STR and Technique grow well, Spirit grows slower.' },
            majin:       { label: 'Majin',          icon: '🍬', desc: 'Absorbent and resilient. VIT ×1.3 with slower agility and control gains.' },
            frieza_race: { label: "Frieza's Race",  icon: '👾', desc: 'Born powerful. STR/AGI grow well with clean Technique and lower endurance.' },
        };

        function getRaceStatMult(char, stat) {
            const race = char.race || 'earthling';
            const mults = {
                earthling:   { STR:1.0, END:1.0, AGI:1.0, VIT:1.0, SPI:1.0, TEC:1.08, GKI:1.0 },
                saiyan:      { STR:1.15, END:0.9, AGI:0.95, VIT:0.9, SPI:1.15, TEC:0.95, GKI:1.05 },
                hybrid:      { STR:1.05, END:0.95, AGI:1.0, VIT:0.95, SPI:1.2, TEC:1.05, GKI:1.05 },
                namekian:    { STR:0.85, END:1.2, AGI:0.95, VIT:1.2, SPI:1.1, TEC:1.08, GKI:1.0 },
                android:     { STR:1.1,  END:1.0, AGI:1.1,  VIT:0.95, SPI:0.8, TEC:1.12, GKI:0.9 },
                majin:       { STR:0.95, END:1.0, AGI:0.8,  VIT:1.3,  SPI:0.95, TEC:0.96, GKI:0.9 },
                frieza_race: { STR:1.1,  END:0.85, AGI:1.1, VIT:1.0, SPI:0.95, TEC:1.03, GKI:1.0 },
            };
            return (mults[race] || mults.earthling)[stat] || 1.0;
        }

        function renderRacePanel() {
            const el = document.getElementById('racePanel');
            if (!el) return;
            const char = getActiveCharacter();
            const race = char.race || 'earthling';
            const info = RACE_INFO[race] || RACE_INFO.earthling;
            const options = Object.entries(RACE_INFO).map(([key, r]) =>
                `<button type="button" class="race-picker-option ${key === race ? 'selected' : ''}" onclick="selectRaceFromPicker('${key}')">
                    <img src="${VISUAL_ASSETS.races[key] || VISUAL_ASSETS.races.earthling}" class="race-thumb" alt="${r.label} thumbnail">
                    <span>${r.label}</span>
                </button>`
            ).join('');
            el.innerHTML = `
                <div class="race-panel-shell" style="display:flex;align-items:center;gap:0.75rem;flex-wrap:wrap;">
                    <div style="flex:1;">
                        <div class="race-picker" id="racePicker">
                            <button type="button" class="race-picker-button" onclick="toggleRacePicker(event)">
                                <img src="${VISUAL_ASSETS.races[race] || VISUAL_ASSETS.races.earthling}" class="race-thumb" alt="${info.label} thumbnail">
                                <span class="race-picker-label">${info.label}</span>
                                <span class="race-picker-chevron">▼</span>
                            </button>
                            <div class="race-picker-menu" id="racePickerMenu">${options}</div>
                        </div>
                        <div class="race-desc" style="font-size:0.8rem;color:#888;margin-top:0.3rem;">${info.desc}</div>
                    </div>
                </div>`;
        }

        function toggleRacePicker(event) {
            if (event) event.stopPropagation();
            const picker = document.getElementById('racePicker');
            if (picker) picker.classList.toggle('open');
        }

        function selectRaceFromPicker(newRace) {
            const picker = document.getElementById('racePicker');
            if (picker) picker.classList.remove('open');
            changeRace(newRace);
        }

        function changeRace(newRace) {
            const char = getActiveCharacter();
            const shouldSwapStarterStats = !hasCharacterTrainingProgress(char) && isStarterStatProfile(char);
            char.race = newRace;
            if (shouldSwapStarterStats) applyStartingStatsForRace(char, newRace);
            char.setupComplete = true;
            saveState();
            renderRacePanel();
            renderDashboard();
        }

        document.addEventListener('click', (event) => {
            const picker = document.getElementById('racePicker');
            if (picker && !event.target.closest('.race-picker')) picker.classList.remove('open');
        });

        // ══════════════════════════════════════════════════════════════
        // STREAK XP BONUS — +5% per streak day, capped at +25%
        // ══════════════════════════════════════════════════════════════
        function getStreakBonus(char) {
            const streak = char.currentStreak || 0;
            return Math.min(0.25, streak * 0.05);
        }

        // ══════════════════════════════════════════════════════════════
        // CHART TAB INIT — wire up toggle buttons
        // ══════════════════════════════════════════════════════════════
        function updateChartGodKiLock() {
            const unlocked = isGodKiUnlocked(getActiveCharacter());
            const gkiBtn = document.querySelector('.chart-toggle[data-series="GKI"]');
            if (!unlocked) chartActiveSeries.delete('GKI');
            if (gkiBtn) {
                gkiBtn.disabled = !unlocked;
                gkiBtn.classList.toggle('locked', !unlocked);
                gkiBtn.classList.toggle('active', unlocked && chartActiveSeries.has('GKI'));
                gkiBtn.title = unlocked ? 'Show God Ki' : 'God Ki unlocks in Dragon Ball Super';
            }
        }

        function initChartControls() {
            document.querySelectorAll('.chart-toggle').forEach(btn => {
                btn.addEventListener('click', () => {
                    const series = btn.dataset.series;
                    if (series === 'GKI' && !isGodKiUnlocked(getActiveCharacter())) {
                        chartActiveSeries.delete('GKI');
                        updateChartGodKiLock();
                        renderChart();
                        return;
                    }
                    if (chartActiveSeries.has(series)) {
                        chartActiveSeries.delete(series);
                        btn.classList.remove('active');
                    } else {
                        chartActiveSeries.add(series);
                        btn.classList.add('active');
                    }
                    renderChart();
                });
            });
            document.querySelectorAll('.chart-range').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.chart-range').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    chartActiveRange = btn.dataset.range;
                    renderChart();
                });
            });

            document.querySelectorAll('.chart-group').forEach(btn => {
                btn.addEventListener('click', () => {
                    document.querySelectorAll('.chart-group').forEach(b => b.classList.remove('active'));
                    btn.classList.add('active');
                    chartGroupBy = btn.dataset.group;
                    renderChart();
                });
            });

            document.getElementById('chartDeselectAll')?.addEventListener('click', () => {
                chartActiveSeries.clear();
                document.querySelectorAll('.chart-toggle').forEach(b => b.classList.remove('active'));
                updateChartGodKiLock();
                renderChart();
            });
            document.getElementById('chartSelectAll')?.addEventListener('click', () => {
                const godKiUnlocked = isGodKiUnlocked(getActiveCharacter());
                Object.keys(CHART_SERIES).forEach(k => {
                    if (k !== 'GKI' || godKiUnlocked) chartActiveSeries.add(k);
                });
                document.querySelectorAll('.chart-toggle').forEach(b => {
                    const series = b.dataset.series;
                    b.classList.toggle('active', chartActiveSeries.has(series));
                });
                updateChartGodKiLock();
                renderChart();
            });
            document.getElementById('chartYMaxApply')?.addEventListener('click', () => {
                const input = document.getElementById('chartYMaxInput');
                const val = Number(input?.value);
                chartYAxisMax = Number.isFinite(val) && val > 0 ? val : null;
                if (input && chartYAxisMax === null) input.value = '';
                renderChart();
            });
            document.getElementById('chartYMaxAuto')?.addEventListener('click', () => {
                chartYAxisMax = null;
                const input = document.getElementById('chartYMaxInput');
                if (input) input.value = '';
                renderChart();
            });
            updateChartGodKiLock();
        }


        window.addEventListener('click', (e) => {
            const modal = document.getElementById('addExerciseModal');
            if (e.target === modal) modal.classList.remove('active');
            const editModal = document.getElementById('editWorkoutModal');
            if (e.target === editModal) editModal.classList.remove('active');
            const compareModal = document.getElementById('compareModal');
            if (compareModal && e.target === compareModal) compareModal.classList.remove('active');
            const newGameModal = document.getElementById('newGameModal');
            if (newGameModal && e.target === newGameModal) { /* don't close new game modal on outside click */ }
        });

        // ════════════════════════════════════════════════════════════════
        // HISTORY CALENDAR
        // ════════════════════════════════════════════════════════════════
        let histCalYear = new Date().getFullYear();
        let histCalMonth = new Date().getMonth(); // 0-indexed
        let histSelectedWorkoutIndex = null; // index into char.workoutLog

        function renderHistoryTab() {
            renderHistCalendar();
        }

        function renderHistCalendar() {
            const char = getActiveCharacter();
            const monthNames = ['January','February','March','April','May','June','July','August','September','October','November','December'];
            document.getElementById('histCalMonthLabel').textContent = `${monthNames[histCalMonth]} ${histCalYear}`;

            // Build a map of date strings -> workout log entries (array of indices)
            const workoutDates = {};
            (char.workoutLog || []).forEach((w, i) => {
                if (w.date) {
                    if (!workoutDates[w.date]) workoutDates[w.date] = [];
                    workoutDates[w.date].push(i);
                }
            });

            const todayStr = new Date().toISOString().slice(0, 10);
            const firstDay = new Date(histCalYear, histCalMonth, 1).getDay(); // 0=Sun
            const daysInMonth = new Date(histCalYear, histCalMonth + 1, 0).getDate();

            const dayLabels = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
            let html = '<div class="hist-cal-grid">';
            dayLabels.forEach(d => { html += `<div class="hist-cal-day-label">${d}</div>`; });

            // Empty cells before first day
            for (let i = 0; i < firstDay; i++) {
                html += '<div class="hist-cal-cell empty"></div>';
            }

            for (let d = 1; d <= daysInMonth; d++) {
                const dateStr = `${histCalYear}-${String(histCalMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
                const hasWorkout = !!workoutDates[dateStr];
                const isToday = dateStr === todayStr;
                const isSelected = histSelectedWorkoutIndex !== null &&
                    char.workoutLog[histSelectedWorkoutIndex]?.date === dateStr;
                let cls = 'hist-cal-cell';
                if (hasWorkout) cls += ' has-workout';
                else cls += ' no-workout';
                if (isToday) cls += ' today';
                if (isSelected) cls += ' selected';
                const clickAttr = hasWorkout ? `onclick="histSelectDate('${dateStr}')"` : '';
                const countBadge = hasWorkout && workoutDates[dateStr].length > 1
                    ? `<span style="position:absolute;top:2px;right:4px;font-size:0.6rem;color:#ffdd88;">${workoutDates[dateStr].length}</span>` : '';
                html += `<div class="${cls}" ${clickAttr} title="${hasWorkout ? workoutDates[dateStr].length + ' workout(s) on this day' : ''}">${d}${countBadge}</div>`;
            }

            html += '</div>';

            // Summary bar
            const totalThisMonth = Object.keys(workoutDates).filter(d => d.startsWith(`${histCalYear}-${String(histCalMonth+1).padStart(2,'0')}`)).length;
            html += `<div style="margin-top:0.75rem;text-align:center;color:#888;font-size:0.85rem;">` +
                    `<span style="color:#ff8c00;font-weight:bold;">${totalThisMonth}</span> workout day${totalThisMonth !== 1 ? 's' : ''} this month` +
                    `</div>`;

            document.getElementById('histCalendar').innerHTML = html;
        }

        function histSelectDate(dateStr) {
            const char = getActiveCharacter();
            const matches = [];
            (char.workoutLog || []).forEach((w, i) => { if (w.date === dateStr) matches.push(i); });
            if (matches.length === 0) return;
            // If multiple workouts on same day, show them all; store first as reference
            histSelectedWorkoutIndex = matches[0];
            renderHistCalendar(); // re-render to highlight selected
            renderHistDayDetail(dateStr, matches);
        }

        function renderHistDayDetail(dateStr, indices) {
            const char = getActiveCharacter();
            const detailDiv = document.getElementById('histDayDetail');
            const contentDiv = document.getElementById('histDayContent');
            const titleEl = document.getElementById('histDayTitle');

            const dateObj = new Date(dateStr + 'T00:00:00');
            const dayNames = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
            const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
            titleEl.textContent = `${dayNames[dateObj.getDay()]} ${dateObj.getDate()} ${monthNames[dateObj.getMonth()]} ${dateObj.getFullYear()}`;

            let html = '';
            indices.forEach((wIdx, sessionNum) => {
                const w = char.workoutLog[wIdx];
                if (!w) return;
                if (indices.length > 1) {
                    html += `<div style="color:#ffaa00;font-weight:bold;margin-bottom:0.5rem;">Session ${sessionNum + 1}</div>`;
                }
                // XP and gains summary
                html += `<div style="display:flex;gap:1.5rem;margin-bottom:0.75rem;flex-wrap:wrap;">`;
                html += `<div style="color:#ffff66;font-size:0.9rem;">⚡ <strong>${w.totalTXP || 0}</strong> TXP earned</div>`;
                // Compute total stat gains
                const totals = Object.fromEntries(STATS.map(s => [s, 0]));
                (w.exercises || []).forEach(ex => {
                    Object.keys(totals).forEach(s => { totals[s] += (ex.statGains?.[s] || 0); });
                });
                const gainParts = Object.entries(totals).filter(([,v]) => v > 0.0001).map(([s,v]) => `${s} +${v.toFixed(3)}`);
                if (gainParts.length > 0) html += `<div style="color:#66aaff;font-size:0.85rem;">📈 ${gainParts.join(' · ')}</div>`;
                html += '</div>';

                // Exercises
                (w.exercises || []).forEach(ex => {
                    const inp = ex.inputs || {};
                    const exerciseDef = findExerciseByName(ex.name) || { name: ex.name, type: ex.type || 'unknown' };
                    const detail = formatExerciseInputSummary({ exercise: exerciseDef, inputs: inp });

                    const exGains = ex.statGains || {};
                    const gainStr = Object.entries(exGains).filter(([,v]) => v > 0.0001).map(([s,v]) => `${s}+${v.toFixed(3)}`).join(' ');

                    html += `<div class="hist-workout-exercise">
                        <div class="hist-workout-exercise-name">${ex.name || 'Exercise'}</div>
                        ${detail ? `<div class="hist-workout-exercise-detail">${detail}</div>` : ''}
                        ${gainStr ? `<div class="hist-workout-exercise-gains">📊 ${gainStr}</div>` : ''}
                    </div>`;
                });

                if (w.notes) {
                    html += `<div style="margin-top:0.5rem;padding:0.6rem 0.8rem;background:#0e0e24;border-radius:6px;font-size:0.85rem;color:#aaa;border-left:3px solid #4488ff;">📝 ${escapeHTML(w.notes)}</div>`;
                }

                if (indices.length > 1 && sessionNum < indices.length - 1) {
                    html += '<hr style="border-color:#2a1a44;margin:1rem 0;">';
                }
            });

            contentDiv.innerHTML = html;

            // Store indices for edit button
            document.getElementById('histEditBtn').dataset.indices = JSON.stringify(indices);

            detailDiv.style.display = 'block';
            detailDiv.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function openEditWorkoutModal(indices) {
            const char = getActiveCharacter();
            const modal = document.getElementById('editWorkoutModal');
            const contentDiv = document.getElementById('editWorkoutContent');

            let html = '';
            indices.forEach((wIdx, sessionNum) => {
                const w = char.workoutLog[wIdx];
                if (!w) return;
                if (indices.length > 1) html += `<h4 style="color:#ffaa00;margin:0.75rem 0 0.4rem;">Session ${sessionNum + 1}</h4>`;

                html += `<div style="margin-bottom:1rem;">`;
                html += `<label style="display:block;margin-bottom:0.3rem;color:#aaa;font-size:0.85rem;">Date:</label>
                         <input type="date" id="editDate_${wIdx}" value="${w.date}" style="width:100%;margin-bottom:0.75rem;">`;

                html += `<div id="editExercises_${wIdx}">`;
                (w.exercises || []).forEach((ex, exIdx) => {
                    const inp = ex.inputs || {};
                    const exerciseDef = findExerciseByName(ex.name) || ex;
                    const exType = ex.type || exerciseDef.type;
                    html += `<div class="hist-workout-exercise" id="editEx_${wIdx}_${exIdx}">
                        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:0.4rem;">
                            <div class="hist-workout-exercise-name">${ex.name}</div>
                            <button class="btn-danger btn-small" onclick="removeEditExercise(${wIdx},${exIdx})" style="font-size:0.7rem;padding:0.2rem 0.5rem;">✕</button>
                        </div>`;
                    if (['weighted', 'bodyweight', 'timed_hold'].includes(exType)) {
                        const sets = setsFromInputs(exType, inp);
                        const btnText = exType === 'timed_hold' ? '+ Add Hold' : '+ Add Set';
                        html += `<div id="editSetRows_${wIdx}_${exIdx}" data-set-container>${sets.map((set, setIdx) => exerciseSetRowHTML(exType, setIdx, set, `edit_${wIdx}_${exIdx}`)).join('')}</div>
                            <button type="button" class="btn-secondary btn-small" onclick="addEditSetRow(${wIdx},${exIdx},'${exType}')" style="margin-top:0.35rem;">${btnText}</button>`;
                    } else if (inp.distance !== undefined) {
                        html += `<div style="display:flex;gap:0.5rem;flex-wrap:wrap;">
                            <label style="font-size:0.8rem;color:#aaa;">Distance(km): <input type="number" id="editDist_${wIdx}_${exIdx}" value="${inp.distance}" min="0" step="0.1" style="width:80px;"></label>
                            <label style="font-size:0.8rem;color:#aaa;">Time(min): <input type="number" id="editDur_${wIdx}_${exIdx}" value="${inp.duration || 30}" min="1" style="width:80px;"></label>
                        </div>`;
                    } else if (inp.duration !== undefined) {
                        html += `<label style="font-size:0.8rem;color:#aaa;">Duration(min): <input type="number" id="editDur_${wIdx}_${exIdx}" value="${inp.duration}" min="0" style="width:80px;"></label>`;
                    }
                    html += `</div>`;
                });
                html += `</div>`; // editExercises

                html += `<label style="display:block;margin-top:0.75rem;margin-bottom:0.3rem;color:#aaa;font-size:0.85rem;">Notes:</label>
                         <textarea id="editNotes_${wIdx}" style="width:100%;height:70px;">${escapeHTML(w.notes || '')}</textarea>`;
                html += `</div>`;
            });

            contentDiv.innerHTML = html;
            document.getElementById('saveEditWorkoutBtn').dataset.indices = JSON.stringify(indices);
            modal.classList.add('active');
        }

        // Remove an exercise row during editing (in-memory for display; saved on confirm)
        window._editRemovedExercises = window._editRemovedExercises || {};
        function removeEditExercise(wIdx, exIdx) {
            const el = document.getElementById(`editEx_${wIdx}_${exIdx}`);
            if (el) { el.style.opacity = '0.3'; el.style.textDecoration = 'line-through'; el.dataset.removed = '1'; }
        }

        function addEditSetRow(wIdx, exIdx, type) {
            addSetRow(`editSetRows_${wIdx}_${exIdx}`, type, `edit_${wIdx}_${exIdx}`);
        }

        function saveEditedWorkout() {
            const char = getActiveCharacter();
            const indices = JSON.parse(document.getElementById('saveEditWorkoutBtn').dataset.indices || '[]');

            indices.forEach(wIdx => {
                const w = char.workoutLog[wIdx];
                if (!w) return;

                const newDate = document.getElementById(`editDate_${wIdx}`)?.value;
                if (newDate) w.date = newDate;

                const newNotes = document.getElementById(`editNotes_${wIdx}`)?.value;
                w.notes = newNotes || '';

                // Update exercise inputs
                (w.exercises || []).forEach((ex, exIdx) => {
                    const elBlock = document.getElementById(`editEx_${wIdx}_${exIdx}`);
                    if (elBlock && elBlock.dataset.removed === '1') {
                        ex._removed = true;
                        return;
                    }
                    const inp = ex.inputs || {};
                    const exercise = findExerciseByName(ex.name);
                    const exType = ex.type || exercise?.type;
                    if (document.getElementById(`editSetRows_${wIdx}_${exIdx}`)) {
                        const setsList = collectSetRows(`editSetRows_${wIdx}_${exIdx}`, exType);
                        ex.inputs = aggregateSetInputs(exType, setsList);
                    } else if (document.getElementById(`editDist_${wIdx}_${exIdx}`)) {
                        ex.inputs = {
                            distance: parseFloat(document.getElementById(`editDist_${wIdx}_${exIdx}`).value) || inp.distance,
                            duration: parseFloat(document.getElementById(`editDur_${wIdx}_${exIdx}`)?.value) || inp.duration || 30
                        };
                    } else if (document.getElementById(`editDur_${wIdx}_${exIdx}`)) {
                        ex.inputs = { duration: parseFloat(document.getElementById(`editDur_${wIdx}_${exIdx}`).value) || inp.duration };
                    }
                    // Recompute stat gains
                    if (exercise) {
                        ex.statGains = computeStatGains(exercise, ex.inputs);
                        Object.assign(ex, createWorkoutLogEntry({ exercise, inputs: ex.inputs, gains: ex.statGains }));
                    }
                });

                // Remove flagged exercises
                w.exercises = (w.exercises || []).filter(ex => !ex._removed);

                // Recompute totalTXP
                const totals = Object.fromEntries(STATS.map(s => [s, 0]));
                (w.exercises || []).forEach(ex => {
                    Object.keys(totals).forEach(s => { totals[s] += (ex.statGains?.[s] || 0); });
                });
                w.totalTXP = Math.round(Object.values(totals).reduce((a,b)=>a+b,0) * 10);
            });

            const selDateAfterEdit = indices.map(wIdx => char.workoutLog[wIdx]?.date).filter(Boolean).sort().slice(-1)[0];
            sortWorkoutLogChronologically(char);
            recalculateWorkoutStreaks(char);
            rebuildHistoryFromWorkoutLog(char);
            applyLatestHistoryStatsToCharacter(char);
            saveState();
            document.getElementById('editWorkoutModal').classList.remove('active');
            // Refresh display
            const selDate = selDateAfterEdit;
            if (selDate) {
                const newMatches = [];
                (char.workoutLog || []).forEach((w, i) => { if (w.date === selDate) newMatches.push(i); });
                renderHistCalendar();
                if (newMatches.length > 0) renderHistDayDetail(selDate, newMatches);
            } else {
                renderHistCalendar();
            }
        }

        function findExerciseByName(name) {
            for (const mainCat of Object.values(EXERCISE_DB)) {
                for (const subCat of Object.values(mainCat)) {
                    const found = subCat.find(e => e.name === name);
                    if (found) return found;
                }
            }
            return null;
        }

        function computeStatGains(exercise, inputData) {
            return getExerciseStatGains(exercise, inputData, getActiveCharacter());
        }

        function getSimulatorTemplates() {
            return [
                {
                    name: 'Strength Base',
                    exercises: [
                        ['Bench Press', { setsList: [{ reps: 8, weight: 40 }, { reps: 8, weight: 40 }, { reps: 8, weight: 40 }], sets: 3, reps: 8, weight: 40 }],
                        ['Squat', { setsList: [{ reps: 8, weight: 50 }, { reps: 8, weight: 50 }, { reps: 8, weight: 50 }], sets: 3, reps: 8, weight: 50 }],
                        ['Plank', { setsList: [{ seconds: 60 }, { seconds: 60 }, { seconds: 60 }], sets: 3, seconds: 60, totalSeconds: 180 }]
                    ]
                },
                {
                    name: 'Cardio Quality',
                    exercises: [
                        ['Outdoor Run', { distance: 5, duration: 30 }],
                        ['Walk', { distance: 4, duration: 48 }]
                    ]
                },
                {
                    name: 'Core + Mobility',
                    exercises: [
                        ['Straight Leg Raise', { setsList: [{ reps: 12 }, { reps: 12 }, { reps: 12 }], sets: 3, reps: 12 }],
                        ['Russian Twist', { setsList: [{ reps: 20 }, { reps: 20 }, { reps: 20 }], sets: 3, reps: 20 }],
                        ['Yoga Session', { duration: 25 }]
                    ]
                },
                {
                    name: 'Martial Conditioning',
                    exercises: [
                        ['Shadow Boxing', { duration: 20 }],
                        ['Heavy Bag Work', { duration: 20 }],
                        ['Jump Rope', { duration: 10 }]
                    ]
                }
            ];
        }

        function addGains(target, gains, multiplier = 1) {
            STATS.forEach(stat => {
                target[stat] = (target[stat] || 0) + ((gains[stat] || 0) * multiplier);
            });
        }

        function simulateProgression(weeks, sessionsPerWeek) {
            const char = getActiveCharacter();
            const templates = getSimulatorTemplates();
            const weekly = Object.fromEntries(STATS.map(s => [s, 0]));
            const rows = [];
            for (let i = 0; i < sessionsPerWeek; i++) {
                const template = templates[i % templates.length];
                const sessionGains = Object.fromEntries(STATS.map(s => [s, 0]));
                template.exercises.forEach(([name, inputs]) => {
                    const exercise = findExerciseByName(name);
                    if (!exercise) return;
                    addGains(sessionGains, getExerciseStatGains(exercise, inputs, char));
                });
                addGains(weekly, sessionGains);
                rows.push({ name: template.name, gains: sessionGains });
            }
            const projected = Object.fromEntries(STATS.map(s => [s, weekly[s] * weeks]));
            const weeklyTXP = Object.values(weekly).reduce((a, b) => a + b, 0) * 10;
            return { weekly, projected, rows, weeklyTXP, totalTXP: weeklyTXP * weeks };
        }

        function renderSimulator() {
            const el = document.getElementById('simulatorDisplay');
            if (!el) return;
            const weeks = Math.max(1, Math.min(52, parseInt(document.getElementById('simWeeks')?.value) || 12));
            const sessions = Math.max(1, Math.min(7, parseInt(document.getElementById('simSessions')?.value) || 4));
            const sim = simulateProgression(weeks, sessions);
            const statCards = STATS.map(stat => `
                <div style="background:#0e0e24;border:1px solid #2a1a44;border-radius:6px;padding:0.75rem;">
                    <div style="color:${STAT_COLORS[stat]};font-weight:bold;">${stat}</div>
                    <div style="color:#ddd;font-size:1.05rem;">+${formatStat(sim.projected[stat])}</div>
                    <div style="color:#777;font-size:0.75rem;">+${formatStat(sim.weekly[stat])} / week</div>
                </div>
            `).join('');
            const rows = sim.rows.map(row => {
                const gainText = STATS.filter(s => row.gains[s] > 0.001)
                    .map(s => `<span style="color:${STAT_COLORS[s]};">${s}+${formatStat(row.gains[s])}</span>`)
                    .join(' ');
                return `<tr><td>${row.name}</td><td>${gainText || '<span style="color:#666;">No gain</span>'}</td></tr>`;
            }).join('');
            el.innerHTML = `
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(110px,1fr));gap:0.6rem;margin-bottom:1rem;">${statCards}</div>
                <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;">
                    <div style="background:#101024;border:1px solid #2a1a44;border-radius:6px;padding:0.85rem;">
                        <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.45rem;">Projected TXP</div>
                        <div style="color:#ffff66;font-size:1.35rem;">${Math.round(sim.totalTXP).toLocaleString()}</div>
                        <div style="color:#777;font-size:0.8rem;">${Math.round(sim.weeklyTXP).toLocaleString()} / week at ${sessions} sessions/week</div>
                    </div>
                    <div style="background:#101024;border:1px solid #2a1a44;border-radius:6px;padding:0.85rem;">
                        <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.45rem;">Anti-cheese thresholds</div>
                        <div style="color:#bbb;font-size:0.85rem;line-height:1.5;">Bonus systems should require at least ${BALANCE_RULES.minWorkoutTXPForBonuses} TXP, ${BALANCE_RULES.minStrengthSetsForBonuses} meaningful strength sets, or ${BALANCE_RULES.minCardioMinutesForBonuses} cardio minutes before counting a workout for future TP/streak bonuses.</div>
                    </div>
                </div>
                <table style="margin-top:1rem;">
                    <thead><tr><th>Template Session</th><th>Estimated Gains</th></tr></thead>
                    <tbody>${rows}</tbody>
                </table>
            `;
        }

        // Init history tab navigation
        document.getElementById('histCalPrev').addEventListener('click', () => {
            histCalMonth--;
            if (histCalMonth < 0) { histCalMonth = 11; histCalYear--; }
            histSelectedWorkoutIndex = null;
            document.getElementById('histDayDetail').style.display = 'none';
            renderHistCalendar();
        });
        document.getElementById('histCalNext').addEventListener('click', () => {
            histCalMonth++;
            if (histCalMonth > 11) { histCalMonth = 0; histCalYear++; }
            histSelectedWorkoutIndex = null;
            document.getElementById('histDayDetail').style.display = 'none';
            renderHistCalendar();
        });
        document.getElementById('histEditBtn').addEventListener('click', () => {
            const indicesRaw = document.getElementById('histEditBtn').dataset.indices;
            if (!indicesRaw) return;
            openEditWorkoutModal(JSON.parse(indicesRaw));
        });
        document.getElementById('histCloseDayBtn').addEventListener('click', () => {
            histSelectedWorkoutIndex = null;
            document.getElementById('histDayDetail').style.display = 'none';
            renderHistCalendar();
        });
        document.getElementById('closeEditWorkoutModal').addEventListener('click', () => {
            document.getElementById('editWorkoutModal').classList.remove('active');
        });
        document.getElementById('saveEditWorkoutBtn').addEventListener('click', saveEditedWorkout);

        // ════════════════════════════════════════════════════════════════
        // PLAYER 2 IMPORT + COMPARE
        // ════════════════════════════════════════════════════════════════
        let player2Data = null; // will hold imported character object

        function loadPlayer2() {
            const saved = localStorage.getItem('dbfitness_p2');
            if (saved) {
                try { player2Data = JSON.parse(saved); } catch(e) { player2Data = null; }
            }
        }
        loadPlayer2();

        function renderP2Button() {
            const btn = document.getElementById('p2ImportBtn') || document.getElementById('p2ActiveBtn');
            if (!btn) return;
            if (player2Data) {
                btn.id = 'p2ActiveBtn';
                btn.textContent = `👤 ${player2Data.name || 'Player 2'}`;
                btn.title = 'Click to re-import or clear Player 2 save';
            } else {
                btn.id = 'p2ImportBtn';
                btn.textContent = '+ Import Player 2';
                btn.title = 'Import another player\'s save to compare';
            }
            // Re-attach listener since id changed
            btn.onclick = handleP2BtnClick;
        }

        function handleP2BtnClick() {
            if (player2Data) {
                const action = confirm(`Player 2: ${player2Data.name}\n\nClick OK to clear Player 2 data, or Cancel to keep it.`);
                if (action) {
                    player2Data = null;
                    localStorage.removeItem('dbfitness_p2');
                    renderP2Button();
                    if (typeof renderDashboardCascade === 'function') renderDashboardCascade();
                    // Hide compare UI
                    document.getElementById('compareHeaderBtn').style.display = 'none';
                    document.getElementById('dashCompareBar')?.style && (document.getElementById('dashCompareBar').style.display = 'none');
                    document.getElementById('statsCompareBar')?.style && (document.getElementById('statsCompareBar').style.display = 'none');
                    document.querySelectorAll('.compare-btn').forEach(b => b.style.display = 'none');
                }
            } else {
                document.getElementById('p2FileInput').click();
            }
        }

        document.getElementById('p2FileInput').addEventListener('change', (e) => {
            const file = e.target.files[0];
            if (!file) return;
            const reader = new FileReader();
            reader.onload = (ev) => {
                try {
                    const parsed = JSON.parse(ev.target.result);
                    // Accept either a full save or a single character export
                    let charObj = null;
                    if (parsed.characters) {
                        // Full save — pick the active character or first character
                        const charKey = parsed.activeCharacter || Object.keys(parsed.characters)[0];
                        charObj = parsed.characters[charKey];
                    } else if (parsed.stats && parsed.workoutLog !== undefined) {
                        charObj = parsed;
                    }
                    if (!charObj) { v6Alert('Could not read player data from this file.'); return; }
                    player2Data = charObj;
                    localStorage.setItem('dbfitness_p2', JSON.stringify(player2Data));
                    renderP2Button();
                    if (typeof renderDashboardCascade === 'function') renderDashboardCascade();
                    // Show compare UI elements
                    document.getElementById('compareHeaderBtn').style.display = 'inline-flex';
                    document.getElementById('dashCompareBar')?.style && (document.getElementById('dashCompareBar').style.display = 'block');
                    document.getElementById('statsCompareBar')?.style && (document.getElementById('statsCompareBar').style.display = 'block');
                    document.querySelectorAll('#p2NameLabel, .p2NameLabel').forEach(el => { el.textContent = player2Data.name || 'Player 2'; });
                    document.querySelectorAll('.compare-btn').forEach(b => b.style.display = 'inline-flex');
                    v6Alert(`✅ Player 2 loaded: ${player2Data.name || 'Unknown'}`);
                } catch(err) {
                    v6Alert('Error reading file: ' + err.message);
                }
            };
            reader.readAsText(file);
            e.target.value = '';
        });

        function openCompareModal() {
            if (!player2Data) { v6Alert('Import a Player 2 save first.'); return; }
            const p1 = getActiveCharacter();
            const p2 = player2Data;

            const p1pl = getPowerLevel(p1);
            const p2pl = getPowerLevel(p2);
            const p1lvl = getLevel(p1);
            const p2lvl = getLevel(p2);
            const p1EffectiveStats = getEffectiveStats(p1);
            const p2EffectiveStats = getEffectiveStats(p2);

            function cmp(a, b) {
                if (a > b) return ['higher', 'lower'];
                if (a < b) return ['lower', 'higher'];
                return ['', ''];
            }

            const statRows = STATS.filter(s => s !== 'GKI').map(s => {
                const v1 = +(p1EffectiveStats[s]||0).toFixed(1);
                const v2 = +(p2EffectiveStats[s]||0).toFixed(1);
                const [c1, c2] = cmp(v1, v2);
                return `<div class="compare-stat-row">
                    <span class="compare-stat-name">${s}</span>
                    <span class="compare-stat-val ${c1}">${v1}</span>
                    <span style="color:#444;font-size:0.7rem;">vs</span>
                    <span class="compare-stat-val ${c2}">${v2}</span>
                </div>`;
            }).join('');

            const gkiRows = isGodKiUnlocked(p1) ? (() => {
                const v1 = +(p1EffectiveStats.GKI || 0).toFixed(1);
                const v2 = +(p2EffectiveStats.GKI || 0).toFixed(1);
                const [c1,c2] = cmp(v1,v2);
                return `<div class="compare-stat-row">
                    <span class="compare-stat-name">GKI</span>
                    <span class="compare-stat-val ${c1}">${v1}</span>
                    <span style="color:#444;font-size:0.7rem;">vs</span>
                    <span class="compare-stat-val ${c2}">${v2}</span>
                </div>`;
            })() : '';

            const [plC1, plC2] = cmp(p1pl, p2pl);
            const [lvlC1, lvlC2] = cmp(p1lvl, p2lvl);
            const [streakC1, streakC2] = cmp(p1.currentStreak||0, p2.currentStreak||0);
            const [workoutsC1, workoutsC2] = cmp((p1.workoutLog||[]).length, (p2.workoutLog||[]).length);
            const [txpC1, txpC2] = cmp(p1.totalTXP||0, p2.totalTXP||0);

            const getForm = (char) => {
                const trans = getActiveTransformation(char);
                return trans ? trans.name : 'Base Form';
            };

            const modal = document.getElementById('compareModal');
            document.getElementById('compareContent').innerHTML = `
                <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1rem;">
                    <div style="text-align:center;padding:0.75rem;background:#12121a;border-radius:8px;border:2px solid #ff8c00;">
                        <div style="font-size:1.2rem;font-weight:bold;color:#ffaa00;">${p1.name}</div>
                        <div style="font-size:0.8rem;color:#888;">${getForm(p1)}</div>
                        <div style="font-size:0.8rem;color:#666;">${(RACE_INFO && RACE_INFO[p1.race||'earthling']?.label) || ''}</div>
                    </div>
                    <div style="text-align:center;padding:0.75rem;background:#12121a;border-radius:8px;border:2px solid #9955cc;">
                        <div style="font-size:1.2rem;font-weight:bold;color:#cc88ff;">${p2.name || 'Player 2'}</div>
                        <div style="font-size:0.8rem;color:#888;">${getForm(p2)}</div>
                        <div style="font-size:0.8rem;color:#666;">${(RACE_INFO && RACE_INFO[p2.race||'earthling']?.label) || ''}</div>
                    </div>
                </div>
                <div style="background:#0e0e24;border-radius:8px;padding:1rem;margin-bottom:0.75rem;">
                    <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.5rem;font-size:0.85rem;">OVERVIEW</div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Power Level</span><span class="compare-stat-val ${plC1}">${p1pl.toLocaleString()}</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val ${plC2}">${p2pl.toLocaleString()}</span></div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Level</span><span class="compare-stat-val ${lvlC1}">${p1lvl}</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val ${lvlC2}">${p2lvl}</span></div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Total TXP</span><span class="compare-stat-val ${txpC1}">${(p1.totalTXP||0).toLocaleString()}</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val ${txpC2}">${(p2.totalTXP||0).toLocaleString()}</span></div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Workouts</span><span class="compare-stat-val ${workoutsC1}">${(p1.workoutLog||[]).length}</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val ${workoutsC2}">${(p2.workoutLog||[]).length}</span></div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Streak</span><span class="compare-stat-val ${streakC1}">${p1.currentStreak||0}🔥</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val ${streakC2}">${p2.currentStreak||0}🔥</span></div>
                </div>
                <div style="background:#0e0e24;border-radius:8px;padding:1rem;margin-bottom:0.75rem;">
                    <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.5rem;font-size:0.85rem;">STATS</div>
                    ${statRows}${gkiRows}
                </div>
                <div style="background:#0e0e24;border-radius:8px;padding:1rem;">
                    <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.5rem;font-size:0.85rem;">TRANSFORMATIONS</div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Unlocked</span><span class="compare-stat-val">${(p1.unlockedTransformations||[]).length}</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val">${(p2.unlockedTransformations||[]).length}</span></div>
                    <div class="compare-stat-row"><span class="compare-stat-name">Latest Form</span><span class="compare-stat-val" style="font-size:0.78rem;">${getForm(p1)}</span><span style="color:#444;font-size:0.7rem;">vs</span><span class="compare-stat-val" style="font-size:0.78rem;">${getForm(p2)}</span></div>
                </div>
            `;
            modal.classList.add('active');
        }

        // ════════════════════════════════════════════════════════════════
        // NEW GAME SETUP MODAL
        // ════════════════════════════════════════════════════════════════
        function maybeShowNewGameModal() {
            const char = getActiveCharacter();
            // Show if character has no workouts logged yet — treat as fresh start
            const hasNoProgress = !hasCharacterTrainingProgress(char) && !char.setupComplete;
            if (hasNoProgress) {
                showNewGameModal();
            }
        }

        function showNewGameModal() {
            const modal = document.getElementById('newGameModal');
            if (!modal) return;
            const char = getActiveCharacter();
            // Pre-fill name only if it's not the default placeholder names
            const defaultNames = ['Tim', 'Hannah', 'Player'];
            document.getElementById('newGameName').value = defaultNames.includes(char.name) ? '' : (char.name || '');
            // Mark current race
            const currentRace = char.race || 'earthling';
            document.querySelectorAll('.race-option').forEach(el => {
                el.classList.toggle('selected', el.dataset.race === currentRace);
            });
            hydrateRaceOptionArt();
            // Set race description
            const raceDescEl = document.getElementById('raceDescBox');
            if (raceDescEl) raceDescEl.textContent = RACE_DESCS[currentRace] || '';
            modal.classList.add('active');
        }

        const RACE_DESCS = {
            earthling:    'Versatile and adaptable. All stat gains ×1.0. No restrictions on transformations.',
            saiyan:       'Born warriors with incredible potential. Access the full Saiyan transformation tree.',
            hybrid:       'Half-Saiyan heritage grants hidden power. Unlocks Gohan\'s exclusive transformations.',
            namekian:     'Regenerative and wise. Access Giant Form and Super Namek transformations.',
            android:      'Boundless energy with no fatigue. Unlocks Android and Cell form transformations.',
            majin:        'Absorbent and resilient. High starting vitality with slower early agility.',
            frieza_race:  'Elite powerhouses who suppress their true strength. Access Frieza\'s transformation forms.',
        };

        function hydrateRaceOptionArt() {
            document.querySelectorAll('.race-option').forEach(option => {
                const race = option.dataset.race || 'earthling';
                const icon = option.querySelector('.race-icon');
                if (!icon) return;
                const info = RACE_INFO[race] || RACE_INFO.earthling;
                icon.innerHTML = `<img src="${VISUAL_ASSETS.races[race] || VISUAL_ASSETS.races.earthling}" class="race-thumb" alt="${info.label} thumbnail">`;
            });
        }

        function selectRaceOption(el) {
            document.querySelectorAll('.race-option').forEach(o => o.classList.remove('selected'));
            el.classList.add('selected');
            const desc = RACE_DESCS[el.dataset.race] || '';
            document.getElementById('raceDescBox').textContent = desc;
        }

        // Race desc box is updated when modal opens via showNewGameModal()

        function confirmNewGame() {
            const nameInput = document.getElementById('newGameName').value.trim();
            if (!nameInput) { v6Alert('Please enter a name for your character.'); return; }
            const selectedRace = document.querySelector('.race-option.selected');
            if (!selectedRace) { v6Alert('Please select a race.'); return; }
            const race = selectedRace.dataset.race;

            const char = getActiveCharacter();
            char.name = nameInput;
            char.race = race;
            applyStartingStatsForRace(char, race);
            char.setupComplete = true;

            // Update the character switcher button label
            const activeBtn = document.querySelector(`.char-btn[data-char="${state.activeCharacter}"]`);
            if (activeBtn) activeBtn.textContent = nameInput;

            saveState();
            document.getElementById('newGameModal').classList.remove('active');
            renderDashboard();
        }

        // ════ TRAINING ARCS ════
        function renderTrainingArcs() {
            const el = document.getElementById('arcsDisplay');
            if (!el) return;
            const char = getActiveCharacter();
            let html = '';
            TRAINING_ARCS.forEach(arc => {
                const isActive = char.activeArc && char.activeArc.id === arc.id;
                const isDone = (char.completedArcs || []).includes(arc.id);
                const progress = isActive ? getArcProgress(char, arc) : null;
                html += `<div style="background:#12121a;border:2px solid ${isDone ? '#44cc88' : isActive ? arc.color : '#2a1a44'};border-radius:8px;padding:1.25rem;margin-bottom:1rem;">
                    <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:0.5rem;">
                        <div>
                            <div style="font-size:1.1rem;font-weight:bold;color:${arc.color};">${arc.name}</div>
                            <div style="color:#888;font-size:0.85rem;margin-top:0.2rem;">${arc.weeks}-week arc · +${arc.rewardSP} SP · +${arc.rewardTXP} TXP</div>
                            <div style="color:#ccc;font-size:0.88rem;margin-top:0.5rem;line-height:1.4;">${arc.desc}</div>
                        </div>
                        <div style="text-align:right;">
                            ${isDone ? '<span style="color:#44cc88;font-size:1.5rem;">✓ Complete</span>' :
                              isActive ? `<button class="btn-danger btn-small" onclick="abandonArc()">Abandon</button>` :
                              `<button class="btn-success btn-small" onclick="enrollArc('${arc.id}')">Enrol</button>`}
                        </div>
                    </div>
                    ${isActive && progress ? `
                    <div style="margin-top:0.75rem;padding-top:0.75rem;border-top:1px solid #2a1a44;">
                        <div style="font-size:0.8rem;color:#888;margin-bottom:0.4rem;">Progress (${progress.sessionsLogged}/${arc.weeks * arc.requirements.workoutsPerWeek} sessions target)</div>
                        <div style="background:#0a0a0f;border-radius:4px;height:10px;overflow:hidden;">
                            <div style="height:100%;background:${arc.color};width:${Math.min(100, progress.pct).toFixed(0)}%;transition:width 0.3s;"></div>
                        </div>
                        <div style="font-size:0.75rem;color:#666;margin-top:0.3rem;">Started ${char.activeArc.startDate} · ${progress.daysLeft} days remaining</div>
                    </div>` : ''}
                    <div style="margin-top:0.6rem;">
                        ${arc.checklist.map(c => {
                            const done = isDone || (isActive && checkArcChecklistItem(char, arc, c));
                            return `<div style="font-size:0.78rem;color:${done?'#44cc88':'#666'};margin-top:0.2rem;">${done?'✓':'○'} ${c}</div>`;
                        }).join('')}
                    </div>
                </div>`;
            });
            el.innerHTML = html;
        }

        function enrollArc(arcId) {
            const char = getActiveCharacter();
            if (char.activeArc) { v6Alert('You are already enrolled in an arc. Abandon it first.'); return; }
            const arc = TRAINING_ARCS.find(a => a.id === arcId);
            if (!arc) return;
            if ((char.completedArcs || []).includes(arcId)) {
                if (!confirm('You\'ve already completed this arc. Repeat it?')) return;
            }
            char.activeArc = { id: arcId, startDate: new Date().toISOString().slice(0,10) };
            saveState();
            renderTrainingArcs();
            v6Alert(`Enrolled in ${arc.name}! Train consistently to complete it.`);
        }

        function abandonArc() {
            if (!confirm('Abandon this training arc? Progress will be lost.')) return;
            getActiveCharacter().activeArc = null;
            saveState();
            renderTrainingArcs();
        }

        function getArcProgress(char, arc) {
            if (!char.activeArc) return null;
            const startDate = char.activeArc.startDate;
            const endDate = new Date(startDate);
            endDate.setDate(endDate.getDate() + arc.weeks * 7);
            const now = new Date();
            const daysLeft = Math.max(0, Math.ceil((endDate - now) / 86400000));
            const sessionsLogged = (char.workoutLog || []).filter(w => w.date >= startDate).length;
            const target = arc.weeks * arc.requirements.workoutsPerWeek;
            const pct = (sessionsLogged / target) * 100;
            return { sessionsLogged, target, pct, daysLeft };
        }

        function checkArcChecklistItem(char, arc, item) {
            if (!char.activeArc) return false;
            const start = char.activeArc.startDate;
            const logs = (char.workoutLog || []).filter(w => w.date >= start);
            const sessions = logs.length;
            // Simple heuristic checks
            if (item.includes('3+ strength')) return logs.filter(w => (w.exercises||[]).some(e => !['Outdoor Run','Treadmill Run','Intervals','Outdoor Ride','Stationary Bike','Rowing Machine','HIIT Class','Jump Rope'].includes(e.name))).length >= 3;
            if (item.includes('cardio sessions')) return logs.filter(w => (w.exercises||[]).some(e => ['Outdoor Run','Treadmill Run','Intervals','Outdoor Ride','Stationary Bike','Rowing Machine','HIIT Class','Jump Rope','Burpees'].includes(e.name))).length >= 3;
            if (item.includes('15+ km')) { let km = 0; logs.forEach(w => { (w.exercises||[]).forEach(e => { if (e.inputs?.distance) km += e.inputs.distance; }); }); return km >= 15; }
            if (item.includes('12+ sessions')) return sessions >= 12;
            if (item.includes('16+ sessions')) return sessions >= 16;
            if (item.includes('30+ sessions')) return sessions >= 30;
            if (item.includes('9+ cardio')) return logs.filter(w => (w.exercises||[]).some(e => ['Outdoor Run','Treadmill Run','Intervals','Outdoor Ride','Stationary Bike','Rowing Machine','HIIT Class','Jump Rope'].includes(e.name))).length >= 9;
            if (item.includes('7-day streak')) return (char.currentStreak || 0) >= 7;
            if (item.includes('personal record')) return Object.keys(char.personalRecords || {}).length > 0;
            if (item.includes('martial arts')) return logs.some(w => (w.exercises||[]).some(e => e.category === 'martial' || ['Kata Practice','Shadow Boxing','Sparring','Ki Meditation'].includes(e.name)));
            return false;
        }

        function checkArcCompletion(char) {
            if (!char.activeArc) return;
            const arc = TRAINING_ARCS.find(a => a.id === char.activeArc.id);
            if (!arc) return;
            const progress = getArcProgress(char, arc);
            if (!progress) return;
            if (progress.pct >= 100) {
                char.completedArcs = char.completedArcs || [];
                if (!char.completedArcs.includes(arc.id)) {
                    char.completedArcs.push(arc.id);
                    char.spEarned = (char.spEarned || 0) + arc.rewardSP;
                    char.totalTXP = (char.totalTXP || 0) + arc.rewardTXP;
                    char.activeArc = null;
                    saveState();
                    setTimeout(() => {
                        v6Alert(`🎉 Training Arc Complete!\n\n${arc.name}\n\nRewards: +${arc.rewardSP} SP, +${arc.rewardTXP} TXP`);
                    }, 500);
                }
            }
        }

        // ════ SAGA/TRANSFORMATION EVENTS ════
        function showGameEvent(event = {}) {
            const overlay = document.getElementById('sagaEventOverlay');
            const box = document.getElementById('sagaEventBox');
            if (!overlay || !box) return;
            const type = event.type || 'milestone';
            const rewardText = formatRewardBundle(event.reward || {});
            const colorStyle = event.color ? `style="color:${event.color};text-shadow:0 0 30px ${event.color};"` : '';
            box.innerHTML = `<div class="event-overlay-card ${type}">
                <div class="event-kicker">${event.title || 'Progress'}</div>
                <div class="event-name" ${colorStyle}>${event.name || 'Unlocked'}</div>
                ${event.detail ? `<div class="event-detail">${event.detail}</div>` : ''}
                ${rewardText ? `<div class="event-reward">${rewardText}</div>` : ''}
            </div>`;
            overlay.classList.add('active');
            clearTimeout(overlay._eventTimer);
            overlay._eventTimer = setTimeout(() => overlay.classList.remove('active'), event.duration || 3400);
        }

        function queueGameEvents(events = [], startDelay = 0) {
            events.filter(Boolean).forEach((event, index) => {
                setTimeout(() => showGameEvent(event), startDelay + (index * 3700));
            });
        }

        function showSagaCompleteEvent(saga) {
            const overlay = document.getElementById('sagaEventOverlay');
            const box = document.getElementById('sagaEventBox');
            const seriesName = saga.series === 'DB' ? 'Dragon Ball' : saga.series === 'DBZ' ? 'Dragon Ball Z' : saga.series === 'DBS' ? 'Dragon Ball Super' : 'Dragon Ball Daima';
            box.innerHTML = `<div class="saga-event-box">
                <div class="saga-event-series">⚡ ${seriesName} ⚡</div>
                <div class="saga-event-title">${saga.name}</div>
                <div class="saga-event-sub" style="color:#44cc88;">SAGA COMPLETE</div>
                <div class="saga-event-sub" style="margin-top:0.5rem;">${saga.desc}</div>
            </div>`;
            overlay.classList.add('active');
            setTimeout(() => overlay.classList.remove('active'), 3500);
        }

        function showTransformUnlockEvent(trans) {
            const overlay = document.getElementById('sagaEventOverlay');
            const box = document.getElementById('sagaEventBox');
            box.innerHTML = `<div class="transform-event-box">
                <div class="saga-event-series" style="color:#cc88ff;">NEW TRANSFORMATION</div>
                <div class="transform-event-name" style="color:${trans.color || '#ffffff'};text-shadow:0 0 30px ${trans.color || '#ffffff'};">${trans.name}</div>
                <div class="saga-event-sub">${trans.desc}</div>
            </div>`;
            overlay.classList.add('active');
            setTimeout(() => overlay.classList.remove('active'), 3000);
        }

        // ════ 1-REP MAX CALCULATOR ════
        function epley1RM(weight, reps) {
            if (!weight || !reps || reps <= 0) return null;
            if (reps === 1) return weight;
            return Math.round(weight * (1 + reps / 30) * 10) / 10;
        }

        // ════ WORKOUT TEMPLATES ════
        function saveCurrentAsTemplate() {
            if (currentWorkoutSession.length === 0) return v6Alert('No exercises in session to save.');
            const name = prompt('Template name:', 'My Workout');
            if (!name) return;
            const template = {
                id: Date.now(),
                name,
                exercises: currentWorkoutSession.map(item => ({
                    exerciseJson: JSON.stringify(item.exercise),
                    name: item.exercise.name,
                    type: item.exercise.type,
                    speedInput: !!item.exercise.speedInput,
                    inputs: { ...item.inputs }
                }))
            };
            if (!state.workoutTemplates) state.workoutTemplates = [];
            state.workoutTemplates.push(template);
            saveState();
            v6Alert(`Template "${name}" saved!`);
        }

        function openTemplatesModal() {
            if (!state.workoutTemplates || state.workoutTemplates.length === 0) {
                v6Alert('No templates saved yet. Build a session and click "Save as Template".');
                return;
            }
            const div = document.getElementById('templatesListDiv');
            div.innerHTML = state.workoutTemplates.map((t, i) => `
                <div style="background:#12121a;border:1px solid #2a1a44;border-radius:6px;padding:0.75rem;margin-bottom:0.5rem;display:flex;justify-content:space-between;align-items:center;">
                    <div>
                        <div style="color:#ffaa00;font-weight:bold;">${t.name}</div>
                        <div style="color:#888;font-size:0.8rem;">${t.exercises.length} exercise${t.exercises.length !== 1 ? 's' : ''}: ${t.exercises.map(e=>e.name).join(', ')}</div>
                    </div>
                    <div style="display:flex;gap:0.5rem;">
                        <button class="btn-success btn-small" onclick="openApplyTemplate(${i});document.getElementById('templatesModal').classList.remove('active');">Load</button>
                        <button class="btn-secondary btn-small" onclick="openEditTemplate(${i});document.getElementById('templatesModal').classList.remove('active');">Edit</button>
                        <button class="btn-secondary btn-small" onclick="renameTemplate(${i})">Rename</button>
                        <button class="btn-secondary btn-small" onclick="duplicateTemplate(${i})">Duplicate</button>
                        <button class="btn-danger btn-small" onclick="deleteTemplate(${i})">✕</button>
                    </div>
                </div>
            `).join('');
            document.getElementById('templatesModal').classList.add('active');
        }

        function deleteTemplate(idx) {
            if (!confirm('Delete this template?')) return;
            state.workoutTemplates.splice(idx, 1);
            saveState();
            openTemplatesModal();
        }

        function renameTemplate(idx) {
            const t = state.workoutTemplates[idx];
            if (!t) return;
            const name = prompt('Template name:', t.name);
            if (!name) return;
            t.name = name;
            saveState();
            openTemplatesModal();
        }

        function duplicateTemplate(idx) {
            const t = state.workoutTemplates[idx];
            if (!t) return;
            const copy = JSON.parse(JSON.stringify(t));
            copy.id = Date.now();
            copy.name = `${t.name} Copy`;
            state.workoutTemplates.push(copy);
            saveState();
            openTemplatesModal();
        }

        function addTemplateSetRow(i, type) {
            addSetRow(`tpl_setRows_${i}`, type, `tpl_${i}`);
        }

        function openApplyTemplate(idx) {
            const t = state.workoutTemplates[idx];
            if (!t) return;
            let html = '';
            t.exercises.forEach((ex, i) => {
                html += `<div style="background:#12121a;border:1px solid #2a1a44;border-radius:6px;padding:0.75rem;margin-bottom:0.6rem;">
                    <div style="color:#ffaa00;font-weight:bold;margin-bottom:0.5rem;">${ex.name}</div>`;
                if (['weighted', 'bodyweight', 'timed_hold'].includes(ex.type)) {
                    const isDumbbell = ex.name.toLowerCase().includes('dumbbell') || ex.name.toLowerCase().includes('dumbell');
                    const hint = isDumbbell ? '<div style="color:#ffaa00;font-size:0.72rem;margin-bottom:0.4rem;">Total of both dumbbells</div>' : '';
                    const label = ex.type === 'timed_hold' ? 'Timed holds:' : 'Sets:';
                    const btnText = ex.type === 'timed_hold' ? '+ Add Hold' : '+ Add Set';
                    const sets = setsFromInputs(ex.type, ex.inputs || {});
                    html += `<div style="margin-top:0.35rem;">
                        <div style="font-size:0.82rem;color:#aaa;margin-bottom:0.35rem;">${label}</div>
                        ${hint}
                        <div id="tpl_setRows_${i}" data-set-container>${sets.map((set, setIdx) => exerciseSetRowHTML(ex.type, setIdx, set, `tpl_${i}`)).join('')}</div>
                        <button type="button" class="btn-secondary btn-small" onclick="addTemplateSetRow(${i}, '${ex.type}')" style="margin-top:0.35rem;">${btnText}</button>
                    </div>`;
                } else if (ex.type === 'cardio_distance') {
                    html += `<div style="display:flex;gap:0.75rem;flex-wrap:wrap;">
                        <label style="font-size:0.82rem;color:#aaa;">Distance (km):<br><input type="number" id="tpl_dist_${i}" value="${ex.inputs.distance||5}" min="0.1" step="0.1" style="width:80px;margin-top:0.2rem;"></label>
                        ${ex.speedInput || ex.inputs.speed ? `<label style="font-size:0.82rem;color:#aaa;">Speed (km/h):<br><input type="number" id="tpl_speed_${i}" value="${ex.inputs.speed||8.5}" min="0.1" step="0.1" style="width:90px;margin-top:0.2rem;"></label>` : `<label style="font-size:0.82rem;color:#aaa;">Time (min):<br><input type="number" id="tpl_dur_${i}" value="${ex.inputs.duration||30}" min="1" style="width:80px;margin-top:0.2rem;"></label>`}
                    </div>`;
                } else if (ex.type === 'cardio_duration') {
                    html += `<label style="font-size:0.82rem;color:#aaa;">Duration (min):<br><input type="number" id="tpl_dur_${i}" value="${ex.inputs.duration||30}" min="1" style="width:80px;margin-top:0.2rem;"></label>`;
                }
                html += `</div>`;
            });
            document.getElementById('applyTemplateContent').innerHTML = html;
            const title = document.querySelector('#applyTemplateModal .modal-header');
            if (title) title.textContent = 'Load Template';
            const btn = document.getElementById('confirmApplyTemplateBtn');
            if (btn) {
                btn.textContent = 'Load into Session';
                btn.onclick = () => applyTemplate(t);
            }
            document.getElementById('applyTemplateModal').classList.add('active');
        }

        function collectTemplateInputs(ex, i) {
            const inputs = {};
            if (['weighted', 'bodyweight', 'timed_hold'].includes(ex.type)) {
                const setsList = collectSetRows(`tpl_setRows_${i}`, ex.type);
                if (!setsList.length) return null;
                Object.assign(inputs, aggregateSetInputs(ex.type, setsList));
            } else if (ex.type === 'cardio_distance') {
                inputs.distance = parseFloat(document.getElementById(`tpl_dist_${i}`)?.value) || ex.inputs.distance || 5;
                if (ex.speedInput || ex.inputs.speed) {
                    inputs.speed = parseFloat(document.getElementById(`tpl_speed_${i}`)?.value) || ex.inputs.speed || 8.5;
                } else {
                    inputs.duration = parseFloat(document.getElementById(`tpl_dur_${i}`)?.value) || ex.inputs.duration || 30;
                }
            } else if (ex.type === 'cardio_duration') {
                inputs.duration = parseFloat(document.getElementById(`tpl_dur_${i}`)?.value) || ex.inputs.duration || 30;
            }
            return inputs;
        }

        function openEditTemplate(idx) {
            const t = state.workoutTemplates[idx];
            if (!t) return;
            openApplyTemplate(idx);
            const title = document.querySelector('#applyTemplateModal .modal-header');
            if (title) title.textContent = `Edit Template: ${t.name}`;
            const btn = document.getElementById('confirmApplyTemplateBtn');
            if (btn) {
                btn.textContent = 'Save Template';
                btn.onclick = () => saveEditedTemplate(idx);
            }
        }

        function saveEditedTemplate(idx) {
            const t = state.workoutTemplates[idx];
            if (!t) return;
            t.exercises.forEach((ex, i) => {
                const inputs = collectTemplateInputs(ex, i);
                if (inputs) ex.inputs = inputs;
            });
            saveState();
            document.getElementById('applyTemplateModal').classList.remove('active');
            const btn = document.getElementById('confirmApplyTemplateBtn');
            if (btn) btn.textContent = 'Apply Template';
            openTemplatesModal();
        }

        function applyTemplate(t) {
            currentWorkoutSession = [];
            t.exercises.forEach((ex, i) => {
                let exercise;
                try { exercise = JSON.parse(ex.exerciseJson); } catch(e) { return; }
                const inputs = collectTemplateInputs(ex, i);
                if (!inputs) return;
                const gains = computeStatGains(exercise, inputs);
                currentWorkoutSession.push({ exercise, inputs, gains, name: ex.name });
            });
            document.getElementById('applyTemplateModal').classList.remove('active');
            renderWorkoutLog();
            // Switch to Training tab, where workout logging now lives.
            document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
            document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
            document.querySelector('.tab-btn[data-tab="training"]').classList.add('active');
            document.getElementById('training').classList.add('active');
            applyTabBg('training');
            renderTraining();
        }

