        function tplSets(reps, weight, count = 3) {
            return Array.from({ length: count }, () => {
                const set = { reps };
                if (weight !== null && weight !== undefined) {
                    set.weight = weight;
                    set.manualWeight = true;
                }
                return set;
            });
        }

        function tplPyramid(reps, weights = null) {
            return reps.map((rep, idx) => {
                const set = { reps: rep };
                const weight = Array.isArray(weights) ? weights[idx] : weights;
                if (weight !== null && weight !== undefined) {
                    set.weight = weight;
                    set.manualWeight = true;
                }
                return set;
            });
        }

        function tplHold(seconds) {
            return [{ seconds }];
        }

