            const v5_today = () => new Date().toISOString().slice(0, 10);
            const v5_num = value => Number.isFinite(Number(value)) ? Number(value) : 0;
            const v5_clamp = (value, min, max) => Math.max(min, Math.min(max, value));
            const v5_escape = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
            const v5_statusAtLeast = (status, target) => (SAGA_STATUS_RANK[status] || 0) >= (SAGA_STATUS_RANK[target] || 0);

            function v5_getSagaById(id) {
                return SAGAS.find(saga => saga.id === id) || null;
            }
            window.v5_getSagaById = v5_getSagaById;

            function v5_statMap(values = 0) {
                return Object.fromEntries(STATS.map(stat => [stat, typeof values === 'object' ? v5_num(values[stat]) : values]));
            }
            window.v5_statMap = v5_statMap;

            function v5_buildSagaStatTargets(basePL) {
                const score = Math.max(0, v5_num(basePL) - POWER_CONFIG.seedPL);
                const profile = { STR: 0.18, END: 0.15, AGI: 0.15, VIT: 0.13, SPI: 0.21, TEC: 0.18 };
                const weights = { STR: 1.10, END: 0.95, AGI: 1.00, VIT: 0.90, SPI: 1.15, TEC: 1.05 };
                const targets = {};
                Object.entries(profile).forEach(([stat, share]) => {
                    targets[stat] = Math.max(0, Math.round((score * share) / (weights[stat] || 1)));
                });
                return targets;
            }

            function v5_reorderSagasForRebalance() {
                const byId = new Map(SAGAS.map(saga => [saga.id, saga]));
                const plannedIds = new Set(SAGA_REBALANCE_ROWS.map(row => row.id));
                const reordered = SAGA_REBALANCE_ROWS.map(row => byId.get(row.id)).filter(Boolean);
                SAGAS.forEach(saga => {
                    if (!plannedIds.has(saga.id)) reordered.push(saga);
                });
                SAGAS.splice(0, SAGAS.length, ...reordered);
            }

            function v5_patchSagaData() {
                v5_reorderSagasForRebalance();
                STORY_CONFIG.finalSagaUnlockXP = Math.round((SAGA_TARGET_WEEKS.dbs_granolah || 208) * STORY_CONFIG.weeklyStoryXPCap);
                STORY_CONFIG.finalSagaClearXP = STORY_CONFIG.finalSagaUnlockXP;
                SAGAS.forEach((saga, index) => {
                    const row = SAGA_REBALANCE_BY_ID[saga.id] || null;
                    const prevRow = index > 0 ? (SAGA_REBALANCE_BY_ID[SAGAS[index - 1]?.id] || null) : null;
                    const nextRow = SAGAS[index + 1] ? (SAGA_REBALANCE_BY_ID[SAGAS[index + 1].id] || null) : null;
                    const unlockWeek = row?.week ?? (SAGA_TARGET_WEEKS[saga.id] ?? Math.round(index * 5.5));
                    const nextWeek = nextRow?.week ?? unlockWeek;
                    const clearWeek = row ? (nextRow ? Math.max(unlockWeek + 1, Math.round(unlockWeek + (nextWeek - unlockWeek) * 0.65)) : unlockWeek) : Math.max(unlockWeek + 6, Math.round(unlockWeek * 1.45));
                    const masterWeek = row ? Math.max(clearWeek + 2, Math.round(unlockWeek + (nextWeek - unlockWeek) * 1.15)) : Math.max(clearWeek + 10, Math.round(unlockWeek * 1.8 + 20));
                    const focusClearWindow = Math.max(1, clearWeek - unlockWeek);
                    const focusMasterWindow = Math.max(1, masterWeek - clearWeek);
                    const focusPace = saga.id.startsWith('dbs_') ? 34 : saga.id.startsWith('daima_') ? 32 : saga.id.startsWith('dbz_') ? 30 : 20;
                    const clearFocusXP = Math.max(20, Math.round(focusClearWindow * focusPace));
                    const masterFocusXP = Math.max(clearFocusXP + 25, Math.round(clearFocusXP + focusMasterWindow * (focusPace + 8)));
                    const baseUnlockPL = row ? (prevRow ? prevRow.effectiveEndPL : POWER_CONFIG.seedPL) : Math.round(Number(saga.plReq || 0) <= 5 ? POWER_CONFIG.seedPL : Math.max(Number(SAGAS[index - 1]?.plReq || 0), Number(saga.plReq || 0) * 0.35));
                    const effectiveUnlockPL = baseUnlockPL;
                    const baseEndPL = row?.baseEndPL ?? Number(saga.plReq || 0);
                    const effectiveEndPL = row?.effectiveEndPL ?? Number(saga.plReq || 0);
                    const statTargets = row ? v5_buildSagaStatTargets(baseEndPL) : { ...(saga.statReqs || {}) };
                    const affinities = SAGA_AFFINITY_PRESETS[saga.id] || {
                        stats: Object.keys(saga.statReqs || {}).slice(0, 2).length ? Object.keys(saga.statReqs || {}).slice(0, 2) : ['STR', 'SPI'],
                        categories: ['martial', 'strength'],
                        tags: [String(saga.series || '').toLowerCase()]
                    };
                    saga.order = index + 1;
                    saga.baseOnly = false;
                    saga.targetUnlockWeek = unlockWeek;
                    saga.targetClearWeek = clearWeek;
                    saga.targetMasterWeek = masterWeek;
                    saga.baseUnlockPL = baseUnlockPL;
                    saga.baseEndPL = baseEndPL;
                    saga.effectiveUnlockPL = effectiveUnlockPL;
                    saga.effectiveEndPL = effectiveEndPL;
                    saga.sagaTransformLabel = row?.transform || 'Best equipped transformation';
                    saga.sagaTransformMultiplier = row?.transformMultiplier || 1;
                    saga.baseStatTargets = statTargets;
                    saga.gplReq = saga.id.startsWith('daima_') ? 0 : (row?.gplReq || 0);
                    if (row) {
                        saga.plReq = effectiveUnlockPL;
                        saga.statReqs = {};
                    }
                    saga.unlockReqs = {
                        ...(saga.unlockReqs || {}),
                        storyXP: Math.round(unlockWeek * STORY_CONFIG.weeklyStoryXPCap),
                        displayPL: effectiveUnlockPL,
                        effectivePL: effectiveUnlockPL,
                        basePL: baseUnlockPL,
                        godPL: saga.id === 'dbs_beerus' || saga.id.startsWith('daima_') ? 0 : (row?.gplReq || Number(saga.gplReq || 0) || 0)
                    };
                    saga.clearReqs = {
                        storyXP: Math.round(clearWeek * STORY_CONFIG.weeklyStoryXPCap),
                        displayPL: effectiveEndPL,
                        effectivePL: effectiveEndPL,
                        basePL: baseEndPL,
                        godPL: saga.id.startsWith('daima_') ? 0 : Number(row?.gplReq || saga.gplReq || 0),
                        stats: row ? {} : { ...(saga.statReqs || {}) },
                        baseStatTargets: { ...statTargets },
                        focusXP: clearFocusXP,
                        fitnessScore: row ? 0 : Math.round(25 + unlockWeek * 7)
                    };
                    saga.masterReqs = {
                        storyXP: Math.round(masterWeek * STORY_CONFIG.weeklyStoryXPCap),
                        displayPL: row ? Math.round(effectiveEndPL * 1.08) : Math.round(Number(saga.plReq || 0) * (saga.gplReq ? 1.4 : 1.65)),
                        effectivePL: row ? Math.round(effectiveEndPL * 1.08) : Math.round(Number(saga.plReq || 0) * (saga.gplReq ? 1.4 : 1.65)),
                        basePL: row ? Math.round(baseEndPL * 1.08) : Number(saga.plReq || 0),
                        godPL: saga.id.startsWith('daima_') ? 0 : (row?.gplReq ? Math.round(Number(row.gplReq) * 1.5) : (saga.gplReq ? Math.round(Number(saga.gplReq || 0) * 1.5) : 0)),
                        stats: row ? {} : Object.fromEntries(Object.entries(saga.statReqs || {}).map(([stat, value]) => [stat, Math.round(Number(value || 0) * 1.45)])),
                        baseStatTargets: row ? v5_buildSagaStatTargets(Math.round(baseEndPL * 1.08)) : {},
                        focusXP: masterFocusXP,
                        fitnessScore: row ? 0 : Math.round(40 + unlockWeek * 10)
                    };
                    saga.affinities = { stats: [], categories: [], partnerTags: [], abilityTags: [], transformationTags: [], ...affinities };
                    saga.focusBoost = saga.focusBoost || {
                        statGain: Object.fromEntries((saga.affinities.stats || []).slice(0, 3).map(stat => [stat, stat === 'GKI' ? 0.04 : 0.055])),
                        categoryGain: Object.fromEntries((saga.affinities.categories || []).slice(0, 3).map(category => [category, 0.04])),
                        apGain: saga.id.startsWith('dbs_') || saga.id.startsWith('daima_') ? 0.04 : 0.025,
                        sagaFocusXPGain: 0.08,
                        partnerXP: { byTag: Object.fromEntries((saga.affinities.partnerTags || saga.affinities.tags || []).slice(0, 3).map(tag => [tag, 0.12])) }
                    };
                    saga.clearReward = saga.clearReward || {
                        ap: saga.id === 'db_pilaf' ? 1 : (saga.id.startsWith('dbs_') ? 4 : 2),
                        tp: saga.id.startsWith('dbs_') ? 10 : 5,
                        passiveBoost: { statGain: Object.fromEntries((saga.affinities.stats || []).slice(0, 2).map(stat => [stat, 0.006])) }
                    };
                    saga.masteryReward = saga.masteryReward || {
                        ap: saga.id.startsWith('dbs_') ? 3 : 1,
                        tp: saga.id.startsWith('dbs_') ? 8 : 4,
                        passiveBoost: {
                            statGain: Object.fromEntries((saga.affinities.stats || []).slice(0, 3).map(stat => [stat, 0.015])),
                            partnerXP: { byTag: Object.fromEntries((saga.affinities.partnerTags || saga.affinities.tags || []).slice(0, 3).map(tag => [tag, 0.04])) }
                        }
                    };
                });
            }

            function v6ScaleProgressionRequirements(requirements, sagaId, targetShare = 0.75) {
                const scaled = { ...(requirements || {}) };
                const statEntries = Object.entries(scaled).filter(([stat, value]) =>
                    STATS.includes(stat) && stat !== 'GKI' && Number(value) > 0
                );
                if (!statEntries.length) return scaled;
                const week = SAGA_TARGET_WEEKS[sagaId || scaled.sagaId] ?? 0;
                const targetScore = Math.max(40, window.DBZ_V6_CONFIG.basePowerTargetForWeek(week) * targetShare);
                const currentScore = statEntries.reduce((sum, [stat, value]) =>
                    sum + Number(value) * Number(window.DBZ_V6_CONFIG.statWeights[stat] || 1), 0
                );
                if (currentScore > targetScore) {
                    const scale = targetScore / currentScore;
                    statEntries.forEach(([stat, value]) => {
                        scaled[stat] = Math.max(1, Math.round(Number(value) * scale));
                    });
                }
                if (Number(scaled.level) > 0) {
                    scaled.level = Math.min(Number(scaled.level), Math.max(5, Math.round(8 + week * 0.72)));
                }
                return scaled;
            }

            function v5_patchAbilityData() {
                ABILITIES.forEach(ability => {
                    ability.reqs = v6ScaleProgressionRequirements(ability.reqs, ability.sagaId, 0.48);
                    const authored = ABILITY_EFFECT_LIBRARY[ability.id] || {};
                    ability.tags = [...new Set([...(ability.tags || []), ...(authored.tags || []), ...(String(ability.name || '').toLowerCase().includes('kamehameha') ? ['ki', 'beam'] : [])])];
                    ability.maxRank = ABILITY_MAX_LEVEL;
                    ability.ranks = ABILITY_MAX_LEVEL;
                    ability.slotCost = Number(ability.slotCost || 1);
                    ability.levelBalance = buildAbilityLevelBalance(ability, authored);
                    ability.apCost = null;
                    ability.effectsByRank = [getAbilityScaledEffects(ability, 1), getAbilityScaledEffects(ability, ABILITY_MAX_LEVEL)];
                    ability.synergies = authored.synergies || ability.synergies || [];
                });
            }

            function getAbilityTierConfig(ability) {
                const sagaId = ability?.sagaId || 'db_pilaf';
                if (ABILITY_TIER_BY_SAGA[sagaId]) return ABILITY_TIER_BY_SAGA[sagaId];
                if (String(sagaId).startsWith('dbs_')) return ABILITY_TIER_BY_SAGA.dbs_universe_survival;
                if (String(sagaId).startsWith('dbz_')) return ABILITY_TIER_BY_SAGA.dbz_frieza;
                if (String(sagaId).startsWith('daima_')) return ABILITY_TIER_BY_SAGA.daima_demon;
                return ABILITY_TIER_BY_SAGA.db_tournament;
            }

            function normalizeAbilityProfile(profile) {
                const clean = {};
                let total = 0;
                Object.entries(profile || {}).forEach(([stat, value]) => {
                    if (!STATS.includes(stat)) return;
                    const val = Math.max(0, v5_num(value));
                    if (!val) return;
                    clean[stat] = val;
                    total += val;
                });
                if (!total) return { SPI: 1 };
                Object.keys(clean).forEach(stat => { clean[stat] = clean[stat] / total; });
                return clean;
            }

            function inferAbilityProfile(ability) {
                const reqs = ability.reqs || {};
                const stats = Object.keys(reqs).filter(key => STATS.includes(key));
                const name = String(ability.name || '').toLowerCase();
                const tags = new Set(ability.tags || []);
                if (name.includes('kamehameha')) return normalizeAbilityProfile({ SPI: 0.46, STR: 0.34, END: 0.10, GKI: tags.has('god') ? 0.10 : 0 });
                if (name.includes('flash') || name.includes('blast') || name.includes('beam') || name.includes('gun') || name.includes('cannon')) return normalizeAbilityProfile({ SPI: 0.38, STR: 0.36, AGI: 0.14, END: 0.12 });
                if (name.includes('time') || name.includes('transmission') || name.includes('skip')) return normalizeAbilityProfile({ AGI: 0.46, SPI: 0.34, END: 0.12, GKI: tags.has('god') ? 0.08 : 0 });
                if (name.includes('disc') || name.includes('saucer') || name.includes('snipe') || tags.has('precision')) return normalizeAbilityProfile({ AGI: 0.38, SPI: 0.34, STR: 0.18, GKI: tags.has('god') ? 0.10 : 0 });
                if (name.includes('destruction') || name.includes('explosion') || name.includes('supernova') || name.includes('death ball')) return normalizeAbilityProfile({ STR: 0.40, SPI: 0.32, VIT: 0.18, GKI: tags.has('god') ? 0.10 : 0 });
                if (name.includes('pose') || name.includes('sense') || name.includes('spirit')) return normalizeAbilityProfile({ SPI: 0.58, AGI: 0.16, VIT: 0.14, END: 0.12 });
                if (!stats.length) return { SPI: 1 };
                const result = {};
                stats.slice(0, 4).forEach((stat, idx) => { result[stat] = idx === 0 ? 0.46 : idx === 1 ? 0.28 : idx === 2 ? 0.16 : 0.10; });
                return normalizeAbilityProfile(result);
            }

            function inferAbilityCategories(ability) {
                const tags = new Set(ability.tags || []);
                const name = String(ability.name || '').toLowerCase();
                const categories = {};
                if (tags.has('beam') || tags.has('ki') || name.includes('kamehameha')) categories.martial = 0.30;
                if (name.includes('kamehameha') || name.includes('cannon') || name.includes('core')) categories.core = 0.18;
                if (name.includes('fist') || name.includes('strike') || name.includes('slash') || name.includes('punch')) categories.strength = 0.22;
                if (name.includes('time') || name.includes('flash') || name.includes('transmission') || tags.has('speed')) categories.cardio = 0.20;
                if (tags.has('movement') || name.includes('after-image')) categories.flexibility = 0.14;
                if (tags.has('spirit') || tags.has('god') || name.includes('hakai')) categories.meditation = 0.18;
                if (!Object.keys(categories).length) categories.martial = 0.22;
                return categories;
            }

            function buildAbilityLevelBalance(ability, authored = {}) {
                const tier = getAbilityTierConfig(ability);
                const override = ABILITY_POWER_OVERRIDES[ability.id] || {};
                const reqs = ability.reqs || {};
                const tags = new Set([...(ability.tags || []), ...(authored.tags || [])]);
                const hasTransformationGate = Array.isArray(reqs.transformations) || Boolean(reqs.transformation);
                const hasGodGate = Boolean(reqs.GKI) || tags.has('god') || String(ability.sagaId || '').startsWith('dbs_') || String(ability.sagaId || '').startsWith('daima_');
                const costMod = 0.88 + Math.min(0.30, v5_num(ability.spCost) / 80);
                const gateMod = 1 + (hasTransformationGate ? 0.16 : 0) + (hasGodGate ? 0.10 : 0);
                const totalPower = v5_num(override.power || (tier.power * (override.powerMult || 1) * costMod * gateMod));
                const profile = normalizeAbilityProfile(override.profile || inferAbilityProfile(ability));
                const categoryProfile = override.categories || inferAbilityCategories(ability);
                const statGain = {};
                Object.entries(profile).forEach(([stat, share]) => {
                    if (stat === 'GKI' && !hasGodGate && !v5_num(reqs.GKI)) return;
                    statGain[stat] = +(totalPower * share).toFixed(4);
                });
                const categoryGain = {};
                Object.entries(categoryProfile).forEach(([category, share]) => {
                    categoryGain[category] = +(totalPower * v5_num(share)).toFixed(4);
                });
                const baseEffects = {
                    statGain,
                    categoryGain,
                    txpGain: +(Math.min(0.22, totalPower * (tags.has('starter') ? 0.10 : 0.055))).toFixed(4),
                    tpGain: +(v5_num(override.tpGain) || 0).toFixed(4),
                    apGain: +(v5_num(override.apGain) || (hasGodGate ? Math.min(0.08, totalPower * 0.025) : 0)).toFixed(4),
                    characterXP: authored.effectsByRank?.[0]?.characterXP || authored.effectsByRank?.[0]?.characterXp,
                    partnerXP: authored.effectsByRank?.[0]?.partnerXP || (tags.has('goku_family') ? { byTag: { goku_family: 0.08 } } : tags.has('vegeta_family') ? { byTag: { vegeta_family: 0.08 } } : undefined)
                };
                return {
                    tierPower: tier.power,
                    xpTax: tier.xpTax,
                    growth: v5_num(override.growth || tier.growth),
                    baseEffects
                };
            }

            function scaleEffectBlock(source, scale) {
                const effects = {};
                if (source.statGain) effects.statGain = Object.fromEntries(Object.entries(source.statGain).map(([key, value]) => [key, +(v5_num(value) * scale).toFixed(4)]));
                if (source.categoryGain) effects.categoryGain = Object.fromEntries(Object.entries(source.categoryGain).map(([key, value]) => [key, +(v5_num(value) * scale).toFixed(4)]));
                if (source.typeGain) effects.typeGain = Object.fromEntries(Object.entries(source.typeGain).map(([key, value]) => [key, +(v5_num(value) * scale).toFixed(4)]));
                ['txpGain', 'tpGain', 'apGain', 'storyXPGain', 'sagaFocusXPGain'].forEach(key => {
                    if (source[key]) effects[key] = +(v5_num(source[key]) * Math.sqrt(scale)).toFixed(4);
                });
                const xpScale = Math.sqrt(scale);
                const xpSources = [source.partnerXP, source.partnerXp, source.characterXP, source.characterXp].filter(Boolean);
                xpSources.forEach(xpSource => {
                    const xpObject = typeof xpSource === 'number' ? {} : xpSource;
                    effects.partnerXP = effects.partnerXP || { global: 0, byTag: {}, byPartner: {} };
                    effects.partnerXP.global += +(v5_num(typeof xpSource === 'number' ? xpSource : xpObject.global) * xpScale).toFixed(4);
                    Object.entries(xpObject.byTag || {}).forEach(([key, value]) => { effects.partnerXP.byTag[key] = +(v5_num(effects.partnerXP.byTag[key]) + v5_num(value) * xpScale).toFixed(4); });
                    Object.entries(xpObject.byPartner || {}).forEach(([key, value]) => { effects.partnerXP.byPartner[key] = +(v5_num(effects.partnerXP.byPartner[key]) + v5_num(value) * xpScale).toFixed(4); });
                });
                return effects;
            }

            function getAbilityScaledEffects(ability, level = 1) {
                const balance = ability?.levelBalance || buildAbilityLevelBalance(ability || {}, ABILITY_EFFECT_LIBRARY[ability?.id] || {});
                const safeLevel = v5_clamp(Math.floor(v5_num(level) || 1), 1, ABILITY_MAX_LEVEL);
                const progress = (safeLevel - 1) / Math.max(1, ABILITY_MAX_LEVEL - 1);
                const scale = 1 + balance.growth * Math.pow(progress, 0.82);
                return scaleEffectBlock(balance.baseEffects, scale);
            }

            function v5_patchTransformationData() {
                TRANSFORMATIONS.forEach(trans => {
                    trans.reqs = v6ScaleProgressionRequirements(trans.reqs, trans.reqs?.sagaId, 0.78);
                    const authored = TRANSFORMATION_EFFECT_LIBRARY[trans.id] || {};
                    trans.powerMultiplier = Number(trans.powerMultiplier || trans.mult || 1);
                    trans.tags = [...new Set([...(trans.tags || []), ...(authored.tags || []), ...(trans.race && trans.race !== 'universal' ? [trans.race] : [])])];
                    trans.effects = authored.effects || trans.effects || {
                        statGain: v5_defaultTransformationStats(trans),
                        categoryGain: { martial: trans.powerMultiplier > 1 ? 0.02 : 0 },
                        partnerXP: trans.race === 'saiyan' || trans.tags.includes('saiyan') ? { byTag: { saiyan: 0.08 } } : undefined
                    };
                });
            }

            function v5_defaultTransformationStats(trans) {
                if (!trans || trans.id === 'base') return {};
                const mult = Math.max(1, Number(trans.powerMultiplier || trans.mult || 1));
                const base = Math.min(0.22, 0.025 + Math.log10(mult) * 0.035);
                const profile = trans.statProfile || {};
                const result = {};
                STATS.forEach(stat => {
                    if (stat === 'GKI' && !trans.tags?.includes('god')) return;
                    const bias = v5_clamp(Number(profile[stat] || 1), 0.7, 1.6);
                    result[stat] = +(base * (0.75 + bias * 0.25)).toFixed(4);
                });
                return result;
            }

            function v5_addKidGokuFormPartners() {
                return;
            }

            function ensureV5Character(char) {
                if (!char) return char;
                if (!char.stats) char.stats = {};
                STATS.forEach(stat => { char.stats[stat] = v5_num(char.stats[stat]); });
                char.storyWeekly = char.storyWeekly && typeof char.storyWeekly === 'object' ? char.storyWeekly : {};
                if (!Number.isFinite(Number(char.storyXP))) char.storyXP = v5_estimateStoryXPFromLog(char);
                char.storyXP = +v5_num(char.storyXP).toFixed(2);
                char.sagaProgress = char.sagaProgress && typeof char.sagaProgress === 'object' ? char.sagaProgress : {};
                SAGAS.forEach((saga, idx) => {
                    const progress = char.sagaProgress[saga.id] || {};
                    const completed = Array.isArray(char.completedSagas) && char.completedSagas.includes(saga.id);
                    const unlockCheck = canUnlockSaga(char, saga, idx);
                    progress.status = completed ? (progress.status === 'mastered' ? 'mastered' : 'cleared') : (progress.status || (unlockCheck.ok ? 'unlocked' : 'locked'));
                    progress.focusXP = v5_num(progress.focusXP);
                    progress.unlockedAt = progress.unlockedAt || (progress.status !== 'locked' ? v5_today() : null);
                    progress.clearedAt = progress.clearedAt || (v5_statusAtLeast(progress.status, 'cleared') ? v5_today() : null);
                    progress.masteredAt = progress.masteredAt || (progress.status === 'mastered' ? v5_today() : null);
                    char.sagaProgress[saga.id] = progress;
                });
                if (!Array.isArray(char.completedSagas)) char.completedSagas = [];
                char.completedSagas = SAGAS.filter(saga => v5_statusAtLeast(char.sagaProgress[saga.id]?.status, 'cleared')).map(saga => saga.id);
                normalizeSagaUnlockChain(char);
                updateSagaUnlocks(char);
                const activeFocus = v5_getSagaById(char.activeSagaFocus);
                if (!activeFocus || !isSagaAtLeast(char, activeFocus.id, 'unlocked')) {
                    const candidate = SAGAS.find(saga => getSagaStatus(char, saga.id) === 'unlocked') || SAGAS.find(saga => isSagaAtLeast(char, saga.id, 'unlocked')) || SAGAS[0];
                    char.activeSagaFocus = candidate?.id || 'db_pilaf';
                }
                char.abilityPointsEarned = Math.max(v5_num(char.abilityPointsEarned), v5_num(char.spEarned));
                char.abilityPointsSpent = Math.max(v5_num(char.abilityPointsSpent), v5_num(char.spSpent));
                migrateAbilityInventory(char);
                ensureAbilityProgressState(char);
                if (historyNeedsBaselineRepair(char)) {
                    rebuildHistoryFromWorkoutLog(char);
                    applyLatestHistoryStatsToCharacter(char);
                }
                char.abilitySlots = v5_clamp(Math.floor(v5_num(char.abilitySlots) || ABILITY_LOADOUT_CONFIG.defaultSlots), ABILITY_LOADOUT_CONFIG.defaultSlots, ABILITY_LOADOUT_CONFIG.maxSlots);
                if (!Array.isArray(char.equippedAbilities)) {
                    char.equippedAbilities = Object.keys(char.purchasedAbilities || {}).filter(id => getAbilityById(id)).slice(0, char.abilitySlots);
                }
                char.equippedAbilities = char.equippedAbilities.filter(id => getAbilityById(id) && (char.purchasedAbilities || {})[id]).slice(0, char.abilitySlots);
                char.transformationSlots = v5_clamp(Math.floor(v5_num(char.transformationSlots) || TRANSFORMATION_LOADOUT_CONFIG.defaultSlots), TRANSFORMATION_LOADOUT_CONFIG.defaultSlots, TRANSFORMATION_LOADOUT_CONFIG.maxSlots);
                if (!Array.isArray(char.equippedTransformations)) char.equippedTransformations = [char.activeTransformation || 'base'];
                if (!char.equippedTransformations.length) char.equippedTransformations = ['base'];
                char.equippedTransformations = char.equippedTransformations
                    .map(id => id || 'base')
                    .filter((id, idx, arr) => arr.indexOf(id) === idx && getTransformationById(id))
                    .slice(0, char.transformationSlots);
                if (!char.equippedTransformations.includes('base') && !char.equippedTransformations.length) char.equippedTransformations = ['base'];
                if (!char.unlockedTransformations) char.unlockedTransformations = ['base'];
                if (!char.unlockedTransformations.includes('base')) char.unlockedTransformations.unshift('base');
                ensureTransformationMasteryState(char);
                char.activeTransformation = char.equippedTransformations[0] || 'base';
                if (!char.partnerLevels || typeof char.partnerLevels !== 'object') char.partnerLevels = {};
                Object.keys(char.partnerLevels).forEach(partnerId => ensurePartnerProgressV5(char, partnerId));
                if (!isGodKiUnlocked(char)) char.stats.GKI = 0;
                return char;
            }

            function ensureAllV5Characters() {
                Object.values(state.characters || {}).forEach(ensureV5Character);
                state.version = GAME_VERSION;
                state.schemaVersion = SAVE_SCHEMA_VERSION;
            }

            function v5_estimateStoryXPFromLog(char) {
                const weekly = {};
                let total = 0;
                (char.workoutLog || []).slice().sort((a, b) => String(a.date || '').localeCompare(String(b.date || ''))).forEach(entry => {
                    const txp = v5_num(entry.totalTXP);
                    const estimated = getStoryXPForWorkout(txp, entry.exercises || []);
                    const date = entry.date || v5_today();
                    const weekKey = typeof getWeekKey === 'function' ? getWeekKey(date) : date.slice(0, 7);
                    weekly[weekKey] = weekly[weekKey] || { earned: 0 };
                    const remaining = Math.max(0, STORY_CONFIG.weeklyStoryXPCap - weekly[weekKey].earned);
                    const awarded = Math.min(remaining, estimated);
                    weekly[weekKey].earned += awarded;
                    total += awarded;
                });
                if (!Object.keys(char.storyWeekly || {}).length) char.storyWeekly = weekly;
                return +total.toFixed(2);
            }

            function ensurePartnerProgressV5(char, partnerId) {
                const progress = char.partnerLevels[partnerId] || { level: 1, xp: 0, totalXp: 0 };
                progress.level = Math.max(1, Math.floor(v5_num(progress.level) || 1));
                progress.xp = v5_num(progress.xp);
                progress.totalXp = v5_num(progress.totalXp);
                progress.unlockedForms = Array.isArray(progress.unlockedForms) ? progress.unlockedForms : ['base'];
                if (!progress.unlockedForms.includes('base')) progress.unlockedForms.unshift('base');
                progress.activeForm = progress.activeForm || 'base';
                progress.masteryNodes = Array.isArray(progress.masteryNodes) ? progress.masteryNodes : [];
                char.partnerLevels[partnerId] = progress;
                updatePartnerFormUnlocks(char, partnerId);
                return progress;
            }

            function getWeekKey(dateStr) {
                const d = parseLocalDate(dateStr) || new Date(`${dateStr || v5_today()}T00:00:00`);
                const day = d.getDay() || 7;
                d.setDate(d.getDate() + 1 - day);
                return formatLocalDateKey(d);
            }
            window.getWeekKey = getWeekKey;

            function getStoryXPForWorkout(txp, normalizedSession = []) {
                const value = v5_num(txp);
                if (value < 10) return 0;
                const unit = Math.min(1.25, value / STORY_CONFIG.standardWorkoutTXP);
                const categories = new Set((normalizedSession || []).map(item => item.category || item.muscle || item.type).filter(Boolean));
                const variety = Math.min(0.20, Math.max(0, categories.size - 1) * 0.04);
                if (value < STORY_CONFIG.meaningfulWorkoutTXP) {
                    return Math.round(10 * Math.min(unit, STORY_CONFIG.shortSessionCap) * (1 + variety));
                }
                return Math.round(10 * unit * (1 + variety));
            }
            window.getStoryXPForWorkout = getStoryXPForWorkout;

            function awardStoryXP(char, dateStr, workoutStoryXP) {
                ensureV5Character(char);
                const weekKey = getWeekKey(dateStr || v5_today());
                const week = char.storyWeekly[weekKey] || { earned: 0 };
                const remaining = Math.max(0, STORY_CONFIG.weeklyStoryXPCap - v5_num(week.earned));
                const awarded = Math.min(remaining, Math.max(0, v5_num(workoutStoryXP)));
                week.earned = +(v5_num(week.earned) + awarded).toFixed(2);
                char.storyWeekly[weekKey] = week;
                char.storyXP = +(v5_num(char.storyXP) + awarded).toFixed(2);
                return awarded;
            }
            window.awardStoryXP = awardStoryXP;

            function ensureSagaProgress(char, sagaId) {
                ensureV5CharacterShallow(char);
                const saga = v5_getSagaById(sagaId) || SAGAS[0];
                if (!char.sagaProgress[saga.id]) {
                    char.sagaProgress[saga.id] = { status: 'locked', focusXP: 0, unlockedAt: null, clearedAt: null, masteredAt: null };
                }
                char.sagaProgress[saga.id].focusXP = v5_num(char.sagaProgress[saga.id].focusXP);
                return char.sagaProgress[saga.id];
            }
            window.ensureSagaProgress = ensureSagaProgress;

            function ensureV5CharacterShallow(char) {
                if (!char.sagaProgress || typeof char.sagaProgress !== 'object') char.sagaProgress = {};
                if (!char.storyWeekly || typeof char.storyWeekly !== 'object') char.storyWeekly = {};
                if (!Array.isArray(char.completedSagas)) char.completedSagas = [];
            }

            function getV6EquippedState(char) {
                const equippedIds = Array.isArray(char?.equippedTransformations) && char.equippedTransformations.length
                    ? char.equippedTransformations
                    : [char?.activeTransformation || 'base'];
                const states = equippedIds.map(id => getTransformationById(id)).filter(Boolean);
                const strongest = states.sort((a, b) =>
                    Number(b?.powerMultiplier || b?.mult || 1) - Number(a?.powerMultiplier || a?.mult || 1)
                )[0] || getTransformationById('base');
                return {
                    ids: equippedIds,
                    states,
                    strongest,
                    multiplier: Math.max(1, Number(strongest?.powerMultiplier || strongest?.mult || 1))
                };
            }

            function getV6RouteSupportReadiness(char) {
                const abilityCount = Math.min(3, (char?.equippedAbilities || []).filter(id => char?.purchasedAbilities?.[id]).length);
                const partnerCount = Math.min(3, typeof getActivePartners === 'function' ? getActivePartners(char).length : 0);
                const masteryReady = Object.values(char?.transformationMastery || {}).some(value =>
                    Number(value?.xp || value?.totalXp || value || 0) >= 2400
                );
                return Math.min(0.36, abilityCount * 0.05 + partnerCount * 0.04 + (masteryReady ? 0.06 : 0));
            }

            function getV6AbsorptionCount(char, kind) {
                return Object.keys(char?.raceAbsorptions?.[kind]?.absorbed || {}).length;
            }

            function getRaceRoutePowerMultiplier(char) {
                const equipped = getV6EquippedState(char);
                const race = normalizeRaceKey(char?.race);
                const nextSaga = SAGAS.find(saga => !(char?.completedSagas || []).includes(saga.id)) || SAGAS[SAGAS.length - 1];
                const targetState = Math.max(1, Number(SAGA_REBALANCE_BY_ID[nextSaga?.id]?.transformMultiplier) || 1);
                const support = getV6RouteSupportReadiness(char);
                const hasRaceState = expectedRace => equipped.states.some(state => normalizeRaceKey(state?.race) === expectedRace);
                const hasHumanState = equipped.ids.some(id => id.startsWith('human_') || id.startsWith('kaioken_'));
                let equivalent = equipped.multiplier;
                let label = equipped.strongest?.name || 'Base Form';
                let source = 'equipped transformation';

                if (race === 'earthling' && hasHumanState) {
                    equivalent = Math.max(equivalent, targetState * Math.min(1.04, 0.72 + support));
                    label = 'Earthling Potential State';
                    source = 'equipped potential, techniques and mastered support';
                } else if (race === 'namekian' && hasRaceState('namekian')) {
                    equivalent = Math.max(equivalent, targetState * Math.min(1.04, 0.72 + support));
                    label = 'Namekian Assimilation State';
                    source = 'equipped Namekian state and assimilation mastery';
                } else if (race === 'hybrid' && hasRaceState('hybrid')) {
                    equivalent = Math.max(equivalent, targetState * Math.min(1.06, 0.76 + support));
                    label = 'Hybrid Awakening';
                    source = 'equipped awakening and potential mastery';
                } else if (race === 'frieza_race' && hasRaceState('frieza_race')) {
                    equivalent = Math.max(equivalent, targetState * Math.min(1.08, 0.80 + support));
                    label = 'Released Evolution';
                    source = 'equipped released form and control mastery';
                } else if (race === 'android') {
                    const absorptions = getV6AbsorptionCount(char, 'android');
                    const required = targetState <= 130 ? 0 : targetState <= 1000 ? 1 : targetState <= 10000 ? 2 : 3;
                    if (absorptions >= required && (hasRaceState('android') || absorptions > 0)) {
                        equivalent = Math.max(equivalent, targetState * Math.min(1.08, 0.50 + absorptions * 0.12 + support));
                        label = 'Android Evolution State';
                        source = `${absorptions} absorption${absorptions === 1 ? '' : 's'}, equipped evolution and support mastery`;
                    }
                } else if (race === 'majin') {
                    const absorptions = getV6AbsorptionCount(char, 'majin');
                    const required = targetState <= 100 ? 0 : targetState <= 1000 ? 1 : targetState <= 10000 ? 2 : 3;
                    if (absorptions >= required && (absorptions > 0 || equipped.multiplier >= targetState)) {
                        equivalent = Math.max(equivalent, targetState * Math.min(1.10, 0.54 + absorptions * 0.12 + support));
                        label = 'Majin Absorption State';
                        source = `${absorptions} absorption${absorptions === 1 ? '' : 's'} and copied support mastery`;
                    }
                }

                return {
                    multiplier: Math.max(1, roundToSignificantNumber(equivalent, 6)),
                    equippedMultiplier: equipped.multiplier,
                    targetState,
                    label,
                    source,
                    supportReadiness: support
                };
            }

            function getSagaUnlockPowerLevel(char) {
                const base = typeof getBaseDisplayPowerFromStats === 'function'
                    ? getBaseDisplayPowerFromStats(char?.stats || {}, false, getRaceStartingPowerScore(char?.race || 'earthling'))
                    : (typeof getPowerLevelFromStats === 'function' ? getPowerLevelFromStats(char?.stats || {}) : 0);
                const route = getRaceRoutePowerMultiplier(char);
                return Math.max(1, roundToSignificantNumber(base * route.multiplier, 6));
            }
            window.getRaceRoutePowerMultiplier = getRaceRoutePowerMultiplier;
            window.getSagaUnlockPowerLevel = getSagaUnlockPowerLevel;

            function canUnlockSaga(char, saga, index = null) {
                ensureV5CharacterShallow(char);
                if (!saga) return { ok: false, blockers: ['Unknown saga'] };
                const sagaIndex = index === null ? SAGAS.findIndex(item => item.id === saga.id) : index;
                const req = saga.unlockReqs || {};
                const blockers = [];
                if (sagaIndex > 0) {
                    const previous = SAGAS[sagaIndex - 1];
                    const previousStatus = char.sagaProgress?.[previous.id]?.status || ((char.completedSagas || []).includes(previous.id) ? 'cleared' : 'locked');
                    if (!v5_statusAtLeast(previousStatus, 'cleared')) blockers.push(`Clear ${previous.name} first`);
                }
                if (v5_num(char.storyXP) < v5_num(req.storyXP)) {
                    blockers.push(`Story XP ${formatPointValue(char.storyXP)} / ${formatPointValue(req.storyXP)}`);
                }
                const effectiveRequirement = v5_num(req.effectivePL || req.displayPL);
                if (effectiveRequirement > 0 && getSagaUnlockPowerLevel(char) < effectiveRequirement) {
                    blockers.push(`Effective PL ${formatPL(getSagaUnlockPowerLevel(char))} / ${formatPL(effectiveRequirement)}`);
                }
                const godRequirement = v5_num(req.godPL);
                const currentGodPL = typeof getGodPowerLevelFromStats === 'function' ? getGodPowerLevelFromStats(char?.stats || {}) : 0;
                if (godRequirement > 0 && currentGodPL < godRequirement) {
                    blockers.push(`God Power ${formatPL(currentGodPL)} / ${formatPL(godRequirement)}`);
                }
                return { ok: blockers.length === 0, blockers };
            }
            window.canUnlockSaga = canUnlockSaga;

            function normalizeSagaUnlockChain(char) {
                ensureV5CharacterShallow(char);
                SAGAS.forEach((saga, index) => {
                    const progress = char.sagaProgress?.[saga.id];
                    if (!progress || index === 0) return;
                    const previous = SAGAS[index - 1];
                    const previousStatus = char.sagaProgress?.[previous.id]?.status || ((char.completedSagas || []).includes(previous.id) ? 'cleared' : 'locked');
                    if (!v5_statusAtLeast(previousStatus, 'cleared') && progress.status === 'unlocked') {
                        progress.status = 'locked';
                        progress.unlockedAt = null;
                    }
                });
                char.completedSagas = SAGAS.filter(saga => v5_statusAtLeast(char.sagaProgress?.[saga.id]?.status, 'cleared')).map(saga => saga.id);
                const focus = v5_getSagaById(char.activeSagaFocus);
                if (focus && !v5_statusAtLeast(char.sagaProgress?.[focus.id]?.status, 'unlocked')) {
                    const candidate = SAGAS.find(saga => v5_statusAtLeast(char.sagaProgress?.[saga.id]?.status, 'unlocked')) || SAGAS[0];
                    char.activeSagaFocus = candidate?.id || 'db_pilaf';
                }
            }
            window.normalizeSagaUnlockChain = normalizeSagaUnlockChain;

            function getSagaStatus(char, sagaId) {
                if (!char) return 'locked';
                const saga = v5_getSagaById(sagaId);
                if (!saga) return 'locked';
                const progress = (char.sagaProgress || {})[sagaId];
                if (progress?.status) return progress.status;
                if ((char.completedSagas || []).includes(sagaId)) return 'cleared';
                return canUnlockSaga(char, saga, SAGAS.findIndex(item => item.id === saga.id)).ok ? 'unlocked' : 'locked';
            }
            window.getSagaStatus = getSagaStatus;

            function setSagaStatus(char, sagaId, status) {
                const progress = ensureSagaProgress(char, sagaId);
                const current = progress.status || 'locked';
                if (!SAGA_STATUS_RANK.hasOwnProperty(status)) return false;
                if (SAGA_STATUS_RANK[status] < SAGA_STATUS_RANK[current]) return false;
                progress.status = status;
                if (status !== 'locked' && !progress.unlockedAt) progress.unlockedAt = v5_today();
                if (v5_statusAtLeast(status, 'cleared') && !progress.clearedAt) progress.clearedAt = v5_today();
                if (status === 'mastered' && !progress.masteredAt) progress.masteredAt = v5_today();
                char.completedSagas = SAGAS.filter(saga => v5_statusAtLeast(char.sagaProgress?.[saga.id]?.status, 'cleared')).map(saga => saga.id);
                return true;
            }
            window.setSagaStatus = setSagaStatus;

            function isSagaAtLeast(char, sagaId, status = 'unlocked') {
                return v5_statusAtLeast(getSagaStatus(char, sagaId), status);
            }
            window.isSagaAtLeast = isSagaAtLeast;

            function updateSagaUnlocks(char) {
                ensureV5CharacterShallow(char);
                normalizeSagaUnlockChain(char);
                const newly = [];
                SAGAS.forEach((saga, index) => {
                    const progress = ensureSagaProgress(char, saga.id);
                    if (v5_statusAtLeast(progress.status, 'unlocked')) return;
                    const unlockCheck = canUnlockSaga(char, saga, index);
                    if (unlockCheck.ok) {
                        progress.status = 'unlocked';
                        progress.unlockedAt = progress.unlockedAt || v5_today();
                        newly.push(saga);
                    }
                });
                return newly;
            }
            window.updateSagaUnlocks = updateSagaUnlocks;

            function getNextSagaUnlock(char) {
                ensureV5Character(char);
                return SAGAS.find(saga => !isSagaAtLeast(char, saga.id, 'unlocked')) || null;
            }
            window.getNextSagaUnlock = getNextSagaUnlock;

            function getActiveSagaFocus(char) {
                ensureV5Character(char);
                const saga = v5_getSagaById(char.activeSagaFocus);
                if (saga && isSagaAtLeast(char, saga.id, 'unlocked')) return saga;
                return SAGAS.find(s => isSagaAtLeast(char, s.id, 'unlocked')) || SAGAS[0];
            }
            window.getActiveSagaFocus = getActiveSagaFocus;

            function getNextSagaGate(char) {
                ensureV5Character(char);
                const focus = getActiveSagaFocus(char);
                if (focus && !isSagaAtLeast(char, focus.id, 'cleared')) {
                    return { type: 'clear', label: `Clear ${focus.name}`, saga: focus, reqs: focus.clearReqs || {} };
                }
                const next = getNextSagaUnlock(char);
                if (next) return { type: 'unlock', label: `Unlock ${next.name}`, saga: next, reqs: next.unlockReqs || {} };
                const masterTarget = SAGAS.find(saga => isSagaAtLeast(char, saga.id, 'cleared') && !isSagaAtLeast(char, saga.id, 'mastered'));
                if (masterTarget) return { type: 'master', label: `Master ${masterTarget.name}`, saga: masterTarget, reqs: masterTarget.masterReqs || {} };
                return { type: 'complete', label: 'All sagas mastered', saga: SAGAS[SAGAS.length - 1], reqs: {} };
            }
            window.getNextSagaGate = getNextSagaGate;

            function setActiveSagaFocus(sagaId) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const saga = v5_getSagaById(sagaId);
                if (!saga || !isSagaAtLeast(char, sagaId, 'unlocked')) return v6Alert('That saga is not unlocked yet.');
                char.activeSagaFocus = sagaId;
                saveState();
                renderDashboard();
                renderSagas();
                if (typeof showNotification === 'function') showNotification('Saga Focus Set', saga.name, 'success');
            }
            window.setActiveSagaFocus = setActiveSagaFocus;

            function getFitnessScore(char) {
                const stats = char?.stats || {};
                const includeGKI = isGodKiUnlocked(char);
                return getDisplayPowerScoreFromStats(stats, includeGKI);
            }
            window.getFitnessScore = getFitnessScore;

            function getDisplayPowerScoreFromStats(stats, includeGKI = false) {
                return (v5_num(stats.STR) * 1.10) +
                    (v5_num(stats.END) * 0.95) +
                    (v5_num(stats.AGI) * 1.00) +
                    (v5_num(stats.VIT) * 0.90) +
                    (v5_num(stats.SPI) * 1.15) +
                    (v5_num(stats.TEC) * 1.05) +
                    (includeGKI ? v5_num(stats.GKI) * POWER_CONFIG.gkiWeight : 0);
            }

            function getRaceStartingPowerScore(race = 'earthling') {
                return getDisplayPowerScoreFromStats(getStartingStatsForRace(race), false);
            }

            function getBaseDisplayPowerFromStats(stats, includeGKI = false, baselineScore = 0) {
                const score = Math.max(0, getDisplayPowerScoreFromStats(stats, includeGKI) - v5_num(baselineScore));
                return Math.max(1, roundToSignificantNumber(POWER_CONFIG.seedPL + score, 6));
            }
            window.getDisplayPowerScoreFromStats = getDisplayPowerScoreFromStats;
            window.getRaceStartingPowerScore = getRaceStartingPowerScore;
            window.getBaseDisplayPowerFromStats = getBaseDisplayPowerFromStats;

            getPowerLevelFromStats = function(stats) {
                return getBaseDisplayPowerFromStats(stats || {}, false);
            };

            getGodPowerLevelFromStats = function(stats) {
                const gki = v5_num(stats?.GKI);
                if (gki <= 0) return 0;
                const raw = (gki * 420) + (v5_num(stats?.SPI) * 65) + (v5_num(stats?.TEC) * 45) + (v5_num(stats?.AGI) * 40) + (v5_num(stats?.END) * 30);
                return Math.max(0, Math.round(raw / 10));
            };

            getBasePowerLevel = function(char) {
                return getBaseDisplayPowerFromStats(char?.stats || {}, isGodKiUnlocked(char), getRaceStartingPowerScore(char?.race || 'earthling'));
            };

            function getPrimaryTransformationPowerMultiplier(char) {
                const id = getEquippedTransformations(char)[0] || 'base';
                const trans = getTransformationById(id);
                return Math.max(1, Number(trans?.powerMultiplier || trans?.mult || 1));
            }
            window.getPrimaryTransformationPowerMultiplier = getPrimaryTransformationPowerMultiplier;

            function getStrongestEquippedTransformationPowerMultiplier(char) {
                return Math.max(1, ...getEquippedTransformations(char).map(id => {
                    const trans = getTransformationById(id);
                    return Math.max(1, Number(trans?.powerMultiplier || trans?.mult || 1));
                }));
            }
            window.getStrongestEquippedTransformationPowerMultiplier = getStrongestEquippedTransformationPowerMultiplier;

            getPowerLevel = function(char) {
                ensureV5CharacterShallow(char);
                const base = getBasePowerLevel(char);
                const route = typeof window.getRaceRoutePowerMultiplier === 'function'
                    ? window.getRaceRoutePowerMultiplier(char)
                    : { multiplier: getPrimaryTransformationPowerMultiplier(char) };
                return Math.max(1, roundToSignificantNumber(base * Math.max(1, Number(route.multiplier) || 1), 6));
            };

            function progressionSoftCapIsFree(char) {
                return !!char && typeof isSagaAtLeast === 'function' && isSagaAtLeast(char, PROGRESSION_SOFT_CAP.freeAfterSaga, 'cleared');
            }
            window.progressionSoftCapIsFree = progressionSoftCapIsFree;

            function getProgressionSoftCapTarget(char) {
                ensureV5CharacterShallow(char);
                const targetIndex = SAGAS.findIndex(saga => !isSagaAtLeast(char, saga.id, 'cleared'));
                const safeIndex = targetIndex >= 0 ? targetIndex : SAGAS.length - 1;
                const saga = SAGAS[safeIndex];
                const row = SAGA_REBALANCE_BY_ID[saga?.id] || SAGA_REBALANCE_ROWS[SAGA_REBALANCE_ROWS.length - 1];
                const prevSaga = safeIndex > 0 ? SAGAS[safeIndex - 1] : null;
                const prevRow = prevSaga ? (SAGA_REBALANCE_BY_ID[prevSaga.id] || null) : null;
                const weeks = Math.max(1, v5_num(row.week) - v5_num(prevRow?.week));
                const baseDelta = Math.max(1, v5_num(row.baseEndPL) - v5_num(prevRow?.baseEndPL || POWER_CONFIG.seedPL));
                const weeklyGain = baseDelta / weeks;
                const sessionCap = weeklyGain * PROGRESSION_SOFT_CAP.targetMultiplier / PROGRESSION_SOFT_CAP.sessionsPerWeek;
                return { saga, row, prevRow, weeklyGain, sessionCap };
            }
            window.getProgressionSoftCapTarget = getProgressionSoftCapTarget;

            function applyProgressionEraSoftCapToSession(char, statGains, sessionEntries = []) {
                if (!char || progressionSoftCapIsFree(char)) {
                    return { applied: false, free: true, scale: 1 };
                }
                const target = getProgressionSoftCapTarget(char);
                const rawScore = getDisplayPowerScoreFromStats(statGains || {}, false);
                const cap = Math.max(0.001, v5_num(target.sessionCap));
                if (rawScore <= cap) {
                    return { applied: false, free: false, scale: 1, rawScore, cap, targetSaga: target.saga?.id || null };
                }
                const effectiveScore = cap * Math.pow(rawScore / cap, PROGRESSION_SOFT_CAP.overflowExponent);
                const scale = v5_clamp(effectiveScore / rawScore, 0.02, 1);
                STATS.forEach(stat => {
                    statGains[stat] = +(v5_num(statGains[stat]) * scale).toFixed(4);
                });
                (sessionEntries || []).forEach(item => {
                    if (!item?.gains) return;
                    STATS.forEach(stat => {
                        item.gains[stat] = +(v5_num(item.gains[stat]) * scale).toFixed(4);
                    });
                });
                return {
                    applied: true,
                    free: false,
                    scale: +scale.toFixed(4),
                    rawScore: +rawScore.toFixed(4),
                    effectiveScore: +effectiveScore.toFixed(4),
                    cap: +cap.toFixed(4),
                    targetSaga: target.saga?.id || null
                };
            }
            window.applyProgressionEraSoftCapToSession = applyProgressionEraSoftCapToSession;

            getGodPowerLevel = function(char) {
                if (!isGodKiUnlocked(char)) return 0;
                const trans = getActiveTransformation(char);
                const godMult = trans?.tags?.includes('god') ? Math.max(1, Math.sqrt(Number(trans.powerMultiplier || trans.mult || 1)) / 6) : 1;
                return Math.round(getGodPowerLevelFromStats(char?.stats || {}) * godMult);
            };

            function getTransformationStatVector(trans) {
                if (!trans || trans.id === 'base') return v5_statMap(1);
                const mult = Math.max(1, Number(trans.powerMultiplier || trans.mult || 1));
                const baseScale = Math.max(1, Math.pow(mult, 0.28));
                const profile = { STR: 1, END: 1, AGI: 1, VIT: 1, SPI: 1, TEC: 1, GKI: 1, ...(trans.statProfile || {}) };
                const vector = {};
                STATS.forEach(stat => {
                    const profileValue = v5_clamp(v5_num(profile[stat]) || 1, 0.45, 1.85);
                    vector[stat] = Math.max(1, baseScale * (0.72 + profileValue * 0.28));
                    if (stat === 'GKI' && !trans.tags?.includes('god')) vector[stat] = 1;
                });
                return vector;
            }

            getEffectiveStatsForTransformation = function(char, transformationId = 'base') {
                const baseStats = { ...v5_statMap(0), ...(char?.stats || {}) };
                const trans = getTransformationById(transformationId);
                const vector = getTransformationStatVector(trans);
                const effective = {};
                STATS.forEach(stat => {
                    effective[stat] = +(v5_num(baseStats[stat]) * (vector[stat] || 1)).toFixed(4);
                });
                if (!isGodKiUnlocked(char)) effective.GKI = 0;
                return effective;
            };

            getEffectiveStats = function(char) {
                return getEffectiveStatsForTransformation(char, getActiveTransformation(char).id);
            };

            getTransformationStatMultipliers = function(trans) {
                return getTransformationStatVector(trans);
            };

            function getEquippedTransformations(char) {
                ensureV5CharacterShallow(char);
                if (!Array.isArray(char.equippedTransformations)) char.equippedTransformations = [char.activeTransformation || 'base'];
                if (!char.equippedTransformations.length) char.equippedTransformations = ['base'];
                const unlocked = new Set(getUnlockedTransformationIds(char));
                const available = new Set(getAvailableTransformations(char).map(trans => trans.id));
                return char.equippedTransformations
                    .filter((id, idx, arr) => id && arr.indexOf(id) === idx && getTransformationById(id) && (id === 'base' || (unlocked.has(id) && available.has(id))))
                    .slice(0, getTransformationSlotLimit(char));
            }
            window.getEquippedTransformations = getEquippedTransformations;

            function ensureTransformationMasteryState(char) {
                if (!char) return {};
                if (!char.transformationMastery || typeof char.transformationMastery !== 'object') char.transformationMastery = {};
                const ids = new Set([...(char.unlockedTransformations || []), ...(char.equippedTransformations || [])]);
                ids.forEach(id => {
                    if (!id || !getTransformationById(id)) return;
                    const current = char.transformationMastery[id];
                    if (!current || typeof current !== 'object') char.transformationMastery[id] = { xp: 0 };
                    char.transformationMastery[id].xp = Math.max(0, v5_num(char.transformationMastery[id].xp));
                });
                if (!char.transformationMastery.base) char.transformationMastery.base = { xp: TRANSFORMATION_MASTERY_RANKS[TRANSFORMATION_MASTERY_RANKS.length - 1].xp };
                return char.transformationMastery;
            }
            window.ensureTransformationMasteryState = ensureTransformationMasteryState;

            function getTransformationMasteryXP(char, transformationId) {
                ensureTransformationMasteryState(char);
                return v5_num(char.transformationMastery?.[transformationId]?.xp);
            }
            window.getTransformationMasteryXP = getTransformationMasteryXP;

            function getTransformationMasteryRank(char, transformationId) {
                const xp = getTransformationMasteryXP(char, transformationId);
                return [...TRANSFORMATION_MASTERY_RANKS].reverse().find(rank => xp >= rank.xp) || TRANSFORMATION_MASTERY_RANKS[0];
            }
            window.getTransformationMasteryRank = getTransformationMasteryRank;

            function getTransformationMasteryEffectScale(char, transformationId) {
                if (!transformationId || transformationId === 'base') return 1;
                const rank = getTransformationMasteryRank(char, transformationId);
                return Math.max(0.35, 1 + v5_num(rank.effectMod));
            }
            window.getTransformationMasteryEffectScale = getTransformationMasteryEffectScale;

            function awardTransformationMasteryXP(char, txpGained) {
                ensureTransformationMasteryState(char);
                const equipped = getEquippedTransformations(char).filter(id => id && id !== 'base');
                if (!equipped.length) return [];
                const baseGain = Math.max(25, Math.round(v5_num(txpGained) * 0.65));
                const summary = [];
                equipped.forEach((id, index) => {
                    const before = getTransformationMasteryRank(char, id);
                    const slotWeight = index === 0 ? 1 : 0.55;
                    const gained = Math.max(1, Math.round(baseGain * slotWeight));
                    char.transformationMastery[id].xp = +(v5_num(char.transformationMastery[id].xp) + gained).toFixed(2);
                    const after = getTransformationMasteryRank(char, id);
                    summary.push({
                        id,
                        name: getTransformationById(id)?.name || id,
                        xp: gained,
                        beforeRank: before.key,
                        afterRank: after.key,
                        rankedUp: before.key !== after.key
                    });
                });
                return summary;
            }
            window.awardTransformationMasteryXP = awardTransformationMasteryXP;

            getActiveTransformation = function(char) {
                ensureV5Character(char);
                const primary = getEquippedTransformations(char)[0] || char.activeTransformation || 'base';
                char.activeTransformation = primary;
                return getTransformationById(primary) || getTransformationById('base');
            };

            getBestSagaRequirementForm = function(char, saga) {
                ensureV5Character(char);
                const forms = saga?.baseOnly ? ['base'] : getAvailableTransformations(char).map(t => t.id);
                const candidates = forms.map(id => {
                    const trans = getTransformationById(id);
                    const stats = getEffectiveStatsForTransformation(char, id);
                    const pl = Math.round(getBasePowerLevel(char) * Math.max(1, Number(trans?.powerMultiplier || trans?.mult || 1)));
                    const gpl = trans?.tags?.includes('god') ? Math.max(getGodPowerLevel(char), getGodPowerLevelFromStats(stats)) : getGodPowerLevelFromStats(stats);
                    return { trans, stats, pl, gpl };
                });
                return candidates
                    .filter(form => form.pl >= v5_num(saga?.plReq)
                        && (!saga?.gplReq || form.gpl >= v5_num(saga.gplReq))
                        && Object.entries(saga?.statReqs || {}).every(([stat, val]) => v5_num(form.stats[stat]) >= v5_num(val)))
                    .sort((a, b) => b.pl - a.pl)[0] || null;
            };

            getBestAvailablePowerLevel = function(char) {
                ensureV5Character(char);
                const ids = getAvailableTransformations(char).map(t => t.id);
                return Math.max(1, ...ids.map(id => Math.round(getBasePowerLevel(char) * Math.max(1, Number(getTransformationById(id)?.powerMultiplier || getTransformationById(id)?.mult || 1)))));
            };

            getBestAvailableGodPowerLevel = function(char) {
                ensureV5Character(char);
                if (!isGodKiUnlocked(char)) return 0;
                return Math.max(0, ...getAvailableTransformations(char).map(trans => trans.tags?.includes('god') ? getGodPowerLevel(char) : getGodPowerLevelFromStats(char.stats)));
            };

            hasReachedGodTier = function(char) {
                if (!char) return false;
                return SAGAS.some(saga => {
                    if (!isGodTierSaga(saga.id)) return false;
                    const status = char.sagaProgress?.[saga.id]?.status || ((char.completedSagas || []).includes(saga.id) ? 'cleared' : 'locked');
                    return v5_statusAtLeast(status, 'unlocked');
                });
            };

            isGodKiUnlocked = function(char) {
                if (!char) return false;
                return SAGAS.some(saga => {
                    if (!isGodTierSaga(saga.id)) return false;
                    const status = char.sagaProgress?.[saga.id]?.status || ((char.completedSagas || []).includes(saga.id) ? 'cleared' : 'locked');
                    return v5_statusAtLeast(status, 'unlocked');
                });
            };

            getCurrentSaga = function(char) {
                ensureV5Character(char);
                return [...SAGAS].reverse().find(saga => isSagaAtLeast(char, saga.id, 'cleared')) ||
                    [...SAGAS].reverse().find(saga => isSagaAtLeast(char, saga.id, 'unlocked')) ||
                    SAGAS[0];
            };

            getNextSagaTarget = function(char) {
                ensureV5Character(char);
                const target = SAGAS.find(saga => !isSagaAtLeast(char, saga.id, 'cleared')) || SAGAS[SAGAS.length - 1];
                return { saga: target, statReqs: { ...(target?.clearReqs?.stats || target?.statReqs || {}) } };
            };

            function canClearSaga(char, saga) {
                ensureV5Character(char);
                const req = saga?.clearReqs || {};
                const progress = ensureSagaProgress(char, saga.id);
                const blockers = [];
                if (!isSagaAtLeast(char, saga.id, 'unlocked')) blockers.push('Unlock the saga first');
                if (v5_num(char.storyXP) < v5_num(req.storyXP)) blockers.push(`Story XP ${formatPointValue(char.storyXP)} / ${formatPointValue(req.storyXP)}`);
                const effectivePL = getSagaUnlockPowerLevel(char);
                const requiredPL = v5_num(req.effectivePL || req.displayPL);
                if (effectivePL < requiredPL) blockers.push(`Effective PL ${formatPL(effectivePL)} / ${formatPL(requiredPL)}`);
                if (req.godPL && getGodPowerLevel(char) < v5_num(req.godPL)) blockers.push(`God Power ${formatPL(getGodPowerLevel(char))} / ${formatPL(req.godPL)}`);
                if (getFitnessScore(char) < v5_num(req.fitnessScore)) blockers.push(`Fitness score ${Math.floor(getFitnessScore(char))} / ${req.fitnessScore}`);
                if (v5_num(progress.focusXP) < v5_num(req.focusXP)) blockers.push(`Focus XP ${formatPointValue(progress.focusXP)} / ${formatPointValue(req.focusXP)}`);
                Object.entries(req.stats || {}).forEach(([stat, val]) => {
                    if (v5_num(char.stats?.[stat]) < v5_num(val)) blockers.push(`${stat} ${formatStat(char.stats?.[stat] || 0)} / ${val}`);
                });
                return { ok: blockers.length === 0, blockers };
            }
            window.canClearSaga = canClearSaga;

            function clearSagaIfEligible(char, sagaId) {
                const saga = v5_getSagaById(sagaId);
                if (!saga || isSagaAtLeast(char, saga.id, 'cleared')) return false;
                const check = canClearSaga(char, saga);
                if (!check.ok) return false;
                setSagaStatus(char, saga.id, 'cleared');
                awardSagaReward(char, saga.clearReward, `Saga cleared: ${saga.name}`);
                unlockTransformationsAndAbilities(char);
                return true;
            }
            window.clearSagaIfEligible = clearSagaIfEligible;

            function canMasterSaga(char, saga) {
                ensureV5Character(char);
                const req = saga?.masterReqs || {};
                const progress = ensureSagaProgress(char, saga.id);
                const blockers = [];
                if (!isSagaAtLeast(char, saga.id, 'cleared')) blockers.push('Clear the saga first');
                if (v5_num(char.storyXP) < v5_num(req.storyXP)) blockers.push(`Story XP ${formatPointValue(char.storyXP)} / ${formatPointValue(req.storyXP)}`);
                const effectivePL = getSagaUnlockPowerLevel(char);
                const requiredPL = v5_num(req.effectivePL || req.displayPL);
                if (effectivePL < requiredPL) blockers.push(`Effective PL ${formatPL(effectivePL)} / ${formatPL(requiredPL)}`);
                if (req.godPL && getGodPowerLevel(char) < v5_num(req.godPL)) blockers.push(`God Power ${formatPL(getGodPowerLevel(char))} / ${formatPL(req.godPL)}`);
                if (getFitnessScore(char) < v5_num(req.fitnessScore)) blockers.push(`Fitness score ${Math.floor(getFitnessScore(char))} / ${req.fitnessScore}`);
                if (v5_num(progress.focusXP) < v5_num(req.focusXP)) blockers.push(`Focus XP ${formatPointValue(progress.focusXP)} / ${formatPointValue(req.focusXP)}`);
                Object.entries(req.stats || {}).forEach(([stat, val]) => {
                    if (v5_num(char.stats?.[stat]) < v5_num(val)) blockers.push(`${stat} ${formatStat(char.stats?.[stat] || 0)} / ${val}`);
                });
                return { ok: blockers.length === 0, blockers };
            }
            window.canMasterSaga = canMasterSaga;

            function masterSagaIfEligible(char, sagaId) {
                const saga = v5_getSagaById(sagaId);
                if (!saga || getSagaStatus(char, saga.id) === 'mastered') return false;
                const check = canMasterSaga(char, saga);
                if (!check.ok) return false;
                setSagaStatus(char, saga.id, 'mastered');
                awardSagaReward(char, saga.masteryReward, `Saga mastered: ${saga.name}`);
                return true;
            }
            window.masterSagaIfEligible = masterSagaIfEligible;

            function awardSagaReward(char, reward, source) {
                if (!reward) return;
                if (reward.ap) addAbilityPoints(char, reward.ap, source);
                if (reward.tp) {
                    char.trainingPoints = +(v5_num(char.trainingPoints) + v5_num(reward.tp)).toFixed(2);
                    char.tpEarned = +(v5_num(char.tpEarned) + v5_num(reward.tp)).toFixed(2);
                }
                (reward.unlockAbilities || []).forEach(id => {
                    if (getAbilityById(id) && !(char.purchasedAbilities || {})[id]) char.purchasedAbilities[id] = 1;
                });
                (reward.unlockTransformations || []).forEach(id => {
                    if (getTransformationById(id) && !char.unlockedTransformations.includes(id)) char.unlockedTransformations.push(id);
                });
                (reward.unlockPartners || []).forEach(id => {
                    if (getPartnerById(id) && !char.ownedPartners.includes(id)) char.ownedPartners.push(id);
                });
            }

            function addAbilityPoints(char, amount, source = 'Ability reward') {
                const value = +v5_num(amount).toFixed(2);
                if (!value) return 0;
                char.abilityPointsEarned = +(v5_num(char.abilityPointsEarned) + value).toFixed(2);
                char.spEarned = +(v5_num(char.spEarned) + value).toFixed(2);
                char.spFragmentHistory = Array.isArray(char.spFragmentHistory) ? char.spFragmentHistory : [];
                if (value % 1 !== 0 || source !== 'Level reward') {
                    char.spFragmentHistory.push({ date: v5_today(), total: value, source });
                    char.spFragmentHistory = char.spFragmentHistory.slice(-60);
                }
                return value;
            }
            window.addAbilityPoints = addAbilityPoints;

            function getAbilityPoints(char) {
                const earned = Math.max(v5_num(char?.abilityPointsEarned), v5_num(char?.spEarned));
                const spent = Math.max(v5_num(char?.abilityPointsSpent), v5_num(char?.spSpent));
                return Math.max(0, +(earned - spent).toFixed(2));
            }
            window.getAbilityPoints = getAbilityPoints;

            getSkillPoints = function(char) {
                return getAbilityPoints(char);
            };

            function spendAbilityPoints(char, amount) {
                const cost = v5_num(amount);
                if (getAbilityPoints(char) + 1e-9 < cost) return false;
                char.abilityPointsSpent = +(v5_num(char.abilityPointsSpent) + cost).toFixed(2);
                char.spSpent = +(v5_num(char.spSpent) + cost).toFixed(2);
                return true;
            }
            window.spendAbilityPoints = spendAbilityPoints;

            function getAbilityById(id) {
                return ABILITIES.find(ability => ability.id === id) || null;
            }
            window.getAbilityById = getAbilityById;

            function getAbilityXPNeeded(ability, level) {
                const safeLevel = v5_clamp(Math.floor(v5_num(level) || 1), 1, ABILITY_MAX_LEVEL);
                const tax = v5_num(ability?.levelBalance?.xpTax || getAbilityTierConfig(ability).xpTax || 1);
                return Math.round((60 + safeLevel * 2.40 + Math.pow(safeLevel, 1.50) * 0.30) * tax);
            }
            window.getAbilityXPNeeded = getAbilityXPNeeded;

            function ensureAbilityProgress(char, abilityId) {
                if (!char || !abilityId || !getAbilityById(abilityId)) return null;
                if (!char.abilityLevels || typeof char.abilityLevels !== 'object' || Array.isArray(char.abilityLevels)) char.abilityLevels = {};
                const legacyLevel = Math.max(1, Math.floor(v5_num(char.purchasedAbilities?.[abilityId]) || 1));
                const progress = char.abilityLevels[abilityId] || {};
                progress.level = v5_clamp(Math.floor(v5_num(progress.level) || legacyLevel), 1, ABILITY_MAX_LEVEL);
                progress.xp = Math.max(0, v5_num(progress.xp));
                progress.totalXp = Math.max(progress.xp, v5_num(progress.totalXp));
                char.abilityLevels[abilityId] = progress;
                if (char.purchasedAbilities && char.purchasedAbilities[abilityId]) char.purchasedAbilities[abilityId] = progress.level;
                return progress;
            }
            window.ensureAbilityProgress = ensureAbilityProgress;

            function ensureAbilityProgressState(char) {
                if (!char) return char;
                if (!char.abilityLevels || typeof char.abilityLevels !== 'object' || Array.isArray(char.abilityLevels)) char.abilityLevels = {};
                Object.keys(char.abilityLevels).forEach(id => {
                    if (!getAbilityById(id) || !char.purchasedAbilities?.[id]) delete char.abilityLevels[id];
                });
                Object.keys(char.purchasedAbilities || {}).forEach(id => ensureAbilityProgress(char, id));
                return char;
            }
            window.ensureAbilityProgressState = ensureAbilityProgressState;

            function addAbilityXPAndProcessLevelUps(char, abilityId, xpAmount) {
                const ability = getAbilityById(abilityId);
                const progress = ensureAbilityProgress(char, abilityId);
                if (!ability || !progress || progress.level >= ABILITY_MAX_LEVEL) return null;
                const beforeLevel = progress.level;
                const gained = Math.max(0, Math.round(v5_num(xpAmount)));
                progress.xp += gained;
                progress.totalXp += gained;
                let safety = 0;
                while (progress.level < ABILITY_MAX_LEVEL && progress.xp >= getAbilityXPNeeded(ability, progress.level) && safety < ABILITY_MAX_LEVEL) {
                    progress.xp -= getAbilityXPNeeded(ability, progress.level);
                    progress.level += 1;
                    safety += 1;
                }
                progress.xp = +progress.xp.toFixed(2);
                char.purchasedAbilities[abilityId] = progress.level;
                return { id: abilityId, name: ability.name, xp: gained, beforeLevel, afterLevel: progress.level, leveled: progress.level > beforeLevel };
            }
            window.addAbilityXPAndProcessLevelUps = addAbilityXPAndProcessLevelUps;

            function awardAbilityXP(char, txpGained) {
                ensureAbilityProgressState(char);
                const equipped = (char.equippedAbilities || []).slice(0, getAbilitySlotLimit(char)).filter(id => getAbilityById(id) && char.purchasedAbilities?.[id]);
                if (!equipped.length || !(v5_num(txpGained) > 0)) return [];
                const raceMult = getRaceAbilityXPMultiplier(char);
                return equipped.map((abilityId, index) => {
                    const weight = ABILITY_SLOT_XP_WEIGHTS[index] || ABILITY_SLOT_XP_WEIGHTS[ABILITY_SLOT_XP_WEIGHTS.length - 1];
                    return addAbilityXPAndProcessLevelUps(char, abilityId, Math.max(1, v5_num(txpGained) * weight * raceMult));
                }).filter(Boolean);
            }
            window.awardAbilityXP = awardAbilityXP;

            function getAbilityRank(char, abilityId) {
                if (!char?.purchasedAbilities?.[abilityId]) return 0;
                return ensureAbilityProgress(char, abilityId)?.level || Math.max(1, Math.floor(v5_num((char.purchasedAbilities || {})[abilityId])));
            }
            window.getAbilityRank = getAbilityRank;

            function getAbilityRankCost(ability, nextRank) {
                const level = v5_clamp(Math.floor(v5_num(nextRank) || 1), 1, ABILITY_MAX_LEVEL);
                if (level <= 1) return v5_num(ability?.spCost ?? 1);
                const tierTax = v5_num(ability?.levelBalance?.xpTax || getAbilityTierConfig(ability).xpTax || 1);
                const raw = 0.35 + v5_num(ability?.spCost || 1) * 0.18 + tierTax * 0.16 + Math.pow(level, 1.18) * 0.045;
                return +raw.toFixed(2);
            }
            window.getAbilityRankCost = getAbilityRankCost;

            function abilityRequirementsMet(char, ability) {
                const reqs = ability?.reqs || {};
                const blockers = [];
                const sagaStatus = reqs.sagaStatus || (ability?.sagaId ? { [ability.sagaId]: 'unlocked' } : {});
                Object.entries(sagaStatus).forEach(([sagaId, status]) => {
                    if (!isSagaAtLeast(char, sagaId, status || 'unlocked')) blockers.push(`${v5_getSagaById(sagaId)?.name || sagaId} ${status || 'unlocked'}`);
                });
                STATS.forEach(stat => {
                    if (reqs[stat] && v5_num(char.stats?.[stat]) < v5_num(reqs[stat])) blockers.push(`${stat} ${formatStat(char.stats?.[stat] || 0)} / ${reqs[stat]}`);
                });
                const requiredTransformations = Array.isArray(reqs.transformations)
                    ? reqs.transformations
                    : (reqs.transformation ? [reqs.transformation] : []);
                requiredTransformations.forEach(transId => {
                    const unlocked = Array.isArray(char.unlockedTransformations) && char.unlockedTransformations.includes(transId);
                    if (!unlocked) blockers.push(`Unlock ${getTransformationById(transId)?.name || transId}`);
                });
                if (reqs.level && getLevel(char) < reqs.level) blockers.push(`Level ${getLevel(char)} / ${reqs.level}`);
                return { ok: blockers.length === 0, blockers };
            }
            window.abilityRequirementsMet = abilityRequirementsMet;

            function canPurchaseAbility(char, ability) {
                if (!ability) return { ok: false, blockers: ['Missing ability'] };
                if (getAbilityRank(char, ability.id) > 0) return { ok: false, blockers: ['Already purchased'] };
                const req = abilityRequirementsMet(char, ability);
                const cost = getAbilityRankCost(ability, 1);
                if (getAbilityPoints(char) < cost) req.blockers.push(`Need ${formatPointValue(cost)} AP`);
                return { ok: req.blockers.length === 0, blockers: req.blockers };
            }
            window.canPurchaseAbility = canPurchaseAbility;

            purchaseAbility = function(abilityId) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const ability = getAbilityById(abilityId);
                const check = canPurchaseAbility(char, ability);
                if (!check.ok) return v6Alert(check.blockers.join('\n'));
                const cost = getAbilityRankCost(ability, 1);
                if (!spendAbilityPoints(char, cost)) return v6Alert('Not enough Ability Points');
                char.purchasedAbilities[abilityId] = 1;
                ensureAbilityProgress(char, abilityId);
                if (!char.equippedAbilities.includes(abilityId) && char.equippedAbilities.length < getAbilitySlotLimit(char)) char.equippedAbilities.push(abilityId);
                const achievementEvents = checkAndAwardAchievements(char);
                saveState();
                renderAbilities();
                renderDashboard();
                renderAchievements();
                queueGameEvents([
                    { type: 'ability', title: 'Ability Learned', name: ability.name, detail: ability.desc },
                    ...achievementEvents.map(ach => ({ type: 'achievement', title: 'Achievement Unlocked', name: ach.name, detail: ach.desc, reward: ach.reward }))
                ]);
            };

            upgradeAbility = function(abilityId) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const ability = getAbilityById(abilityId);
                if (!ability) return v6Alert('Ability not found');
                const currentRank = getAbilityRank(char, abilityId);
                if (!currentRank) return v6Alert('Purchase the ability first');
                if (currentRank >= (ability.maxRank || ability.ranks || 1)) return v6Alert('Already at max rank');
                const req = abilityRequirementsMet(char, ability);
                if (!req.ok) return v6Alert(req.blockers.join('\n'));
                const cost = getAbilityRankCost(ability, currentRank + 1);
                if (!spendAbilityPoints(char, cost)) return v6Alert('Not enough Ability Points');
                const progress = ensureAbilityProgress(char, abilityId);
                progress.level = Math.min(ABILITY_MAX_LEVEL, currentRank + 1);
                progress.xp = 0;
                char.purchasedAbilities[abilityId] = progress.level;
                saveState();
                renderAbilities();
                renderDashboard();
                if (typeof renderStats === 'function') renderStats();
                showGameEvent({ type: 'ability', title: 'Ability Level Up', name: `${ability.name} Lv ${char.purchasedAbilities[abilityId]}`, detail: 'The technique is stronger now.' });
            };

            function getAbilitySlotLimit(char) {
                return v5_clamp(Math.floor(v5_num(char?.abilitySlots) || ABILITY_LOADOUT_CONFIG.defaultSlots), ABILITY_LOADOUT_CONFIG.defaultSlots, ABILITY_LOADOUT_CONFIG.maxSlots);
            }
            window.getAbilitySlotLimit = getAbilitySlotLimit;

            function canUnlockAbilitySlot(char, slot) {
                const upgrade = ABILITY_LOADOUT_CONFIG.slotUpgrades.find(item => item.slot === slot);
                if (!upgrade) return { ok: false, blockers: ['No slot upgrade found'] };
                const blockers = [];
                if (getAbilitySlotLimit(char) >= slot) blockers.push('Already unlocked');
                if (getAbilityPoints(char) < upgrade.apCost) blockers.push(`Need ${upgrade.apCost} AP`);
                if (upgrade.requiresSaga && !isSagaAtLeast(char, upgrade.requiresSaga, upgrade.requiresStatus || 'unlocked')) blockers.push(`${v5_getSagaById(upgrade.requiresSaga)?.name || upgrade.requiresSaga} ${upgrade.requiresStatus || 'unlocked'}`);
                return { ok: blockers.length === 0, blockers };
            }
            window.canUnlockAbilitySlot = canUnlockAbilitySlot;

            function unlockAbilitySlot(slot) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const check = canUnlockAbilitySlot(char, Number(slot));
                if (!check.ok) return v6Alert(check.blockers.join('\n'));
                const upgrade = ABILITY_LOADOUT_CONFIG.slotUpgrades.find(item => item.slot === Number(slot));
                if (!spendAbilityPoints(char, upgrade.apCost)) return v6Alert('Not enough Ability Points');
                char.abilitySlots = Math.max(getAbilitySlotLimit(char), Number(slot));
                saveState();
                renderAbilities();
                renderDashboard();
            }
            window.unlockAbilitySlot = unlockAbilitySlot;

            function setAbilitySlot(slotIndex, abilityId) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const idx = Math.max(0, Number(slotIndex) || 0);
                if (idx >= getAbilitySlotLimit(char)) return;
                if (!abilityId) {
                    char.equippedAbilities.splice(idx, 1);
                } else {
                    if (!char.purchasedAbilities?.[abilityId]) return v6Alert('Purchase that ability first.');
                    char.equippedAbilities = char.equippedAbilities.filter(id => id !== abilityId);
                    char.equippedAbilities[idx] = abilityId;
                }
                char.equippedAbilities = char.equippedAbilities.filter(Boolean).slice(0, getAbilitySlotLimit(char));
                saveState();
                renderAbilities();
                renderDashboard();
            }
            window.setAbilitySlot = setAbilitySlot;

            function getTransformationSlotLimit(char) {
                return v5_clamp(Math.floor(v5_num(char?.transformationSlots) || TRANSFORMATION_LOADOUT_CONFIG.defaultSlots), TRANSFORMATION_LOADOUT_CONFIG.defaultSlots, TRANSFORMATION_LOADOUT_CONFIG.maxSlots);
            }
            window.getTransformationSlotLimit = getTransformationSlotLimit;

            function canUnlockTransformationSlot(char, slot) {
                const upgrade = TRANSFORMATION_LOADOUT_CONFIG.slotUpgrades.find(item => item.slot === slot);
                if (!upgrade) return { ok: false, blockers: ['No slot upgrade found'] };
                const blockers = [];
                if (getTransformationSlotLimit(char) >= slot) blockers.push('Already unlocked');
                if (getAbilityPoints(char) < upgrade.apCost) blockers.push(`Need ${upgrade.apCost} AP`);
                if (upgrade.requiresSaga && !isSagaAtLeast(char, upgrade.requiresSaga, upgrade.requiresStatus || 'unlocked')) blockers.push(`${v5_getSagaById(upgrade.requiresSaga)?.name || upgrade.requiresSaga} ${upgrade.requiresStatus || 'unlocked'}`);
                if (upgrade.requiresGodKi && !isGodKiUnlocked(char)) blockers.push('God Ki locked');
                return { ok: blockers.length === 0, blockers };
            }
            window.canUnlockTransformationSlot = canUnlockTransformationSlot;

            function unlockTransformationSlot(slot) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const numericSlot = Number(slot);
                const check = canUnlockTransformationSlot(char, numericSlot);
                if (!check.ok) return v6Alert(check.blockers.join('\n'));
                const upgrade = TRANSFORMATION_LOADOUT_CONFIG.slotUpgrades.find(item => item.slot === numericSlot);
                if (!spendAbilityPoints(char, upgrade.apCost)) return v6Alert('Not enough Ability Points');
                char.transformationSlots = Math.max(getTransformationSlotLimit(char), numericSlot);
                saveState();
                renderTransformations();
                renderDashboard();
            }
            window.unlockTransformationSlot = unlockTransformationSlot;

            function setTransformationSlot(slotIndex, transformationId) {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const idx = Math.max(0, Number(slotIndex) || 0);
                if (idx >= getTransformationSlotLimit(char)) return;
                if (!transformationId) transformationId = idx === 0 ? 'base' : '';
                if (transformationId && !getUnlockedTransformationIds(char).includes(transformationId)) return v6Alert('Unlock that transformation first.');
                char.equippedTransformations = char.equippedTransformations.filter((id, pos) => pos === idx || id !== transformationId);
                if (transformationId) char.equippedTransformations[idx] = transformationId;
                else char.equippedTransformations.splice(idx, 1);
                char.equippedTransformations = char.equippedTransformations.filter(Boolean).slice(0, getTransformationSlotLimit(char));
                if (!char.equippedTransformations.length) char.equippedTransformations = ['base'];
                char.activeTransformation = char.equippedTransformations[0];
                saveState();
                renderTransformations();
                renderDashboard();
            }
            window.setTransformationSlot = setTransformationSlot;

            setActiveTransformation = function(id) {
                setTransformationSlot(0, id);
            };

            function createEffectAccumulator() {
                return {
                    statGain: v5_statMap(0),
                    categoryGain: {},
                    typeGain: {},
                    txpGain: 0,
                    tpGain: 0,
                    apGain: 0,
                    storyXPGain: 0,
                    sagaFocusXPGain: 0,
                    partnerXP: { global: 0, byTag: {}, byPartner: {} }
                };
            }
            window.createEffectAccumulator = createEffectAccumulator;

            function addEffects(target, source, scale = 1) {
                if (!source || !target) return target;
                Object.entries(source.statGain || {}).forEach(([stat, value]) => { if (STATS.includes(stat)) target.statGain[stat] = v5_num(target.statGain[stat]) + v5_num(value) * scale; });
                Object.entries(source.categoryGain || {}).forEach(([key, value]) => { target.categoryGain[key] = v5_num(target.categoryGain[key]) + v5_num(value) * scale; });
                Object.entries(source.typeGain || {}).forEach(([key, value]) => { target.typeGain[key] = v5_num(target.typeGain[key]) + v5_num(value) * scale; });
                ['txpGain', 'tpGain', 'apGain', 'storyXPGain', 'sagaFocusXPGain'].forEach(key => { target[key] = v5_num(target[key]) + v5_num(source[key]) * scale; });
                [source.partnerXP, source.partnerXp, source.characterXP, source.characterXp].filter(Boolean).forEach(xpSource => {
                    const xpObject = typeof xpSource === 'number' ? {} : xpSource;
                    target.partnerXP.global += v5_num(typeof xpSource === 'number' ? xpSource : xpObject.global) * scale;
                    Object.entries(xpObject.byTag || {}).forEach(([tag, value]) => { target.partnerXP.byTag[tag] = v5_num(target.partnerXP.byTag[tag]) + v5_num(value) * scale; });
                    Object.entries(xpObject.byPartner || {}).forEach(([id, value]) => { target.partnerXP.byPartner[id] = v5_num(target.partnerXP.byPartner[id]) + v5_num(value) * scale; });
                });
                return target;
            }
            window.addEffects = addEffects;

            function clampEffectAccumulator(effects, char = getActiveCharacter()) {
                const cap = isGodKiUnlocked(char) ? EFFECT_CAPS.statGain.postGodKi : EFFECT_CAPS.statGain.preGodKi;
                STATS.forEach(stat => { effects.statGain[stat] = v5_clamp(v5_num(effects.statGain[stat]), -0.25, cap); });
                Object.keys(effects.categoryGain).forEach(key => { effects.categoryGain[key] = v5_clamp(v5_num(effects.categoryGain[key]), -0.25, cap); });
                Object.keys(effects.typeGain).forEach(key => { effects.typeGain[key] = v5_clamp(v5_num(effects.typeGain[key]), -0.25, cap); });
                effects.txpGain = v5_clamp(effects.txpGain, -0.25, EFFECT_CAPS.txpGain);
                effects.tpGain = v5_clamp(effects.tpGain, -0.25, EFFECT_CAPS.tpGain);
                effects.apGain = v5_clamp(effects.apGain, -0.25, EFFECT_CAPS.apGain);
                effects.storyXPGain = 0;
                effects.sagaFocusXPGain = v5_clamp(effects.sagaFocusXPGain, -0.25, EFFECT_CAPS.sagaFocusXP);
                effects.partnerXP.global = v5_clamp(effects.partnerXP.global, -0.25, EFFECT_CAPS.partnerXP);
                Object.keys(effects.partnerXP.byTag).forEach(key => { effects.partnerXP.byTag[key] = v5_clamp(effects.partnerXP.byTag[key], -0.25, EFFECT_CAPS.partnerXP); });
                Object.keys(effects.partnerXP.byPartner).forEach(key => { effects.partnerXP.byPartner[key] = v5_clamp(effects.partnerXP.byPartner[key], -0.25, EFFECT_CAPS.partnerXP); });
                return effects;
            }
            window.clampEffectAccumulator = clampEffectAccumulator;

            function getAbilityRankEffects(ability, rank) {
                return getAbilityScaledEffects(ability, rank);
            }
            window.getAbilityRankEffects = getAbilityRankEffects;

            function getPartnerTags(partner) {
                const tags = new Set(partner?.tags || []);
                const id = String(partner?.id || '').toLowerCase();
                const name = String(partner?.name || '').toLowerCase();
                if (/goku|gohan|goten|pan/.test(id + name)) tags.add('goku_family');
                if (/vegeta|trunks|bra/.test(id + name)) tags.add('vegeta_family');
                if (/saiyan|goku|vegeta|gohan|trunks|broly|goten|bardock|raditz|nappa/.test(id + name)) tags.add('saiyan');
                if (/piccolo|namek|dende|nail/.test(id + name)) tags.add('namekian');
                if (/krillin|yamcha|tien|chiaotzu|roshi|earthling/.test(id + name)) tags.add('earthling');
                if (/android|cell|gamma/.test(id + name)) tags.add('android');
                if (/frieza|cooler|king_cold|ginyu|recoome|burter|jeice|guldo/.test(id + name)) tags.add('frieza_force');
                if (/beerus|whis|god|blue|ultra|jiren|toppo|hakai/.test(id + name)) tags.add('god');
                if (/roshi|krillin|yamcha|goku/.test(id + name)) tags.add('turtle_school');
                if (/king_kai/.test(id + name)) tags.add('king_kai');
                if (/majin|buu/.test(id + name)) tags.add('majin');
                return [...tags];
            }
            window.getPartnerTags = getPartnerTags;

            function getSagaAbilityResonanceScale(char, ability) {
                if (!ability) return 1;
                const active = typeof getCurrentSaga === 'function' ? getCurrentSaga(char) : null;
                const rules = SAGA_ABILITY_RESONANCE[active?.id] || [];
                if (!rules.length) return 1;
                const abilityTags = new Set(ability.tags || []);
                let scale = 1;
                rules.forEach(rule => {
                    if ((rule.ids || []).includes(ability.id)) scale = Math.max(scale, v5_num(rule.scale) || 1);
                    if ((rule.tags || []).some(tag => abilityTags.has(tag))) scale = Math.max(scale, v5_num(rule.scale) || 1);
                });
                return scale;
            }
            window.getSagaAbilityResonanceScale = getSagaAbilityResonanceScale;

            function getEquippedAbilityEffects(char, normalizedSession = []) {
                ensureV5Character(char);
                const effects = createEffectAccumulator();
                const activePartners = new Set(getActivePartners(char));
                const activePartnerTags = new Set(getActivePartners(char).flatMap(id => getPartnerTags(getPartnerById(id))));
                const equippedTrans = getEquippedTransformations(char).map(getTransformationById).filter(Boolean);
                const transformationTags = new Set(equippedTrans.flatMap(t => t.tags || []));
                char.equippedAbilities.slice(0, getAbilitySlotLimit(char)).forEach(abilityId => {
                    const ability = getAbilityById(abilityId);
                    const rank = getAbilityRank(char, abilityId);
                    if (!ability || !rank) return;
                    addEffects(effects, getAbilityRankEffects(ability, rank), getSagaAbilityResonanceScale(char, ability));
                    (ability.synergies || []).forEach(syn => {
                        let matched = false;
                        if (syn.withPartner && activePartners.has(syn.withPartner)) matched = true;
                        if (syn.withPartnerTag && activePartnerTags.has(syn.withPartnerTag)) matched = true;
                        if (syn.withTransformationTag && transformationTags.has(syn.withTransformationTag)) matched = true;
                        if (matched) addEffects(effects, syn.bonus, 1);
                    });
                });
                return effects;
            }
            window.getEquippedAbilityEffects = getEquippedAbilityEffects;

            function getTransformationMasteryBonusEffects(char, transformationId) {
                const rank = getTransformationMasteryRank(char, transformationId);
                const rankIndex = TRANSFORMATION_MASTERY_RANKS.findIndex(item => item.key === rank.key);
                const bonus = {};
                if (rankIndex >= 5) bonus.txpGain = 0.01;
                if (rankIndex >= 6) bonus.characterXP = { global: 0.02 };
                if (rankIndex >= 7) bonus.apGain = 0.01;
                if (rankIndex >= 8) bonus.tpGain = 0.01;
                if (rankIndex >= 9) bonus.sagaFocusXPGain = 0.03;
                return bonus;
            }

            function getEquippedTransformationEffects(char, normalizedSession = []) {
                ensureV5Character(char);
                const effects = createEffectAccumulator();
                getEquippedTransformations(char).forEach((id, index) => {
                    const trans = getTransformationById(id);
                    const weight = TRANSFORMATION_LOADOUT_CONFIG.slotWeights[index] || 0;
                    const masteryScale = getTransformationMasteryEffectScale(char, id);
                    addEffects(effects, trans?.effects, weight * masteryScale);
                    addEffects(effects, getTransformationMasteryBonusEffects(char, id), weight);
                });
                return effects;
            }
            window.getEquippedTransformationEffects = getEquippedTransformationEffects;

            function getSagaAffinityBonus(saga, normalizedSession = []) {
                if (!saga) return 0;
                const affinities = saga.affinities || {};
                let bonus = 0;
                const entries = normalizedSession || [];
                const cats = new Set(entries.map(item => item.category || item.muscle || item.type).filter(Boolean));
                (affinities.categories || []).forEach(cat => { if (cats.has(cat)) bonus += 0.025; });
                const statsTouched = new Set();
                entries.forEach(item => Object.entries(item.weights || item.gains || {}).forEach(([stat, value]) => { if (STATS.includes(stat) && v5_num(value) > 0) statsTouched.add(stat); }));
                (affinities.stats || []).forEach(stat => { if (statsTouched.has(stat)) bonus += 0.025; });
                return Math.min(0.20, bonus);
            }
            window.getSagaAffinityBonus = getSagaAffinityBonus;

            function getSagaBoostEffects(char, normalizedSession = []) {
                ensureV5Character(char);
                const effects = createEffectAccumulator();
                const active = getActiveSagaFocus(char);
                if (active && isSagaAtLeast(char, active.id, 'unlocked')) addEffects(effects, active.focusBoost, 1);
                SAGAS.forEach(saga => {
                    const status = getSagaStatus(char, saga.id);
                    if (status === 'cleared') addEffects(effects, saga.clearReward?.passiveBoost, 0.35);
                    if (status === 'mastered') {
                        addEffects(effects, saga.clearReward?.passiveBoost, 0.35);
                        addEffects(effects, saga.masteryReward?.passiveBoost, 1);
                    }
                });
                return effects;
            }
            window.getSagaBoostEffects = getSagaBoostEffects;

            function getLoadoutEffectTotals(char, normalizedSession = []) {
                ensureV5Character(char);
                const effects = createEffectAccumulator();
                addEffects(effects, getSagaBoostEffects(char, normalizedSession), getRaceSagaEffectMultiplier(char));
                addEffects(effects, getEquippedAbilityEffects(char, normalizedSession), 1);
                addEffects(effects, getEquippedTransformationEffects(char, normalizedSession), 1);
                return clampEffectAccumulator(effects, char);
            }
            window.getLoadoutEffectTotals = getLoadoutEffectTotals;

            function v5_exerciseContext(exercise, inputData) {
                const category = exercise?.category || exercise?.muscle || exercise?.group || exercise?.family || '';
                const type = exercise?.type || '';
                return [{ category, type, name: exercise?.name || '', weights: exercise?.weights || {}, inputs: inputData || {} }];
            }

            const v49_getExerciseStatGains = getExerciseStatGains;
            getExerciseStatGains = function(exercise, inputData, char = getActiveCharacter()) {
                const gains = v49_getExerciseStatGains(exercise, inputData, char);
                const effects = getLoadoutEffectTotals(char, v5_exerciseContext(exercise, inputData));
                const category = exercise?.category || exercise?.muscle || exercise?.group || '';
                const type = exercise?.type || '';
                STATS.forEach(stat => {
                    if (stat === 'GKI' && !isGodKiUnlocked(char)) {
                        gains[stat] = 0;
                        return;
                    }
                    const boost = v5_num(effects.statGain[stat]) + v5_num(effects.categoryGain[category]) + v5_num(effects.typeGain[type]);
                    gains[stat] = +(v5_num(gains[stat]) * (1 + boost)).toFixed(4);
                });
                return gains;
            };

            const v49_getTrainingTXPMultiplier = typeof getTrainingTXPMultiplier === 'function' ? getTrainingTXPMultiplier : null;
            if (v49_getTrainingTXPMultiplier) {
                getTrainingTXPMultiplier = function(char) {
                    const effects = getLoadoutEffectTotals(char, []);
                    return v49_getTrainingTXPMultiplier(char) * (1 + v5_num(effects.txpGain));
                };
            }

            if (typeof getTrainingTPMultiplier === 'function') {
                const v49_getTrainingTPMultiplier = getTrainingTPMultiplier;
                getTrainingTPMultiplier = function(char) {
                    const effects = getLoadoutEffectTotals(char, []);
                    return v49_getTrainingTPMultiplier(char) * (1 + v5_num(effects.tpGain));
                };
            }

            const v49_awardFractionalAbilityPoints = typeof awardFractionalAbilityPoints === 'function' ? awardFractionalAbilityPoints : null;
            if (v49_awardFractionalAbilityPoints) {
                awardFractionalAbilityPoints = function(char, normalizedSession, dateStr) {
                    const result = v49_awardFractionalAbilityPoints(char, normalizedSession, dateStr) || { total: 0 };
                    const effects = getLoadoutEffectTotals(char, normalizedSession || []);
                    const bonus = +(v5_num(result.total) * v5_num(effects.apGain)).toFixed(2);
                    if (bonus > 0) {
                        addAbilityPoints(char, bonus, 'Loadout AP bonus');
                        result.total = +(v5_num(result.total) + bonus).toFixed(2);
                    }
                    return result;
                };
            }

            const v49_awardLevelUps = typeof awardLevelUps === 'function' ? awardLevelUps : null;
            if (v49_awardLevelUps) {
                awardLevelUps = function(char, oldLevel) {
                    const before = Math.max(v5_num(char.abilityPointsEarned), v5_num(char.spEarned));
                    const result = v49_awardLevelUps(char, oldLevel);
                    const after = Math.max(v5_num(char.abilityPointsEarned), v5_num(char.spEarned));
                    if (after < v5_num(char.spEarned)) char.abilityPointsEarned = char.spEarned;
                    if (after === before && v5_num(char.spEarned) > before) char.abilityPointsEarned = char.spEarned;
                    return result;
                };
            }

            const v49_awardPartnerXP = typeof awardPartnerXP === 'function' ? awardPartnerXP : null;
            if (v49_awardPartnerXP) {
                awardPartnerXP = function(char, txpGained) {
                    const effects = getLoadoutEffectTotals(char, []);
                    const active = getActivePartners(char);
                    let bestBonus = v5_num(effects.partnerXP.global);
                    active.forEach(id => {
                        const partner = getPartnerById(id);
                        const tags = getPartnerTags(partner);
                        bestBonus = Math.max(bestBonus, v5_num(effects.partnerXP.byPartner[id]));
                        tags.forEach(tag => { bestBonus = Math.max(bestBonus, v5_num(effects.partnerXP.byTag[tag])); });
                    });
                    return v49_awardPartnerXP(char, Math.round(v5_num(txpGained) * (1 + bestBonus)));
                };
            }

            function awardSagaFocusXP(char, saga, txp, normalizedSession = []) {
                ensureV5Character(char);
                if (!saga || !isSagaAtLeast(char, saga.id, 'unlocked')) return 0;
                const base = Math.max(1, Math.round(v5_num(txp) / 10));
                const affinityBonus = getSagaAffinityBonus(saga, normalizedSession);
                const effects = getLoadoutEffectTotals(char, normalizedSession);
                const gained = Math.round(base * (1 + affinityBonus + v5_num(effects.sagaFocusXPGain)));
                const progress = ensureSagaProgress(char, saga.id);
                progress.focusXP = +(v5_num(progress.focusXP) + gained).toFixed(2);
                return gained;
            }
            window.awardSagaFocusXP = awardSagaFocusXP;

            sagaRequirementsMet = function(char, saga) {
                return canClearSaga(char, saga).ok;
            };

            completeReachableSagas = function(char) {
                ensureV5Character(char);
                updateSagaUnlocks(char);
                const completed = [];
                const active = getActiveSagaFocus(char);
                const candidates = [active, SAGAS.find(saga => getSagaStatus(char, saga.id) === 'unlocked')].filter(Boolean);
                candidates.forEach(saga => {
                    if (!completed.some(s => s.id === saga.id) && clearSagaIfEligible(char, saga.id)) completed.push(saga);
                });
                return completed;
            };

            function masterReachableSagas(char) {
                ensureV5Character(char);
                const mastered = [];
                const active = getActiveSagaFocus(char);
                if (active && masterSagaIfEligible(char, active.id)) mastered.push(active);
                return mastered;
            }
            window.masterReachableSagas = masterReachableSagas;

            trainingSagaMet = function(char, sagaId, status = 'unlocked') {
                if (sagaId && typeof sagaId === 'object') sagaId = sagaId.sagaId;
                if (!sagaId) return true;
                return isSagaAtLeast(char, sagaId, status);
            };

            partnerSagaMet = function(char, sagaId, status = 'unlocked') {
                if (sagaId && typeof sagaId === 'object') sagaId = sagaId.sagaReq;
                if (!sagaId) return true;
                return isSagaAtLeast(char, sagaId, status);
            };

            applyRestDayAdjustments = function(char) {
                if (!char) return;
                if (!isGodKiUnlocked(char) && char.stats) char.stats.GKI = 0;
            };

            const v49_checkAndAwardMilestones = typeof checkAndAwardMilestones === 'function' ? checkAndAwardMilestones : null;
            if (v49_checkAndAwardMilestones) {
                checkAndAwardMilestones = function(char) {
                    const oldGPL = char.gplMilestones ? [...char.gplMilestones] : [];
                    if (!isGodKiUnlocked(char)) char.gplMilestones = [];
                    const events = v49_checkAndAwardMilestones(char) || [];
                    if (!isGodKiUnlocked(char)) {
                        char.gplMilestones = oldGPL;
                        return events.filter(event => !String(event?.id || event?.label || '').toLowerCase().includes('gpl'));
                    }
                    return events;
                };
            }

            unlockTransformationsAndAbilities = function(char) {
                ensureV5Character(char);
                const level = getLevel(char);
                TRANSFORMATIONS.forEach(trans => {
                    if (!char.unlockedTransformations.includes(trans.id)) {
                        const reqs = trans.reqs || {};
                        const sagaOk = !reqs.sagaId || isSagaAtLeast(char, reqs.sagaId, reqs.sagaStatus || (trans.tags?.includes('god') ? 'unlocked' : 'cleared'));
                        const levelOk = !reqs.level || level >= reqs.level;
                        const statsOk = STATS.every(stat => !reqs[stat] || v5_num(char.stats[stat]) >= v5_num(reqs[stat]));
                        const godOk = !trans.tags?.includes('god') || isGodKiUnlocked(char);
                        if (sagaOk && levelOk && statsOk && godOk) char.unlockedTransformations.push(trans.id);
                    }
                });
            };

            function getPartnerSupportScaleV5(partner, progress, isMain = false) {
                const level = Math.max(1, Number(progress?.level || 1));
                const tier = Math.max(1, Number(partner?.powerTier || Math.log10(Number(partner?.canonPL || 1) + 10)));
                const tierScale = 1 + 0.04 * Math.log2(tier + 1);
                const levelScale = 1 + 0.018 * Math.sqrt(level);
                const formScale = getPartnerSupportFormScale(partner, progress);
                const mainScale = isMain ? 1.15 : 1.0;
                return tierScale * levelScale * formScale * mainScale;
            }
            window.getPartnerSupportScaleV5 = getPartnerSupportScaleV5;

            function getPartnerSupportFormScale(partner, progress) {
                const form = getPartnerActiveForm(partner?.id, progress);
                if (!form) return 1;
                return 1 + Math.min(0.25, Math.log10(Math.max(1, Number(form.powerMultiplier || 1))) * 0.06);
            }
            window.getPartnerSupportFormScale = getPartnerSupportFormScale;

            getPartnerLevelEffectScale = function(partner, progress, isMain = false) {
                return getPartnerSupportScaleV5(partner, progress, isMain);
            };

            if (typeof getPartnerPowerEffectScale === 'function') {
                getPartnerPowerEffectScale = function(partner, progress, isMain = false) {
                    return getPartnerSupportScaleV5(partner, progress, isMain);
                };
            }

            function getPartnerXPNeeded(partner, level) {
                const tier = Math.max(1, Number(partner?.powerTier || 1));
                const tierTax = 1 + 0.025 * Math.log2(tier + 1);
                return Math.round((25 + 0.45 * level + 0.002 * level * level) * tierTax);
            }
            window.getPartnerXPNeeded = getPartnerXPNeeded;

            function getPartnerActiveForm(partnerId, progress) {
                const forms = PARTNER_FORMS[partnerId] || [{ id: 'base', name: 'Base', level: 1, powerMultiplier: 1 }];
                const activeId = progress?.activeForm || 'base';
                return forms.find(form => form.id === activeId) || forms[0];
            }
            window.getPartnerActiveForm = getPartnerActiveForm;

            function getPartnerUnlockedForms(char, partnerId) {
                const progress = ensurePartnerProgressV5(char, partnerId);
                return progress.unlockedForms;
            }
            window.getPartnerUnlockedForms = getPartnerUnlockedForms;

            function updatePartnerFormUnlocks(char, partnerId) {
                const progress = char.partnerLevels?.[partnerId];
                if (!progress) return [];
                const forms = PARTNER_FORMS[partnerId] || [];
                const unlocked = [];
                forms.forEach(form => {
                    const levelOk = progress.level >= v5_num(form.level || 1);
                    const sagaOk = !form.requiresSaga || isSagaAtLeast(char, form.requiresSaga, form.requiresStatus || 'unlocked');
                    if (levelOk && sagaOk && !progress.unlockedForms.includes(form.id)) {
                        progress.unlockedForms.push(form.id);
                        unlocked.push(form);
                    }
                });
                if (!progress.unlockedForms.includes(progress.activeForm)) progress.activeForm = progress.unlockedForms[0] || 'base';
                return unlocked;
            }
            window.updatePartnerFormUnlocks = updatePartnerFormUnlocks;

            function setPartnerActiveForm(partnerId, formId) {
                const char = getActiveCharacter();
                const progress = ensurePartnerProgressV5(char, partnerId);
                if (!progress.unlockedForms.includes(formId)) return v6Alert('That partner form is locked.');
                progress.activeForm = formId;
                saveState();
                renderCharacter();
                renderDashboard();
            }
            window.setPartnerActiveForm = setPartnerActiveForm;

            function getPartnerDisplayPL(partner, progress) {
                const basePL = Math.max(1, Number(partner?.canonPL || 1));
                const level = Math.max(1, Number(progress?.level || 1));
                const activeForm = getPartnerActiveForm(partner?.id, progress);
                const formMult = Number(activeForm?.powerMultiplier || 1);
                return Math.round(basePL * Math.pow(1.045, level - 1) * formMult);
            }
            window.getPartnerDisplayPL = getPartnerDisplayPL;

            const v49_completeWorkout = completeWorkout;
            completeWorkout = function() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const beforeLogLength = (char.workoutLog || []).length;
                v49_completeWorkout();
                const activeChar = getActiveCharacter();
                ensureV5Character(activeChar);
                if ((activeChar.workoutLog || []).length <= beforeLogLength) return;
                const entry = activeChar.workoutLog[activeChar.workoutLog.length - 1];
                const normalized = (entry.exercises || []).map(ex => {
                    try { return typeof normalizeWorkoutEntry === 'function' ? normalizeWorkoutEntry(ex) : ex; }
                    catch (err) { return ex; }
                });
                const rawStory = getStoryXPForWorkout(entry.totalTXP, normalized);
                const storyAwarded = awardStoryXP(activeChar, entry.date, rawStory);
                const focusSaga = getActiveSagaFocus(activeChar);
                const focusAwarded = awardSagaFocusXP(activeChar, focusSaga, entry.totalTXP, normalized);
                const abilityXpSummary = awardAbilityXP(activeChar, entry.totalTXP);
                const transformationXpSummary = awardTransformationMasteryXP(activeChar, entry.totalTXP);
                const newlyUnlocked = updateSagaUnlocks(activeChar);
                const newlyCleared = completeReachableSagas(activeChar);
                if (newlyCleared.length) {
                    updateSagaUnlocks(activeChar).forEach(saga => {
                        if (!newlyUnlocked.some(item => item.id === saga.id)) newlyUnlocked.push(saga);
                    });
                }
                const newlyMastered = masterReachableSagas(activeChar);
                unlockTransformationsAndAbilities(activeChar);
                entry.storyXP = storyAwarded;
                entry.sagaFocus = focusSaga?.id || null;
                entry.sagaFocusXP = focusAwarded;
                entry.abilityXP = abilityXpSummary.map(item => ({ id: item.id, xp: item.xp, beforeLevel: item.beforeLevel, afterLevel: item.afterLevel }));
                entry.transformationMasteryXP = transformationXpSummary.map(item => ({ id: item.id, xp: item.xp, beforeRank: item.beforeRank, afterRank: item.afterRank }));
                if (!isGodKiUnlocked(activeChar)) activeChar.stats.GKI = 0;
                saveState();
                renderDashboard();
                renderSagas();
                renderTransformations();
                renderAbilities();
                renderCharacter();
                const parts = [`+${formatPointValue(storyAwarded)} Story XP`, `+${formatPointValue(focusAwarded)} ${focusSaga?.name || 'Saga'} Focus XP`];
                if (newlyUnlocked.length) parts.push(`Unlocked ${newlyUnlocked.map(s => s.name).join(', ')}`);
                if (newlyCleared.length) parts.push(`Cleared ${newlyCleared.map(s => s.name).join(', ')}`);
                if (newlyMastered.length) parts.push(`Mastered ${newlyMastered.map(s => s.name).join(', ')}`);
                const abilityLevelUps = abilityXpSummary.filter(item => item.leveled);
                const transformationRankUps = transformationXpSummary.filter(item => item.rankedUp);
                if (abilityLevelUps.length) parts.push(`Ability level up: ${abilityLevelUps.map(item => `${item.name} Lv ${item.afterLevel}`).join(', ')}`);
                if (transformationRankUps.length) parts.push(`Transformation mastery: ${transformationRankUps.map(item => `${item.name} ${item.afterRank}`).join(', ')}`);
                if (typeof showNotification === 'function') showNotification('Story Progress', parts.join(' | '), 'success');
                if (typeof queueGameEvents === 'function') {
                    queueGameEvents([
                        ...abilityLevelUps.map(item => ({ type: 'ability', title: 'Ability Level Up', name: `${item.name} Lv ${item.afterLevel}`, detail: `Gained ${item.xp} technique XP from this workout.` })),
                        ...transformationRankUps.map(item => ({ type: 'transform', title: 'Transformation Mastery', name: `${item.name} ${item.afterRank}`, detail: `Gained ${item.xp} mastery XP from this workout.` }))
                    ], 1200);
                }
            };

            function renderEffectSummary(effects) {
                const rows = [];
                const pct = value => {
                    const raw = v5_num(value) * 100;
                    return Math.abs(raw) < 10 ? formatPointValue(+raw.toFixed(1)) : formatPointValue(Math.round(raw));
                };
                STATS.forEach(stat => {
                    if (Math.abs(v5_num(effects.statGain[stat])) >= 0.005) rows.push(`${stat} +${pct(effects.statGain[stat])}%`);
                });
                Object.entries(effects.categoryGain || {}).forEach(([key, value]) => {
                    if (Math.abs(v5_num(value)) >= 0.005) rows.push(`${key} +${pct(value)}%`);
                });
                if (effects.txpGain) rows.push(`TXP +${pct(effects.txpGain)}%`);
                if (effects.apGain) rows.push(`AP +${pct(effects.apGain)}%`);
                if (effects.sagaFocusXPGain) rows.push(`Focus XP +${pct(effects.sagaFocusXPGain)}%`);
                const characterXP = effects.partnerXP || effects.characterXP || {};
                const xpParts = [];
                if (Math.abs(v5_num(characterXP.global)) >= 0.005) xpParts.push(`all +${pct(characterXP.global)}%`);
                Object.entries(characterXP.byTag || {}).forEach(([tag, value]) => {
                    if (Math.abs(v5_num(value)) >= 0.005) xpParts.push(`${tag.replace(/_/g, ' ')} +${pct(value)}%`);
                });
                Object.entries(characterXP.byPartner || {}).forEach(([id, value]) => {
                    if (Math.abs(v5_num(value)) >= 0.005) xpParts.push(`${id.replace(/_/g, ' ')} +${pct(value)}%`);
                });
                if (xpParts.length) rows.push(`Character XP ${xpParts.slice(0, 3).join(', ')}`);
                return rows.slice(0, 10).join(' | ') || 'No equipped effects yet';
            }
            window.renderEffectSummary = renderEffectSummary;

            function renderV5DashboardSupplements() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const currentEl = document.getElementById('currentSagaDisplay');
                if (!currentEl) return;
                const focus = getActiveSagaFocus(char);
                const next = getNextSagaUnlock(char);
                const gate = getNextSagaGate(char);
                const weekKey = getWeekKey(v5_today());
                const weekly = v5_num(char.storyWeekly?.[weekKey]?.earned);
                const focusProgress = ensureSagaProgress(char, focus.id);
                const clear = canClearSaga(char, focus);
                currentEl.querySelector('.v5-story-strip')?.remove();
                currentEl.insertAdjacentHTML('beforeend', `
                    <div class="v5-story-strip">
                        <div class="v5-story-row"><span>Story XP</span><strong>${formatPointValue(char.storyXP)}${gate?.reqs?.storyXP ? ` / ${formatPointValue(gate.reqs.storyXP)}` : ''}</strong></div>
                        <div class="v5-meter"><span style="width:${gate?.reqs?.storyXP ? Math.min(100, char.storyXP / Math.max(1, gate.reqs.storyXP) * 100) : 100}%"></span></div>
                        ${gate?.reqs?.effectivePL || gate?.reqs?.displayPL ? `<div class="v5-story-row"><span>Gate PL</span><strong>${formatPL(getSagaUnlockPowerLevel(char))} / ${formatPL(gate.reqs.effectivePL || gate.reqs.displayPL || 0)}</strong></div>` : ''}
                        <div class="v5-story-row"><span>Weekly cap</span><strong>${formatPointValue(weekly)} / ${STORY_CONFIG.weeklyStoryXPCap}</strong></div>
                        <div class="v5-story-row"><span>Next gate</span><strong>${v5_escape(gate?.label || (next ? next.name : 'All sagas unlocked'))}</strong></div>
                        <label class="v5-loadout-label" for="v5SagaFocusSelect">Active Saga Focus</label>
                        <select id="v5SagaFocusSelect" class="v5-select" onchange="setActiveSagaFocus(this.value)">
                            ${SAGAS.filter(s => isSagaAtLeast(char, s.id, 'unlocked')).map(s => `<option value="${s.id}" ${s.id === focus.id ? 'selected' : ''}>${v5_escape(s.name)}</option>`).join('')}
                        </select>
                        <div class="v5-story-row"><span>Focus XP</span><strong>${formatPointValue(focusProgress.focusXP)} / ${formatPointValue(focus.clearReqs.focusXP)}</strong></div>
                        <div class="v5-mini-note">${clear.ok ? 'Ready to clear this saga.' : `Clear blockers: ${clear.blockers.slice(0, 3).map(v5_escape).join(' | ')}`}</div>
                    </div>
                `);
            }

            const v49_renderDashboard = renderDashboard;
            renderDashboard = function() {
                ensureAllV5Characters();
                v49_renderDashboard();
                renderV5DashboardSupplements();
            };

            let v5SagaSeriesFilter = 'ALL';
            let v5SelectedSagaId = null;

            function v5SagaPct(value, target) {
                return Math.max(0, Math.min(100, Math.round(v5_num(value) / Math.max(1, v5_num(target)) * 100)));
            }

            function v5SagaBannerSrc(saga) {
                const path = `./images/saga_banners/${saga?.id || 'db_pilaf'}.webp`;
                return typeof versionedAsset === 'function' ? versionedAsset(path) : path;
            }

            function v5SagaStatusLabel(status) {
                if (status === 'mastered') return 'Mastered';
                if (status === 'cleared') return 'Cleared';
                if (status === 'unlocked') return 'Available';
                return 'Locked';
            }

            function v5SagaMetric(label, value, target, color = '#73b7ff') {
                const pct = target ? v5SagaPct(value, target) : 100;
                return `<div class="v5-saga-metric">
                    <div class="v5-saga-metric-row"><span>${v5_escape(label)}</span><strong>${v5_escape(value)}${target ? ` / ${v5_escape(target)}` : ''}</strong></div>
                    <div class="v5-saga-meter" style="--meter:${pct}%;--meter-color:${color};"><span></span></div>
                </div>`;
            }

            function v5SagaRequirementRows(char, saga, mode) {
                const req = mode === 'master' ? saga.masterReqs || {} : mode === 'clear' ? saga.clearReqs || {} : saga.unlockReqs || {};
                const rows = [];
                if (req.storyXP) rows.push(['Story XP', formatPointValue(char.storyXP), formatPointValue(req.storyXP), v5_num(char.storyXP) >= v5_num(req.storyXP)]);
                const effectiveRequirement = v5_num(req.effectivePL || req.displayPL);
                if (effectiveRequirement) rows.push([mode === 'unlock' ? 'Entry PL' : 'Effective PL', formatPL(getSagaUnlockPowerLevel(char)), formatPL(effectiveRequirement), getSagaUnlockPowerLevel(char) >= effectiveRequirement]);
                if (req.godPL) rows.push(['God Power', formatPL(getGodPowerLevel(char)), formatPL(req.godPL), getGodPowerLevel(char) >= v5_num(req.godPL)]);
                if (req.focusXP) {
                    const progress = ensureSagaProgress(char, saga.id);
                    rows.push(['Focus XP', formatPointValue(progress.focusXP), formatPointValue(req.focusXP), v5_num(progress.focusXP) >= v5_num(req.focusXP)]);
                }
                if (req.fitnessScore) rows.push(['Fitness Score', Math.floor(getFitnessScore(char)), req.fitnessScore, getFitnessScore(char) >= v5_num(req.fitnessScore)]);
                Object.entries(req.stats || {}).forEach(([stat, val]) => rows.push([stat, formatStat(char.stats?.[stat] || 0), formatStat(val), v5_num(char.stats?.[stat]) >= v5_num(val)]));
                return rows.map(([label, have, need, ok]) => `<div class="v5-saga-req-row ${ok ? 'ready' : 'blocked'}"><span>${v5_escape(label)}</span><strong>${v5_escape(have)} / ${v5_escape(need)}</strong></div>`).join('') || '<div class="v5-mini-note">No extra requirements for this step.</div>';
            }

            function v5SagaRewardText(reward) {
                const parts = [];
                if (reward?.ap) parts.push(`+${formatPointValue(reward.ap)} AP`);
                if (reward?.tp) parts.push(`+${formatPointValue(reward.tp)} TP`);
                if (reward?.sp) parts.push(`+${formatPointValue(reward.sp)} SP`);
                if (reward?.txp) parts.push(`+${formatPointValue(reward.txp)} TXP`);
                return parts.join(', ') || 'Story and unlock progress';
            }

            function v5SagaFocusBoostText(saga) {
                const statBoosts = Object.entries(saga.focusBoost?.statGain || {}).map(([stat, val]) => `${stat} +${Math.round(val * 100)}%`);
                const catBoosts = Object.entries(saga.focusBoost?.categoryGain || {}).map(([cat, val]) => `${cat.replace(/_/g, ' ')} +${Math.round(val * 100)}%`);
                return [...statBoosts, ...catBoosts].slice(0, 6).join(' | ') || 'General story focus';
            }

            function v5SagaUnlockItems(saga) {
                const items = [];
                if (Array.isArray(PARTNER_ROSTER)) {
                    PARTNER_ROSTER.filter(p => p.sagaId === saga.id).slice(0, 8).forEach(p => items.push({ type: 'Partner', name: p.name }));
                }
                if (Array.isArray(ABILITIES)) {
                    ABILITIES.filter(a => a.sagaId === saga.id || a.reqs?.sagaId === saga.id).slice(0, 8).forEach(a => items.push({ type: 'Ability', name: a.name }));
                }
                if (Array.isArray(TRANSFORMATIONS)) {
                    TRANSFORMATIONS.filter(t => t.sagaId === saga.id || t.reqs?.sagaId === saga.id).slice(0, 8).forEach(t => items.push({ type: 'Transformation', name: t.name }));
                }
                if (Array.isArray(TRAINING_BRANCHES)) {
                    TRAINING_BRANCHES.forEach(branch => {
                        const upgrades = (branch.upgrades || []).filter(upgrade => upgrade.sagaId === saga.id);
                        if (upgrades.length) items.push({ type: 'Training', name: `${branch.name}: ${upgrades[0].name}${upgrades.length > 1 ? ` +${upgrades.length - 1}` : ''}` });
                    });
                }
                return items;
            }

            function v5RenderSagaUnlockPreview(saga) {
                const items = v5SagaUnlockItems(saga);
                if (!items.length) return '<div class="v5-mini-note">No direct system unlocks listed for this saga yet.</div>';
                return items.slice(0, 16).map(item => `<div class="v5-saga-unlock-chip"><span>${v5_escape(item.type)}</span><strong>${v5_escape(item.name)}</strong></div>`).join('');
            }

            function v5RenderSagaStoryLog(char, saga) {
                const pack = typeof SAGA_STORY_PACKS !== 'undefined' ? SAGA_STORY_PACKS[saga.id] : null;
                const ratio = typeof getSagaFocusProgressRatio === 'function' ? getSagaFocusProgressRatio(char, saga.id) : 0;
                const entries = pack?.entries?.length ? pack.entries : [
                    { id: `${saga.id}_fallback_start`, triggerProgress: 0, title: `${saga.name} Begins`, summary: [dbzThreeSentences(saga.desc, saga)] },
                    { id: `${saga.id}_fallback_focus`, triggerProgress: 0.5, title: `${saga.name} Pressure`, summary: [`Training focus turns ${saga.name} from a locked target into an earned benchmark.`] },
                    { id: `${saga.id}_fallback_clear`, triggerProgress: 1, title: `${saga.name} Cleared`, summary: [`Clearing ${saga.name} should open the next meaningful tier of the campaign.`] }
                ];
                return entries.map(entry => {
                    const unlocked = typeof hasUnlockedStoryEntry === 'function' ? hasUnlockedStoryEntry(char, entry.id) : ratio >= v5_num(entry.triggerProgress);
                    const open = unlocked || ratio >= v5_num(entry.triggerProgress);
                    const summary = Array.isArray(entry.summary) ? entry.summary.join(' ') : String(entry.summary || '');
                    return `<div class="v5-saga-story-entry ${open ? 'open' : 'locked'}">
                        <div class="v5-kicker">${open ? 'Unlocked' : `At ${Math.round(v5_num(entry.triggerProgress) * 100)}% focus`}</div>
                        <h4>${v5_escape(entry.title)}</h4>
                        <p>${open ? v5_escape(dbzThreeSentences(summary, saga)) : 'Keep training this saga focus to reveal this story beat.'}</p>
                    </div>`;
                }).join('');
            }

            function v5SagaStoryArchiveEntries(saga) {
                const pack = typeof SAGA_STORY_PACKS !== 'undefined' ? SAGA_STORY_PACKS[saga.id] : null;
                return pack?.entries?.length ? pack.entries : [
                    { id: `${saga.id}_fallback_start`, triggerProgress: 0, title: `${saga.name} Begins`, summary: [dbzThreeSentences(saga.desc, saga)] },
                    { id: `${saga.id}_fallback_focus`, triggerProgress: 0.5, title: `${saga.name} Pressure`, summary: [`Training focus turns ${saga.name} from a locked target into an earned benchmark.`] },
                    { id: `${saga.id}_fallback_clear`, triggerProgress: 1, title: `${saga.name} Cleared`, summary: [`Clearing ${saga.name} should open the next meaningful tier of the campaign.`] }
                ];
            }

            function v5RenderCompleteSagaStoryArchive(char) {
                return SAGAS.map(saga => {
                    const progress = ensureSagaProgress(char, saga.id);
                    const status = getSagaStatus(char, saga.id);
                    const ratio = typeof getSagaFocusProgressRatio === 'function' ? getSagaFocusProgressRatio(char, saga.id) : 0;
                    const entries = v5SagaStoryArchiveEntries(saga);
                    const unlocked = entries.filter(entry => (typeof hasUnlockedStoryEntry === 'function' ? hasUnlockedStoryEntry(char, entry.id) : false) || ratio >= v5_num(entry.triggerProgress));
                    const shouldOpen = char.activeSagaFocus === saga.id || status === 'unlocked';
                    return `<details class="v5-saga-archive-item ${status}" ${shouldOpen ? 'open' : ''}>
                        <summary><strong>${v5_escape(saga.name)}</strong><span>${v5SagaStatusLabel(status)} | ${unlocked.length}/${entries.length} story beats</span></summary>
                        <div class="v5-saga-archive-body">
                            <div class="v5-mini-note">Focus XP ${formatPointValue(progress.focusXP)} / ${formatPointValue(saga.clearReqs?.focusXP || 0)} | Clear target ${formatPointValue(saga.clearReqs?.storyXP || 0)} Story XP</div>
                            <div class="v5-saga-story-grid">
                                ${entries.map(entry => {
                                    const open = (typeof hasUnlockedStoryEntry === 'function' ? hasUnlockedStoryEntry(char, entry.id) : false) || ratio >= v5_num(entry.triggerProgress);
                                    const summary = Array.isArray(entry.summary) ? entry.summary.join(' ') : String(entry.summary || '');
                                    return `<div class="v5-saga-story-entry ${open ? 'open' : 'locked'}">
                                        <div class="v5-kicker">${open ? 'Unlocked' : `At ${Math.round(v5_num(entry.triggerProgress) * 100)}% focus`}</div>
                                        <h4>${v5_escape(entry.title)}</h4>
                                        <p>${open ? v5_escape(dbzThreeSentences(summary, saga)) : 'Locked story beat. Focus this saga to reveal it.'}</p>
                                    </div>`;
                                }).join('')}
                            </div>
                        </div>
                    </details>`;
                }).join('');
            }
            window.v5RenderCompleteSagaStoryArchive = v5RenderCompleteSagaStoryArchive;

            function setSagaSeriesFilter(series) {
                v5SagaSeriesFilter = series || 'ALL';
                renderSagas();
            }
            window.setSagaSeriesFilter = setSagaSeriesFilter;

            function selectSagaForDetails(sagaId) {
                v5SelectedSagaId = sagaId;
                renderSagas();
            }
            window.selectSagaForDetails = selectSagaForDetails;

            function focusSagaFromDetails(sagaId) {
                const char = getActiveCharacter();
                if (!isSagaAtLeast(char, sagaId, 'unlocked')) return;
                v5SelectedSagaId = sagaId;
                setActiveSagaFocus(sagaId);
            }
            window.focusSagaFromDetails = focusSagaFromDetails;

            function clearSagaFromDetails(sagaId) {
                const char = getActiveCharacter();
                if (clearSagaIfEligible(char, sagaId)) {
                    updateSagaUnlocks(char);
                    saveState();
                    renderSagas();
                    renderDashboard();
                }
            }
            window.clearSagaFromDetails = clearSagaFromDetails;

            function masterSagaFromDetails(sagaId) {
                const char = getActiveCharacter();
                if (masterSagaIfEligible(char, sagaId)) {
                    saveState();
                    renderSagas();
                    renderDashboard();
                }
            }
            window.masterSagaFromDetails = masterSagaFromDetails;

            renderSagas = function() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const el = document.getElementById('sagasDisplay');
                if (!el) return;
                updateSagaUnlocks(char);
                if (typeof updateAllStoryUnlocks === 'function') updateAllStoryUnlocks(char);
                const activeFocus = getActiveSagaFocus(char);
                const currentSaga = typeof getCurrentSaga === 'function' ? getCurrentSaga(char) : activeFocus;
                const selectedSaga = v5_getSagaById(v5SelectedSagaId) || activeFocus || currentSaga || SAGAS[0];
                const selectedProgress = ensureSagaProgress(char, selectedSaga.id);
                const selectedStatus = getSagaStatus(char, selectedSaga.id);
                const selectedClear = canClearSaga(char, selectedSaga);
                const selectedMaster = canMasterSaga(char, selectedSaga);
                const next = getNextSagaUnlock(char);
                const gate = getNextSagaGate(char);
                const weekKey = typeof getWeekKey === 'function' ? getWeekKey(v5_today()) : '';
                const weekly = v5_num(char.storyWeekly?.[weekKey]?.earned);
                const focusProgress = ensureSagaProgress(char, activeFocus.id);
                const seriesOrder = ['ALL', ...['DB', 'DBZ', 'DBS', 'DAIMA'].filter(series => SAGAS.some(s => s.series === series))];
                const visibleSagas = SAGAS.filter(saga => v5SagaSeriesFilter === 'ALL' || saga.series === v5SagaSeriesFilter);
                const pathCards = visibleSagas.map(saga => {
                    const status = getSagaStatus(char, saga.id);
                    const progress = ensureSagaProgress(char, saga.id);
                    const focus = char.activeSagaFocus === saga.id;
                    const selected = selectedSaga.id === saga.id;
                    return `<button class="v5-saga-node ${status} ${focus ? 'focused' : ''} ${selected ? 'selected' : ''}" onclick="selectSagaForDetails('${saga.id}')">
                        <span>${v5_escape(saga.series || 'Story')} ${saga.order}</span>
                        <strong>${v5_escape(saga.name)}</strong>
                        <small>${v5SagaStatusLabel(status)} | Entry ${formatPL(saga.unlockReqs?.effectivePL || saga.unlockReqs?.displayPL || 0)} | Clear ${formatPL(saga.clearReqs?.effectivePL || saga.clearReqs?.displayPL || 0)}</small>
                        <div class="v5-saga-node-meter" style="--meter:${v5SagaPct(progress.focusXP, saga.clearReqs?.focusXP || 1)}%;"><i></i></div>
                    </button>`;
                }).join('');
                const focusClear = canClearSaga(char, activeFocus);
                const selectedUnlock = canUnlockSaga(char, selectedSaga);
                const selectedBlockers = selectedStatus === 'locked' && !selectedUnlock.ok ? selectedUnlock.blockers : selectedStatus === 'unlocked' && !selectedClear.ok ? selectedClear.blockers : selectedStatus === 'cleared' && !selectedMaster.ok ? selectedMaster.blockers : [];
                el.innerHTML = `
                    <div class="v5-saga-page">
                        <section class="v5-saga-panel v5-saga-current">
                            <h2>Current Saga</h2>
                            <div class="v5-saga-current-grid">
                                <div>
                                    <div class="v5-kicker">${v5_escape(currentSaga?.series || 'Story')} campaign</div>
                                    <h3>${v5_escape(activeFocus.name)}</h3>
                                    <p>${v5_escape(activeFocus.desc || 'Train to advance the story.')}</p>
                                    <div class="v5-saga-status-line"><span class="v5-status ${getSagaStatus(char, activeFocus.id)}">${v5SagaStatusLabel(getSagaStatus(char, activeFocus.id))}</span><strong>Focus boost: ${v5_escape(v5SagaFocusBoostText(activeFocus))}</strong></div>
                                </div>
                                <div class="v5-saga-banner-wrap">
                                    <img src="${v5_escape(v5SagaBannerSrc(activeFocus))}" alt="${v5_escape(activeFocus.name)} banner" onerror="this.style.display='none';this.parentElement.textContent='Saga banner art pending';">
                                </div>
                                <div class="v5-saga-progress-stack">
                                    ${v5SagaMetric('Story XP', formatPointValue(char.storyXP), gate?.reqs?.storyXP ? formatPointValue(gate.reqs.storyXP || 0) : '', '#73b7ff')}
                                    ${v5SagaMetric('Weekly Story Cap', formatPointValue(weekly), formatPointValue(window.STORY_CONFIG?.weeklyStoryXPCap || 0), '#44cc88')}
                                    ${v5SagaMetric('Focus XP', formatPointValue(focusProgress.focusXP), formatPointValue(activeFocus.clearReqs?.focusXP || 0), '#aa44ff')}
                                    ${gate?.reqs?.effectivePL || gate?.reqs?.displayPL ? v5SagaMetric('Gate PL', formatPL(getSagaUnlockPowerLevel(char)), formatPL(gate.reqs.effectivePL || gate.reqs.displayPL || 0), '#ffc400') : ''}
                                    <div class="v5-saga-next-line"><span>Next gate</span><strong>${v5_escape(gate?.label || (next ? next.name : 'All sagas unlocked'))}</strong></div>
                                    <div class="v5-mini-note">${focusClear.ok ? 'This focus is ready to clear.' : `Clear blockers: ${focusClear.blockers.slice(0, 2).map(v5_escape).join(' | ') || 'Training needed'}`}</div>
                                </div>
                            </div>
                        </section>

                        <section class="v5-saga-panel">
                            <h2>Saga Path</h2>
                            <div class="v5-saga-filter-row">
                                ${seriesOrder.map(series => `<button class="btn-small ${v5SagaSeriesFilter === series ? 'btn-success' : ''}" onclick="setSagaSeriesFilter('${series}')">${v5_escape(series === 'ALL' ? 'All' : series)}</button>`).join('')}
                            </div>
                            <div class="v5-saga-path">${pathCards}</div>
                        </section>

                        <section class="v5-saga-panel v5-saga-detail">
                            <h2>Focused Saga</h2>
                            <div class="v5-saga-detail-grid">
                                <div>
                                    <div class="v5-kicker">${v5_escape(selectedSaga.series || 'Story')} | Saga ${selectedSaga.order}</div>
                                    <h3>${v5_escape(selectedSaga.name)}</h3>
                                    <p>${v5_escape(dbzThreeSentences(selectedSaga.desc, selectedSaga))}</p>
                                    <div class="v5-saga-banner-wrap compact">
                                        <img src="${v5_escape(v5SagaBannerSrc(selectedSaga))}" alt="${v5_escape(selectedSaga.name)} banner" onerror="this.style.display='none';this.parentElement.textContent='Saga banner art pending';">
                                    </div>
                                    <div class="v5-button-row">
                                        <button class="btn-small" ${isSagaAtLeast(char, selectedSaga.id, 'unlocked') ? `onclick="focusSagaFromDetails('${selectedSaga.id}')"` : 'disabled'}>${activeFocus.id === selectedSaga.id ? 'Active Focus' : 'Set Focus'}</button>
                                        <button class="btn-small btn-success" ${selectedClear.ok && selectedStatus === 'unlocked' ? `onclick="clearSagaFromDetails('${selectedSaga.id}')"` : 'disabled'}>${selectedClear.ok && selectedStatus === 'unlocked' ? 'Clear Saga' : (selectedStatus === 'locked' ? `Locked: ${(selectedBlockers[0] || 'requirements').replace(/"/g, '&quot;')}` : 'Clear Locked')}</button>
                                        <button class="btn-small" ${selectedMaster.ok && selectedStatus === 'cleared' ? `onclick="masterSagaFromDetails('${selectedSaga.id}')"` : 'disabled'}>${selectedMaster.ok && selectedStatus === 'cleared' ? 'Master Saga' : 'Master Locked'}</button>
                                    </div>
                                    ${selectedBlockers.length ? `<div class="v5-blockers">${selectedBlockers.slice(0, 5).map(v5_escape).join('<br>')}</div>` : ''}
                                </div>
                                <div>
                                    <div class="v5-saga-step-title">Unlock</div>
                                    ${v5SagaRequirementRows(char, selectedSaga, 'unlock')}
                                    <div class="v5-saga-step-title">Clear</div>
                                    ${v5SagaRequirementRows(char, selectedSaga, 'clear')}
                                    <div class="v5-saga-step-title">Master</div>
                                    ${v5SagaRequirementRows(char, selectedSaga, 'master')}
                                </div>
                                <div>
                                    <div class="v5-saga-step-title">Rewards</div>
                                    <div class="v5-saga-reward-row"><span>Clear</span><strong>${v5_escape(v5SagaRewardText(selectedSaga.clearReward))}</strong></div>
                                    <div class="v5-saga-reward-row"><span>Master</span><strong>${v5_escape(v5SagaRewardText(selectedSaga.masteryReward))}</strong></div>
                                    <div class="v5-saga-step-title">Direct Unlocks</div>
                                    <div class="v5-saga-unlock-grid">${v5RenderSagaUnlockPreview(selectedSaga)}</div>
                                </div>
                            </div>
                        </section>

                        <section class="v5-saga-panel">
                            <h2>Story Log</h2>
                            <div class="v5-saga-story-grid">${v5RenderSagaStoryLog(char, selectedSaga)}</div>
                        </section>

                        <section class="v5-saga-panel">
                            <h2>Complete Story Archive</h2>
                            <div class="v5-saga-archive-list">${v5RenderCompleteSagaStoryArchive(char)}</div>
                        </section>
                    </div>
                `;
            };

            function renderAbilityLoadoutPanel(char) {
                const purchased = Object.keys(char.purchasedAbilities || {}).filter(id => getAbilityById(id));
                const slots = getAbilitySlotLimit(char);
                const slotRows = Array.from({ length: ABILITY_LOADOUT_CONFIG.maxSlots }, (_, idx) => {
                    const slot = idx + 1;
                    const unlocked = slot <= slots;
                    const selected = char.equippedAbilities[idx] || '';
                    const upgrade = ABILITY_LOADOUT_CONFIG.slotUpgrades.find(item => item.slot === slot);
                    return `
                        <div class="v5-slot ${unlocked ? '' : 'locked'}">
                            <div class="v5-slot-title">Ability ${slot}</div>
                            ${unlocked ? `
                                <select class="v5-select" onchange="setAbilitySlot(${idx}, this.value)">
                                    <option value="">Empty</option>
                                    ${purchased.map(id => `<option value="${id}" ${selected === id ? 'selected' : ''}>${v5_escape(getAbilityById(id).name)} Lv ${getAbilityRank(char, id)}</option>`).join('')}
                                </select>
                            ` : `
                                <div class="v5-mini-note">Locked${upgrade ? ` | ${upgrade.apCost} AP` : ''}</div>
                                ${upgrade ? `<button class="btn-small" onclick="unlockAbilitySlot(${slot})">Unlock</button>` : ''}
                            `}
                        </div>
                    `;
                }).join('');
                const effects = getLoadoutEffectTotals(char, []);
                return `
                    <div class="v5-loadout-panel">
                        <div class="v5-card-top">
                            <div>
                                <div class="v5-kicker">Build Loadout</div>
                                <h3>Ability Slots ${slots} / ${ABILITY_LOADOUT_CONFIG.maxSlots}</h3>
                            </div>
                            <strong>${formatPointValue(getAbilityPoints(char))} AP</strong>
                        </div>
                        <div class="v5-slot-grid">${slotRows}</div>
                        <div class="v5-mini-note"><strong>Current build:</strong> ${v5_escape(renderEffectSummary(effects))}</div>
                    </div>
                `;
            }

            renderAbilities = function() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const el = document.getElementById('abilitiesDisplay');
                if (!el) return;
                const grouped = {};
                ABILITIES.forEach(ab => {
                    grouped[ab.sagaId || 'db_pilaf'] = grouped[ab.sagaId || 'db_pilaf'] || [];
                    grouped[ab.sagaId || 'db_pilaf'].push(ab);
                });
                let html = renderAbilityLoadoutPanel(char);
                SAGAS.forEach(saga => {
                    const abilities = grouped[saga.id] || [];
                    if (!abilities.length) return;
                    html += `<div class="v5-group-title">${v5_escape(saga.name)} Abilities</div><div class="grid-3">`;
                    abilities.forEach(ability => {
                        const rank = getAbilityRank(char, ability.id);
                        const maxRank = ability.maxRank || ability.ranks || 1;
                        const req = abilityRequirementsMet(char, ability);
                        const purchased = rank > 0;
                        const progress = purchased ? ensureAbilityProgress(char, ability.id) : null;
                        const xpNeeded = purchased && rank < maxRank ? getAbilityXPNeeded(ability, rank) : 0;
                        const xpPct = purchased && xpNeeded ? Math.min(100, v5_num(progress.xp) / xpNeeded * 100) : 100;
                        const equipped = char.equippedAbilities.includes(ability.id);
                        const canBuy = canPurchaseAbility(char, ability);
                        const nextCost = getAbilityRankCost(ability, purchased ? rank + 1 : 1);
                        const effects = getAbilityRankEffects(ability, Math.max(1, rank || 1));
                        html += `
                            <div class="card v5-ability-card ${equipped ? 'equipped' : ''}">
                                ${typeof getArtPanel === 'function' ? getArtPanel(ability.id, req.ok || purchased ? 1 : 0.55, 'ability') : ''}
                                <div class="v5-card-body">
                                    <div class="v5-card-top">
                                        <h3>${v5_escape(ability.name)}</h3>
                                        <span class="v5-status ${purchased ? 'cleared' : req.ok ? 'unlocked' : 'locked'}">${purchased ? `Lv ${rank}/${maxRank}` : req.ok ? 'Available' : 'Locked'}</span>
                                    </div>
                                    <div class="v5-saga-desc">${v5_escape(ability.desc || '')}</div>
                                    <div class="v5-tags">${(ability.tags || []).slice(0, 5).map(tag => `<span>${v5_escape(tag)}</span>`).join('')}</div>
                                    <div class="v5-mini-note">${v5_escape(renderEffectSummary(addEffects(createEffectAccumulator(), effects, 1)))}</div>
                                    ${purchased ? `<div class="v5-mini-note">Technique XP ${rank >= maxRank ? 'MAX' : `${formatPointValue(progress.xp)} / ${formatPointValue(xpNeeded)}`}</div><div class="v5-meter"><span style="width:${xpPct}%"></span></div>` : ''}
                                    ${!req.ok ? `<div class="v5-blockers">${req.blockers.slice(0, 4).map(v5_escape).join('<br>')}</div>` : ''}
                                    <div class="v5-button-row">
                                        ${purchased ? `<button class="btn-small" onclick="setAbilitySlot(${Math.min(char.equippedAbilities.length, getAbilitySlotLimit(char) - 1)}, '${ability.id}')">${equipped ? 'Move' : 'Equip'}</button>` : `<button class="btn-small btn-success" ${canBuy.ok ? `onclick="purchaseAbility('${ability.id}')"` : 'disabled'}>Purchase (${formatPointValue(nextCost)} AP)</button>`}
                                        ${purchased && rank < maxRank ? `<button class="btn-small" onclick="upgradeAbility('${ability.id}')">Focus Level (${formatPointValue(nextCost)} AP)</button>` : ''}
                                    </div>
                                </div>
                            </div>
                        `;
                    });
                    html += `</div>`;
                });
                el.innerHTML = html;
                const spEl = document.getElementById('spAvailDisplay');
                if (spEl) spEl.textContent = formatPointValue(getAbilityPoints(char));
            };

            function renderTransformationMasteryMini(char, transformationId) {
                if (!transformationId || transformationId === 'base') return '<div class="v5-mini-note">Base form has no mastery grind.</div>';
                const rank = getTransformationMasteryRank(char, transformationId);
                const xp = getTransformationMasteryXP(char, transformationId);
                const rankIndex = TRANSFORMATION_MASTERY_RANKS.findIndex(item => item.key === rank.key);
                const next = TRANSFORMATION_MASTERY_RANKS[rankIndex + 1];
                const nextText = next ? `${formatPointValue(xp)} / ${formatPointValue(next.xp)} XP` : 'MAX';
                const mod = Math.round(v5_num(rank.effectMod) * 100);
                return `<div class="v5-mini-note">Mastery: <strong>${v5_escape(rank.label)}</strong> (${mod >= 0 ? '+' : ''}${mod}% effects) | ${nextText}</div>`;
            }

            function renderTransformationLoadoutPanel(char) {
                const slots = getTransformationSlotLimit(char);
                const unlocked = getAvailableTransformations(char);
                const rows = Array.from({ length: TRANSFORMATION_LOADOUT_CONFIG.maxSlots }, (_, idx) => {
                    const slot = idx + 1;
                    const open = slot <= slots;
                    const selected = char.equippedTransformations[idx] || (idx === 0 ? 'base' : '');
                    const upgrade = TRANSFORMATION_LOADOUT_CONFIG.slotUpgrades.find(item => item.slot === slot);
                    return `
                        <div class="v5-slot ${open ? '' : 'locked'}">
                            <div class="v5-slot-title">${idx === 0 ? 'Primary' : `Echo ${idx}`} ${open ? `${Math.round((TRANSFORMATION_LOADOUT_CONFIG.slotWeights[idx] || 0) * 100)}%` : ''}</div>
                            ${open ? `
                                <select class="v5-select" onchange="setTransformationSlot(${idx}, this.value)">
                                    ${idx > 0 ? '<option value="">Empty</option>' : ''}
                                    ${unlocked.map(t => `<option value="${t.id}" ${selected === t.id ? 'selected' : ''}>${v5_escape(t.name)} x${formatPointValue(t.powerMultiplier || t.mult || 1)}</option>`).join('')}
                                </select>
                                ${renderTransformationMasteryMini(char, selected)}
                            ` : `
                                <div class="v5-mini-note">Locked${upgrade ? ` | ${upgrade.apCost} AP` : ''}</div>
                                ${upgrade ? `<button class="btn-small" onclick="unlockTransformationSlot(${slot})">Unlock</button>` : ''}
                            `}
                        </div>
                    `;
                }).join('');
                return `
                    <div class="v5-loadout-panel">
                        <div class="v5-card-top">
                            <div>
                                <div class="v5-kicker">Transformation Loadout</div>
                                <h3>Slots ${slots} / ${TRANSFORMATION_LOADOUT_CONFIG.maxSlots}</h3>
                            </div>
                            <strong>Primary controls displayed PL</strong>
                        </div>
                        <div class="v5-slot-grid">${rows}</div>
                        <div class="v5-mini-note"><strong>Transformation effects:</strong> ${v5_escape(renderEffectSummary(getEquippedTransformationEffects(char, [])))}</div>
                    </div>
                `;
            }

            const v49_renderTransformations = renderTransformations;
            renderTransformations = function() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                v49_renderTransformations();
                const el = document.getElementById('transformationsDisplay');
                if (el) el.insertAdjacentHTML('afterbegin', renderTransformationLoadoutPanel(char));
            };

            const v49_renderCharacter = renderCharacter;
            renderCharacter = function() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                v49_renderCharacter();
                const el = document.getElementById('characterDisplay');
                if (!el) return;
                const active = getActivePartners(char);
                const summary = active.map(id => {
                    const partner = getPartnerById(id);
                    const progress = ensurePartnerProgressV5(char, id);
                    const forms = PARTNER_FORMS[id] || [];
                    const activeForm = getPartnerActiveForm(id, progress);
                    const nextForm = forms.find(form => !progress.unlockedForms.includes(form.id));
                    return `
                        <div class="v5-partner-row">
                            <img src="${getPartnerImageSrc(partner)}" onerror="this.src='${getPartnerPlaceholder(partner)}'" alt="${v5_escape(partner?.name || id)}">
                            <div>
                                <strong>${v5_escape(partner?.name || id)}</strong>
                                <span>Lv ${progress.level} | Partner PL ${formatPL(getPartnerDisplayPL(partner, progress))}</span>
                                <span>Form: ${v5_escape(activeForm?.name || 'Base')}${nextForm ? ` | Next: ${v5_escape(nextForm.name)} at Lv ${nextForm.level}` : ' | Forms complete'}</span>
                            </div>
                        </div>
                    `;
                }).join('');
                el.insertAdjacentHTML('afterbegin', `
                    <div class="v5-loadout-panel">
                        <div class="v5-card-top"><div><div class="v5-kicker">Partner Progression</div><h3>Active Team Forms</h3></div></div>
                        ${summary || '<div class="v5-mini-note">Activate partners to build levels, forms, and synergies.</div>'}
                    </div>
                `);
            };

            function renderBuild() {
                const char = getActiveCharacter();
                ensureV5Character(char);
                const el = document.getElementById('buildDisplay');
                if (!el) return;
                el.innerHTML = `
                    ${renderAbilityLoadoutPanel(char)}
                    ${renderTransformationLoadoutPanel(char)}
                    <div class="v5-loadout-panel">
                        <div class="v5-card-top"><div><div class="v5-kicker">Build Summary</div><h3>Current Effects</h3></div></div>
                        <div class="v5-mini-note">${v5_escape(renderEffectSummary(getLoadoutEffectTotals(char, [])))}</div>
                    </div>
                `;
            }
            window.renderBuild = renderBuild;

            function installV5BuildTab() {
                const nav = document.querySelector('.tab-nav');
                if (nav && !document.querySelector('[data-tab="build"]')) {
                    const btn = document.createElement('button');
                    btn.className = 'tab-btn';
                    btn.dataset.tab = 'build';
                    btn.textContent = 'Build';
                    const abilitiesBtn = document.querySelector('[data-tab="abilities"]');
                    nav.insertBefore(btn, abilitiesBtn || null);
                    btn.addEventListener('click', () => {
                        document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
                        document.querySelectorAll('.tab-content').forEach(c => c.classList.remove('active'));
                        btn.classList.add('active');
                        document.getElementById('build')?.classList.add('active');
                        if (typeof applyTabBg === 'function') applyTabBg('build');
                        renderBuild();
                    });
                }
                if (!document.getElementById('build')) {
                    const section = document.createElement('section');
                    section.id = 'build';
                    section.className = 'tab-content';
                    section.innerHTML = '<h2>Build</h2><div id="buildDisplay"></div>';
                    const abilities = document.getElementById('abilities');
                    (abilities?.parentNode || document.body).insertBefore(section, abilities || null);
                }
            }

            function injectV5Styles() {
                if (document.getElementById('v5Styles')) return;
                const style = document.createElement('style');
                style.id = 'v5Styles';
                style.textContent = `
                    .v5-story-strip,.v5-loadout-panel,.v5-section-intro{margin-top:1rem;padding:1rem;border:1px solid rgba(255,184,46,.35);border-radius:8px;background:linear-gradient(135deg,rgba(5,8,14,.76),rgba(20,13,8,.58));box-shadow:0 10px 30px rgba(0,0,0,.18)}
                    .v5-section-intro{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1rem;color:#f6f1df}.v5-section-intro span{color:#c9c4b8;font-size:.86rem}
                    .v5-story-row,.v5-card-top{display:flex;justify-content:space-between;gap:1rem;align-items:flex-start}.v5-story-row{margin:.35rem 0;color:#dcd6c8;font-size:.84rem}.v5-story-row strong{color:#fff2a8}
                    .v5-meter{height:8px;border-radius:999px;overflow:hidden;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.12);margin:.4rem 0}.v5-meter span{display:block;height:100%;background:linear-gradient(90deg,#ff7a18,#ffe45c,#73b7ff)}
                    .v5-loadout-label,.v5-kicker{display:block;text-transform:uppercase;letter-spacing:.08em;font-size:.72rem;color:#ffb82e;font-weight:700;margin-top:.6rem}.v5-select{width:100%;background:#101622;color:#fff;border:1px solid rgba(255,255,255,.16);border-radius:6px;padding:.58rem}
                    .v5-mini-note{color:#d2cab9;font-size:.8rem;line-height:1.45;margin-top:.55rem}.v5-blockers{margin-top:.65rem;color:#ffb2a8;font-size:.78rem;line-height:1.45;background:rgba(120,20,20,.18);border:1px solid rgba(255,100,80,.24);border-radius:6px;padding:.55rem}
                    .v5-saga-card.focused{border-color:#ffcc44;box-shadow:0 0 0 1px rgba(255,204,68,.45),0 18px 40px rgba(0,0,0,.2)}.v5-saga-card h3,.v5-ability-card h3{margin:0;color:#fff4bf;font-size:1rem}.v5-saga-desc{color:#d8d1c4;font-size:.82rem;line-height:1.45;margin:.5rem 0}
                    .v5-status{display:inline-flex;align-items:center;border-radius:999px;padding:.22rem .55rem;font-size:.72rem;font-weight:800;border:1px solid rgba(255,255,255,.15);white-space:nowrap}.v5-status.locked{color:#aab;background:rgba(120,120,150,.14)}.v5-status.unlocked{color:#73f0a6;background:rgba(48,140,85,.18)}.v5-status.cleared{color:#7fc8ff;background:rgba(64,130,255,.18)}.v5-status.mastered{color:#ffd45f;background:rgba(255,190,30,.18)}
                    .v5-saga-page{display:grid;gap:1.45rem}.v5-saga-panel{border:1px solid rgba(255,196,0,.72);border-radius:8px;background-image:linear-gradient(135deg,rgba(7,10,18,.72),rgba(24,17,10,.62)),url("./images/cover_a.jpg");background-size:cover;background-position:center;box-shadow:0 16px 38px rgba(0,0,0,.28);padding:1rem}.v5-saga-panel h2{margin:0 0 1rem;text-align:center;color:var(--dbz-gold,#ffc400);font-size:1.55rem;text-transform:uppercase;letter-spacing:.04em}.v5-saga-current-grid,.v5-saga-detail-grid{display:grid;grid-template-columns:1.05fr 1fr 1.1fr;gap:1rem;align-items:stretch}.v5-saga-current h3,.v5-saga-detail h3{margin:.25rem 0;color:#fff2a8;font-size:1.45rem}.v5-saga-current p,.v5-saga-detail p{margin:.45rem 0;color:#e8ecff;line-height:1.45}.v5-saga-banner-wrap{min-height:150px;border:1px solid rgba(255,196,0,.45);border-radius:7px;background:rgba(2,5,12,.54);overflow:hidden;display:flex;align-items:center;justify-content:center;color:#ffe082;font-weight:900;text-align:center}.v5-saga-banner-wrap.compact{min-height:112px;margin:.75rem 0}.v5-saga-banner-wrap img{width:100%;height:100%;object-fit:cover;object-position:center}.v5-saga-status-line{display:flex;gap:.55rem;align-items:center;flex-wrap:wrap;margin-top:.7rem}.v5-saga-status-line strong{color:#dbe3ff;font-size:.82rem}.v5-saga-progress-stack{display:grid;gap:.62rem}.v5-saga-metric-row,.v5-saga-next-line,.v5-saga-req-row,.v5-saga-reward-row{display:grid;grid-template-columns:1fr auto;gap:.75rem;align-items:center;color:#dbe3ff;font-size:.84rem}.v5-saga-metric-row strong,.v5-saga-next-line strong,.v5-saga-reward-row strong{color:#fff2a8;text-align:right}.v5-saga-meter,.v5-saga-node-meter{height:8px;border-radius:999px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.12);overflow:hidden}.v5-saga-meter span{display:block;width:var(--meter);height:100%;background:linear-gradient(90deg,var(--meter-color),#fff1a8)}.v5-saga-filter-row{display:flex;gap:.55rem;flex-wrap:wrap;margin-bottom:.9rem}.v5-saga-path{display:grid;grid-template-columns:repeat(auto-fit,minmax(142px,1fr));gap:.65rem}.v5-saga-node{border:1px solid rgba(255,196,0,.34);border-radius:7px;background:rgba(6,9,18,.72);padding:.7rem;text-align:left;color:#f7f0df;min-height:112px;cursor:pointer}.v5-saga-node:hover,.v5-saga-node.selected{border-color:#ffc400;box-shadow:0 0 0 1px rgba(255,196,0,.34)}.v5-saga-node.focused{background:linear-gradient(135deg,rgba(73,49,156,.62),rgba(8,14,26,.76));border-color:#aa44ff}.v5-saga-node.locked{opacity:.72}.v5-saga-node.cleared{border-color:#73b7ff}.v5-saga-node.mastered{border-color:#ffc400;background:rgba(62,49,15,.55)}.v5-saga-node span{display:block;color:#ffcc44;font-size:.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:900}.v5-saga-node strong{display:block;color:#fff;font-size:.9rem;line-height:1.2;margin:.3rem 0;min-height:2.15em}.v5-saga-node small{display:block;color:#cfd7ee;font-size:.72rem}.v5-saga-node-meter{margin-top:.5rem}.v5-saga-node-meter i{display:block;width:var(--meter);height:100%;background:linear-gradient(90deg,#aa44ff,#73b7ff)}.v5-saga-step-title{margin:.1rem 0 .55rem;color:#ffc400;text-transform:uppercase;letter-spacing:.08em;font-size:.78rem;font-weight:1000}.v5-saga-req-row,.v5-saga-reward-row{background:rgba(2,5,12,.44);border:1px solid rgba(255,255,255,.1);border-radius:6px;padding:.5rem .6rem;margin-bottom:.45rem}.v5-saga-req-row.ready{border-color:rgba(68,204,136,.42)}.v5-saga-req-row.blocked{border-color:rgba(255,68,68,.35)}.v5-saga-req-row strong{text-align:right;color:#fff2a8}.v5-saga-unlock-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.45rem}.v5-saga-unlock-chip{border:1px solid rgba(255,255,255,.12);border-radius:6px;background:rgba(0,0,0,.22);padding:.5rem}.v5-saga-unlock-chip span{display:block;color:#73b7ff;font-size:.68rem;text-transform:uppercase;font-weight:900}.v5-saga-unlock-chip strong{display:block;color:#fff2a8;font-size:.82rem;line-height:1.25;margin-top:.2rem}.v5-saga-story-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:.75rem}.v5-saga-story-entry{border:1px solid rgba(255,255,255,.13);border-radius:7px;background:rgba(2,5,12,.46);padding:.85rem;min-height:150px}.v5-saga-story-entry.open{border-color:rgba(255,196,0,.42)}.v5-saga-story-entry.locked{opacity:.72}.v5-saga-story-entry h4{margin:.35rem 0;color:#fff2a8;font-size:1rem}.v5-saga-story-entry p{margin:0;color:#e8ecff;line-height:1.45;font-size:.84rem}@media(max-width:900px){.v5-saga-current-grid,.v5-saga-detail-grid{grid-template-columns:1fr}.v5-saga-banner-wrap{min-height:130px}.v5-saga-panel{padding:.85rem}.v5-saga-panel h2{font-size:1.35rem}}
                    .v5-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:.45rem;margin:.65rem 0}.v5-metrics span,.v5-tags span{font-size:.73rem;color:#f0eadc;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.10);border-radius:999px;padding:.3rem .5rem}.v5-tags{display:flex;gap:.35rem;flex-wrap:wrap;margin:.55rem 0}
                    .v5-button-row{display:flex;gap:.5rem;flex-wrap:wrap;margin-top:.75rem}.v5-slot-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:.75rem;margin:.9rem 0}.v5-slot{padding:.75rem;border:1px solid rgba(255,255,255,.12);background:rgba(0,0,0,.18);border-radius:8px}.v5-slot.locked{opacity:.68}.v5-slot-title{font-size:.77rem;color:#ffcc44;font-weight:800;margin-bottom:.45rem}
                    .v5-group-title{margin:1.5rem 0 .75rem;color:#ffb82e;text-transform:uppercase;letter-spacing:.08em;font-weight:900}.v5-card-body{padding:.85rem}.v5-ability-card.equipped{border-color:#66eeaa;box-shadow:0 0 0 1px rgba(102,238,170,.35)}
                    .v5-partner-row{display:grid;grid-template-columns:52px 1fr;gap:.7rem;align-items:center;padding:.55rem;border:1px solid rgba(255,255,255,.1);border-radius:8px;background:rgba(0,0,0,.16);margin:.5rem 0}.v5-partner-row img{width:52px;height:52px;object-fit:contain;border-radius:8px;background:rgba(255,255,255,.08)}.v5-partner-row span{display:block;color:#d8d1c4;font-size:.78rem;margin-top:.15rem}
                `;
                document.head.appendChild(style);
            }

            const v49_loadState = loadState;
            loadState = async function() {
                const loaded = await v49_loadState();
                ensureAllV5Characters();
                await saveState({ snapshot: false });
                return loaded;
            };

            const v49_saveState = saveState;
            saveState = function(options = {}) {
                ensureAllV5Characters();
                return v49_saveState(options);
            };

            function validateGameDataV5(saveData = state) {
                const errors = [];
                const warnings = [];
                const sagaIds = new Set();
                const sagaOrders = new Set();
                let previousSaga = null;
                SAGAS.forEach((saga, index) => {
                    if (sagaIds.has(saga.id)) errors.push(`Duplicate saga id: ${saga.id}`);
                    sagaIds.add(saga.id);
                    if (sagaOrders.has(saga.order)) warnings.push(`Duplicate saga order: ${saga.order}`);
                    sagaOrders.add(saga.order);
                    if (!saga.unlockReqs || !saga.clearReqs || !saga.masterReqs) errors.push(`Saga missing v5 requirements: ${saga.id}`);
                    if (previousSaga && Number(saga.order || 0) <= Number(previousSaga.order || 0)) warnings.push(`Saga order does not increase: ${previousSaga.id} -> ${saga.id}`);
                    if (previousSaga && v5_num(saga.unlockReqs?.storyXP) < v5_num(previousSaga.clearReqs?.storyXP)) warnings.push(`Saga ${saga.id} can unlock before previous clear Story XP`);
                    if (v5_num(saga.clearReqs?.storyXP) < v5_num(saga.unlockReqs?.storyXP)) errors.push(`Saga ${saga.id} clear Story XP is below unlock Story XP`);
                    if (v5_num(saga.masterReqs?.storyXP) < v5_num(saga.clearReqs?.storyXP)) errors.push(`Saga ${saga.id} master Story XP is below clear Story XP`);
                    if (v5_num(saga.clearReqs?.effectivePL || saga.clearReqs?.displayPL) < v5_num(saga.unlockReqs?.effectivePL || saga.unlockReqs?.displayPL)) warnings.push(`Saga ${saga.id} clear PL is below unlock PL`);
                    if (v5_num(saga.masterReqs?.effectivePL || saga.masterReqs?.displayPL) < v5_num(saga.clearReqs?.effectivePL || saga.clearReqs?.displayPL)) warnings.push(`Saga ${saga.id} master PL is below clear PL`);
                    if (v5_num(saga.masterReqs?.focusXP) < v5_num(saga.clearReqs?.focusXP)) errors.push(`Saga ${saga.id} master Focus XP is below clear Focus XP`);
                    if (saga.id.startsWith('daima_') && (v5_num(saga.unlockReqs?.godPL) || v5_num(saga.gplReq))) errors.push(`Daima saga has God Ki requirement: ${saga.id}`);
                    if (!saga.clearReward) warnings.push(`Saga missing clear reward: ${saga.id}`);
                    if (!saga.masteryReward) warnings.push(`Saga missing mastery reward: ${saga.id}`);
                    previousSaga = saga;
                });
                ABILITIES.forEach(ability => { if (ability.sagaId && !sagaIds.has(ability.sagaId)) errors.push(`Ability ${ability.id} has missing saga ${ability.sagaId}`); });
                TRANSFORMATIONS.forEach(trans => { if (trans.reqs?.sagaId && !sagaIds.has(trans.reqs.sagaId)) errors.push(`Transformation ${trans.id} has missing saga ${trans.reqs.sagaId}`); });
                PARTNER_ROSTER.forEach(partner => {
                    const sagaRef = partner.sagaReq || partner.sagaId;
                    if (sagaRef && !sagaIds.has(sagaRef)) warnings.push(`Partner ${partner.id} has missing saga ${sagaRef}`);
                });
                Object.values(saveData.characters || {}).forEach(char => {
                    (char.equippedAbilities || []).forEach(id => { if (!getAbilityById(id)) errors.push(`${char.name} equipped missing ability ${id}`); });
                    (char.equippedTransformations || []).forEach(id => { if (!getTransformationById(id)) errors.push(`${char.name} equipped missing transformation ${id}`); });
                    if (!isGodKiUnlocked(char) && v5_num(char.stats?.GKI) > 0) warnings.push(`${char.name} has pre-unlock GKI ${char.stats.GKI}`);
                    SAGAS.forEach((saga, index) => {
                        if (index === 0) return;
                        const previous = SAGAS[index - 1];
                        const status = char.sagaProgress?.[saga.id]?.status || 'locked';
                        const previousStatus = char.sagaProgress?.[previous.id]?.status || 'locked';
                        if (v5_statusAtLeast(status, 'unlocked') && !v5_statusAtLeast(previousStatus, 'cleared')) {
                            warnings.push(`${char.name} has ${saga.id} unlocked before ${previous.id} cleared`);
                        }
                    });
                });
                const result = { version: GAME_VERSION, schemaVersion: SAVE_SCHEMA_VERSION, errors, warnings };
                console.table(result.errors.map(message => ({ type: 'error', message })).concat(result.warnings.map(message => ({ type: 'warning', message }))));
                return result;
            }
            window.validateGameDataV5 = validateGameDataV5;

            function balanceSimulatorV5(maxWeeks = 156, workoutsPerWeek = 4, txpPerWorkout = 45) {
                const rows = [];
                const weeklyStory = Math.min(STORY_CONFIG.weeklyStoryXPCap, workoutsPerWeek * getStoryXPForWorkout(txpPerWorkout, [{ category: 'strength' }, { category: 'cardio' }]));
                [2, 4, 5, 6].forEach(pattern => {
                    const storyPerWeek = Math.min(STORY_CONFIG.weeklyStoryXPCap, pattern * getStoryXPForWorkout(txpPerWorkout, [{ category: 'strength' }, { category: 'cardio' }]));
                    rows.push({
                        workoutsPerWeek: pattern,
                        storyXPPerWeek: storyPerWeek,
                        unlockAllWeeks: Math.ceil(STORY_CONFIG.finalSagaUnlockXP / Math.max(1, storyPerWeek)),
                        clearAllWeeks: Math.ceil(STORY_CONFIG.finalSagaClearXP / Math.max(1, storyPerWeek)),
                        note: pattern >= 4 ? 'hits intended story cap pace' : 'slower timeline'
                    });
                });
                console.table(rows);
                return { selectedPattern: { workoutsPerWeek, weeklyStory, maxWeeks }, rows };
            }
            window.balanceSimulatorV5 = balanceSimulatorV5;

